const IDEAS=[
 {id:'evenodd',strand:'Groups',title:'Even and odd',line:'Can they all find a partner?',door:'puz',thing:'strawberries',book:'learned what even and odd mean',
  pages:[
   /* 1. the idea in words, then in a picture */
   {say:`Here is the whole idea in one sentence. <em>Even</em> means everyone can find a partner. <em>Odd</em> means one is left over, all alone. Let's try it with 7 strawberries.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);const items=[];for(let i=0;i<7;i++){const d=dot('in');items.push(d);r.appendChild(d)}await appear(items,'',120);sc.appendChild(el('div','bigword','7'))}},
   {say:`Two and two and two… and look! One strawberry has <em>no partner</em>. So 7 is <em>odd</em>.`,draw:async(sc)=>{const g=el('div','pairgrid');sc.appendChild(g);const items=[];for(let i=0;i<7;i++){const d=dot('in');items.push(d);g.appendChild(d)}for(const d of items){d.classList.remove('in');await wait(140)}await wait(300);items[6].classList.add('alone','glow');sc.appendChild(el('div','bigword','7 is <em>odd</em>'))}},
   {say:`Give it one more friend. Now <em>everyone</em> has a partner, nobody is alone. 8 is <em>even</em>.`,draw:async(sc)=>{const g=el('div','pairgrid');sc.appendChild(g);const items=[];for(let i=0;i<7;i++){const d=dot('');items.push(d);g.appendChild(d)}items[6].classList.add('alone');await wait(500);items[6].classList.remove('alone');const n=dot('in new');g.appendChild(n);await wait(20);n.classList.remove('in');await wait(300);sc.appendChild(el('div','bigword','8 is <em>even</em>'))}},
   /* 2. a second way to see it: two equal teams */
   {say:`Another way to see the same thing. An even number can be split into <em>two equal teams</em>. 8 is 4 and 4. Try 7: it is 4 and 3, not equal. Odd numbers never split evenly.`,draw:async(sc)=>{const mk=(n,label)=>{const a=row(label),b=row('');[a,b].forEach(r=>r.classList.add('wide'));const wrap=el('div','ta');wrap.style.gap='4px';wrap.append(a,b);sc.appendChild(wrap);for(let i=0;i<n;i++)(i%2?b:a).appendChild(dot(''));return [a,b]};const [a8,b8]=mk(8,'8');await wait(900);sc.appendChild(el('div','bigword','4 and 4: <em>even</em>'));await wait(900);const [a7,b7]=mk(7,'7');await wait(700);a7.lastChild.classList.add('alone','glow');sc.appendChild(el('div','bigword','4 and 3: <em>odd</em>'))}},
   /* 3. a third way: counting by twos */
   {say:`A third way. Count by <em>twos</em> from 0: 2, 4, 6, 8, 10. Every number you <em>say</em> is even. Every number you <em>skip</em> is odd.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);const strip=el('div','ways strip');for(let i=0;i<=12;i++)strip.appendChild(el('span','way',i));sc.appendChild(strip);let pos=0;walkTo(w,pos);for(let k=0;k<6;k++){await wait(550);pos+=2;walkTo(w,pos);strip.children[pos].style.background='var(--leaf)';strip.children[pos].style.color='#fff';playNote(pos)}for(let i=1;i<=11;i+=2){strip.children[i].style.background='var(--sun)'}sc.appendChild(el('div','bigword','green: <em>even</em> · yellow: odd'))}},
   /* 4. the pattern */
   {say:`So they take turns, forever: odd, even, odd, even. 1 is odd, 2 is even, 3 is odd, 4 is even… and 0 is <em>even</em>: nobody is alone when there is nobody at all.`,draw:async(sc)=>{const strip=el('div','ways strip');strip.style.maxWidth='340px';for(let i=0;i<=20;i++)strip.appendChild(el('span','way',i));sc.appendChild(strip);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<=20;i++){const c=strip.children[i];c.style.background=i%2?'var(--sun)':'var(--leaf)';c.style.color=i%2?'':'#fff';w.innerHTML=`${i} is <em>${i%2?'odd':'even'}</em>`;playNote(i);await wait(260)}w.innerHTML='odd, even, odd, even…'}},
   /* 5. why the last digit works */
   {say:`What about <em>big</em> numbers, like 23? Here is the secret. Every stick of ten is 5 pairs, so the tens <em>never</em> leave anyone alone. Only the loose ones can. 23 has 3 loose ones: one is alone. 23 is odd.`,draw:async(sc)=>{const rods=el('div','rods');for(let k=0;k<2;k++){const rod=el('div','rod solid');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod)}const g=el('div','pairgrid');sc.append(rods,g);for(let i=0;i<3;i++)g.appendChild(dot(''));sc.appendChild(el('div','bigword','2<span class="ones">3</span>'));await wait(900);g.lastChild.classList.add('alone','glow');sc.appendChild(el('div','bigword','the tens pair up; the <em>3</em> decides'))}},
   {say:`So you only need to look at the <em>last digit</em>. 0, 2, 4, 6, 8 at the end: even. 1, 3, 5, 7, 9 at the end: odd. 148 is even. 1,001 is odd. The front of the number does not matter.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','1<span class="ones">4</span> &nbsp;even'));await wait(500);sc.appendChild(el('div','bigword','14<span class="ones">8</span> &nbsp;even'));await wait(500);sc.appendChild(el('div','bigword','100<span class="ones">1</span> &nbsp;odd'))}},
   /* 6. traps */
   {say:`Two traps. First: <em>odd</em> does not mean strange. 3 is a perfectly ordinary number; it just has one left over. Second: big does not mean even. 99 is big and odd. 2 is small and even. Only the last digit decides.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','9<span class="ones">9</span> big, but <em>odd</em>'));sc.appendChild(el('div','bigword','<span class="ones">2</span> small, but <em>even</em>'))}},
   /* 7. where you meet it */
   {say:`Where you meet it: sharing with a friend. 6 cookies share evenly, 3 each. 7 cookies: 3 each and one left to argue about. Socks and gloves come in pairs. And house numbers: one side of a street is all even, the other all odd.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='30px';sc.appendChild(r);const street=(nums,col)=>{const c=el('div');c.style.cssText='display:flex;flex-direction:column;gap:6px';nums.forEach(n=>{const h=el('div','way',n);h.style.background=col;h.style.color='#fff';c.appendChild(h)});return c};r.append(street([2,4,6,8],'var(--leaf)'),el('div','mirrorline'),street([1,3,5,7],'var(--sun)'));sc.appendChild(el('div','bigword','a street: <em>even</em> side, odd side'))}},
   /* 8. practice, two kinds */
   {say:`Your turn! Drag the strawberries into the pair boxes. Does one end up <em>alone</em>?`,draw:async(sc)=>{const n=pick([5,6,7,8,9]);sc.appendChild(el('div','instr',`${n} strawberries. Pair them up!`));const pb=el('div','pairbox');const zs=zones(n%2?n+1:n);zs.forEach(z=>pb.appendChild(z));const {t,items}=trayOf(n);sc.append(pb,t);const out=el('div','bigword','');sc.appendChild(out);
     items.forEach(d=>makeDraggable(d,{onDrop:()=>{const f=fullCount(zs);if(f===n){const alone=n%2;out.innerHTML=alone?`${n} is <em>odd</em>!`:`${n} is <em>even</em>!`;if(alone){const lastZ=zs.find(z=>z.classList.contains('full')&&(zs.indexOf(z)%2===0)&&!zs[zs.indexOf(z)+1].classList.contains('full'));if(lastZ)lastZ.firstChild.classList.add('alone','glow')}bugs('happy');confetti()}}}))}},
   {say:`Your turn again, no pictures this time. Tap every <em>even</em> number. Remember: look at the last digit.`,draw:async(sc)=>{const nums=shuffle([3,8,11,14,20,27,32,45,56,99]).slice(0,8);const r=el('div','row');r.style.gap='10px';sc.append(el('div','instr','Tap all the even ones.'),r);const need=nums.filter(n=>n%2===0).length;let got=0;const out=el('div','bigword','');sc.appendChild(out);
     nums.forEach(n=>{const b=el('button','choice',n);b.onclick=()=>{if(b.done)return;b.done=true;if(n%2===0){b.classList.add('hit');got++;playNote(got*2);out.textContent=`${got} of ${need}`;if(got===need){out.innerHTML=`All <em>${need}</em> evens!`;bugs('happy');confetti()}}else{b.classList.add('miss');out.innerHTML=`${n} ends in ${n%10}: <em>odd</em>`;bugs('think')}};r.appendChild(b)})}},
   /* 9. connections */
   {say:`It's the same as <em>half</em>: even numbers have a whole half (half of 8 is 4), odd numbers do not. And the same as <em>skip counting</em> by 2s. And it is where the Which one is different? puzzle gets its best reason.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','half of 8 = <em>4</em>'));sc.appendChild(el('div','bigword','half of 7 = 3 and a bit'));sc.appendChild(el('div','bigword','2, 4, 6, 8… <em>even</em>'))}}
  ],
  tries:()=>{const kind=pick(['dots','digit','which','zero','teams']);
   if(kind==='dots'){const n=rnd(2,12);return{q:`Is ${n} even or odd?`,kind:'choice',opts:['Even','Odd'],ans:n%2?'Odd':'Even',draw:st=>{currentThing='strawberries';st.appendChild(dotsRow2(n))},explain:n%2?`Pair them up and one is left over, so ${n} is odd.`:`They all pair up, so ${n} is even.`,show:st=>{st.innerHTML='';st.appendChild(pairUp2(n))}}}
   if(kind==='digit'){const n=rnd(13,99);return{q:`No pictures: is ${n} even or odd? Look at the last digit.`,kind:'choice',opts:['Even','Odd'],ans:n%2?'Odd':'Even',draw:st=>st.appendChild(el('div','bigword',`${Math.floor(n/10)}<span class="ones">${n%10}</span>`)),explain:`The tens always pair up. ${n} ends in ${n%10}, so it is ${n%2?'odd':'even'}.`}}
   if(kind==='which'){const base=rnd(2,9)*2;const opts=shuffle([base,base+2,base+1]);return{q:'Which one is odd?',kind:'choice',opts:opts.map(String),ans:String(base+1),draw:()=>{},explain:`${base+1} ends in ${(base+1)%10}: that is the odd one. ${base} and ${base+2} are even.`}}
   if(kind==='zero'){return{q:'Is 0 even or odd?',kind:'choice',opts:['Even','Odd'],ans:'Even',draw:st=>st.appendChild(el('div','bigword','0')),explain:'Nobody is alone when there is nobody at all. 0 is even, and 0, 2, 4, 6, 8 are the even endings.'}}
   const n=rnd(2,6)*2;return{q:`${n} friends make two equal teams. How many on each team?`,kind:'num',ans:n/2,draw:st=>{currentThing='strawberries';st.appendChild(dotsRow2(n))},explain:`${n} is even, so it splits into two equal teams of ${n/2}.`}}},

 {id:'diff',strand:'Adding and taking',title:'How far apart',line:'The difference between two numbers',door:'add',thing:'acorns',book:'learned what the difference between two numbers is',
  pages:[
   {say:`Here is the idea. "How many <em>more</em>?" and "how far <em>apart</em>?" are the same question. The answer is called the <em>difference</em>. ${KID()} has 9 acorns, Max has 6. How many more does ${KID()} have?`,draw:async(sc)=>{const a=row(KID()),b=row('Max');[a,b].forEach(r=>{r.style.justifyContent='flex-start';r.classList.add('wide')});sc.append(a,b);const A=[],B=[];for(let i=0;i<9;i++){const d=dot('in');A.push(d);a.appendChild(d)}for(let i=0;i<6;i++){const d=dot('in');B.push(d);b.appendChild(d)}await appear(A,'',90);await appear(B,'',90)}},
   {say:`Line them up, one under the other. The ones that <em>stick out</em> past the shorter row are the difference. Count them: <em>3</em>.`,draw:async(sc)=>{const a=row(KID()),b=row('Max');[a,b].forEach(r=>{r.style.justifyContent='flex-start';r.classList.add('wide')});sc.append(a,b);const A=[];for(let i=0;i<9;i++){const d=dot('');A.push(d);a.appendChild(d)}for(let i=0;i<6;i++)b.appendChild(dot(''));await wait(500);for(let i=6;i<9;i++){A[i].classList.add('glow');A[i].appendChild(el('b','',i-5));playNote(i);await wait(300)}sc.appendChild(el('div','bigword','<em>3</em> apart'))}},
   {say:`A second way: <em>hop</em>. Start at the small number, 6, and hop up to 9. Count the hops: <em>1, 2, 3</em>.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=6;walkTo(w,pos);const b=el('div','bigword','6');sc.appendChild(b);for(let i=0;i<3;i++){await wait(650);pos++;walkTo(w,pos);b.textContent=String(pos);playNote(pos)}b.innerHTML='3 hops: 9 − 6 = <em>3</em>'}},
   {say:`A third way: <em>take away</em>. Cover Max's 6 inside ${KID()}'s 9. What is left uncovered is the difference. 9 take away 6 leaves 3.`,draw:async(sc)=>{const a=row('');a.classList.add('wide');a.style.justifyContent='flex-start';sc.appendChild(a);const A=[];for(let i=0;i<9;i++){const d=dot('');A.push(d);a.appendChild(d)}await wait(600);for(let i=0;i<6;i++){A[i].classList.add('gone');await wait(180)}sc.appendChild(el('div','bigword','9 − 6 = <em>3</em>'))}},
   {say:`So "how far apart" and "take away" are the <em>same question</em> from two sides. 6 + 3 = 9, and 9 − 6 = 3. Three facts, one picture.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','6 + <em>3</em> = 9'));await wait(600);sc.appendChild(el('div','bigword','9 − 6 = <em>3</em>'));await wait(600);sc.appendChild(el('div','bigword','9 − 3 = <em>6</em>'))}},
   {say:`<em>Why</em> hopping up works: the hops from 6 to 9 are exactly the acorns that stick out. Counting up and taking away are measuring the same gap.`,draw:async(sc)=>{const a=row('');a.classList.add('wide');a.style.justifyContent='flex-start';sc.appendChild(a);for(let i=0;i<9;i++){const d=dot(i<6?'':'new');if(i>=6)d.appendChild(el('b','',i+1));a.appendChild(d)}sc.appendChild(el('div','bigword','7, 8, 9: the <em>gap</em> is 3'))}},
   {say:`The rule: to find the difference, start at the <em>smaller</em> number and count up to the bigger one. Or take the smaller away from the bigger. Never the other way round.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','small → up to big'));sc.appendChild(el('div','bigword','big − small'))}},
   {say:`The trap: "how many more" does <em>not</em> mean add them together. ${KID()} 9 and Max 6 is not 15 more. It is the gap between them, 3. Watch for the word "more" after a number.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','9 + 6 = 15 ✗'));await wait(700);sc.appendChild(el('div','bigword','9 − 6 = <em>3</em> more ✓'))}},
   {say:`Where you meet it: <em>ages</em> (your cousin is 8, you are 5: 3 years apart), <em>scores</em> (7 to 4: winning by 3), and <em>how many more</em> are needed: you have 6 beads and need 10, so 4 more.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 and 5: <em>3</em> years apart'));sc.appendChild(el('div','bigword','have 6, need 10: <em>4</em> more'))}},
   {say:`Your turn! Drag Max's acorns into the boxes under ${KID()}'s. The ones with <em>no acorn underneath</em> are the difference.`,draw:async(sc)=>{const a=rnd(6,9),b=rnd(2,a-2);sc.appendChild(el('div','instr',`${KID()} has ${a}. Max has ${b}. How many more does ${KID()} have?`));const top=row(KID());top.classList.add('wide');top.style.justifyContent='flex-start';const A=[];for(let i=0;i<a;i++){const d=dot('');A.push(d);top.appendChild(d)}
     const under=row('Max');under.classList.add('wide');under.style.justifyContent='flex-start';const zs=zones(a);zs.forEach(z=>under.appendChild(z));const {t,items}=trayOf(b);sc.append(top,under,t);const out=el('div','bigword','');sc.appendChild(out);
     items.forEach(d=>makeDraggable(d,{onDrop:()=>{if(fullCount(zs)===b){zs.forEach((z,i)=>{if(!z.classList.contains('full'))A[i].classList.add('glow')});out.innerHTML=`<em>${a-b}</em> more. ${a} − ${b} = ${a-b}`;bugs('happy');confetti()}}}))}},
   {say:`Your turn again, no acorns. Two numbers. Tap how far apart they are. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const a=rnd(4,12),b=rnd(1,a-1);const ans=a-b;big.innerHTML=`${a} and ${b}: how far apart?`;const opts=shuffle([ans,ans+1,a+b,Math.max(1,ans-1)].filter((v,i,x)=>x.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const btn=el('button','choice',v);btn.onclick=()=>{if(v===ans){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`${a} − ${b} = <em>${ans}</em>. You have it!`:`${a} − ${b} = <em>${ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{btn.classList.add('miss');btn.disabled=true;big.innerHTML=v===a+b?'Not together. The gap between them.':`Count up from ${b} to ${a}.`;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Find the missing number</em> (6 + ? = 9) and the same as <em>Which has more?</em>: the extra dots that stick out.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','6 + <span class="ones">?</span> = 9'));sc.appendChild(el('div','bigword','the gap is <em>3</em>'))}}
  ],
  tries:()=>{const kind=pick(['apart','apart','more','trap','missing']);const a=rnd(5,15),b=rnd(1,a-1);
   if(kind==='apart')return{q:`How far apart are ${a} and ${b}?`,kind:'num',ans:a-b,draw:st=>{currentThing='acorns';const r1=dotsRow2(a),r2=dotsRow2(b);r1.style.justifyContent=r2.style.justifyContent='flex-start';st.append(r1,r2)},explain:`${b} + ${a-b} = ${a}, so they are ${a-b} apart.`,show:st=>{st.querySelector('.srow').items.slice(b).forEach(d=>d.classList.add('glow'))}};
   if(kind==='more')return{q:`${KID()} has ${a}. Max has ${b}. How many more does ${KID()} have?`,kind:'num',ans:a-b,draw:st=>st.appendChild(el('div','bigword',`${a} and ${b}`)),explain:`Count up from ${b} to ${a}: ${a-b} more.`};
   if(kind==='trap')return{q:`${KID()} has ${a} and Max has ${b}. "How many more" means…`,kind:'choice',opts:[`${a} − ${b}`,`${a} + ${b}`],ans:`${a} − ${b}`,draw:()=>{},explain:`"More" after a number means the gap between them: ${a} − ${b} = ${a-b}.`};
   return{q:`${b} + ? = ${a}`,kind:'num',ans:a-b,draw:st=>st.appendChild(el('div','bigword',`${b} + <span class="ones">?</span> = ${a}`)),explain:`The missing number is the gap: ${a-b}.`}}},
 {id:'tens',strand:'Numbers',title:'Tens and ones',line:'Why 23 is 2 sticks and 3 dots',door:'add',thing:'blueberries',book:'learned how tens and ones make a number',
  pages:[
   {say:`Here is the idea. Big numbers are made of <em>tens</em> and <em>ones</em>. We pack things in tens because ten is easy to count, and the number tells you how many sticks and how many loose ones.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);const items=[];for(let i=0;i<23;i++){const d=dot('in');d.style.width=d.style.height='30px';d.querySelector('svg').style.width=d.querySelector('svg').style.height='28px';items.push(d);r.appendChild(d)}await appear(items,'',45);sc.appendChild(el('div','bigword','<em>23</em> blueberries. A lot to count!'))}},
   {say:`Pack them in <em>tens</em>. Ten go in a stick… and another ten. Three are left loose.`,draw:async(sc)=>{const rods=el('div','rods'),r=row('');r.classList.add('wide');sc.append(rods,r);const items=[];for(let i=0;i<23;i++){const d=dot('');d.style.width=d.style.height='30px';d.querySelector('svg').style.width=d.querySelector('svg').style.height='28px';items.push(d);r.appendChild(d)}await wait(500);
     for(let k=0;k<2;k++){for(let i=0;i<10;i++){items[k*10+i].classList.add('gone');await wait(55)}const rod=el('div','rod solid pop');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod);playNote((k+1)*10);await wait(500)}sc.appendChild(el('div','bigword','2 sticks, <em>3</em> loose'))}},
   {say:`Now read the number. <em>2</em> sticks of ten and <em>3</em> loose ones. 20 + 3 = 23. The 2 means tens, the 3 means ones. That is all a two-digit number is.`,draw:async(sc)=>{const rods=el('div','rods');for(let k=0;k<2;k++){const rod=el('div','rod solid');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod)}const r=row('');r.classList.add('wide');for(let i=0;i<3;i++)r.appendChild(dot(''));sc.append(rods,r,el('div','bigword','<em>2</em>3 &nbsp;→&nbsp; <em>2</em> tens, 3 ones'),el('div','bigword','20 + 3 = 23'))}},
   {say:`A second way: <em>money</em>. A dime is a stick of ten pennies. 23¢ is 2 dimes and 3 pennies. Same idea, different things.`,draw:async(sc)=>{const r=el('div','coins');sc.appendChild(r);for(const c of [COINS[2],COINS[2],COINS[0],COINS[0],COINS[0]]){const b=coinBtn(c);b.disabled=true;b.classList.add('pop');r.appendChild(b);await wait(300)}sc.appendChild(el('div','bigword','2 dimes + 3 pennies = <em>23¢</em>'))}},
   {say:`A third way: the <em>hundred chart</em>. Each row is one ten. 23 is in the third row (two full rows above it) and three steps in.`,draw:async(sc)=>{sc.appendChild(hundredChart([23]));sc.appendChild(el('div','bigword','2 rows, 3 in: <em>23</em>'))}},
   {say:`The pattern: counting by tens is counting <em>sticks</em>: 10, 20, 30, 40. Then the ones go 1 to 9 inside each ten and start over.`,draw:async(sc)=>{const rods=el('div','rods');sc.appendChild(rods);const w=el('div','bigword','');sc.appendChild(w);for(let i=1;i<=4;i++){const rod=el('div','rod solid pop');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod);w.textContent=String(i*10);playNote(i*10);await wait(550)}w.innerHTML='10, 20, 30, 40: <em>sticks</em>'}},
   {say:`The rule: in a two-digit number, the <em>left</em> digit counts tens, the <em>right</em> digit counts ones. 47 is 4 tens and 7 ones: 40 + 7.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','<em>4</em>7 = 40 + 7'));await wait(600);sc.appendChild(el('div','bigword','<em>6</em>1 = 60 + 1'));await wait(600);sc.appendChild(el('div','bigword','<em>3</em>0 = 30 + 0'))}},
   {say:`Two traps. <em>Order</em> matters: 32 is 3 sticks and 2 loose, but 23 is 2 sticks and 3 loose. Not the same at all! And 20 has <em>zero</em> loose ones: the 0 is there to say "no ones", not nothing.`,draw:async(sc)=>{const mk=n=>{const d=el('div');d.style.cssText='display:flex;flex-direction:column;align-items:center;gap:6px';const rods=el('div','rods');for(let k=0;k<Math.floor(n/10);k++){const rod=el('div','rod solid');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod)}const r=row('');for(let i=0;i<n%10;i++)r.appendChild(dot(''));d.append(rods,r,el('div','bigword',String(n)));return d};const rr=el('div','row');rr.style.gap='26px';rr.append(mk(32),mk(23));sc.appendChild(rr)}},
   {say:`When you run out of ones, you can <em>break</em> a stick back into ten ones. That is how 23 − 5 works: break one stick, take 5, and 18 are left.`,draw:async(sc)=>{const rods=el('div','rods');const r=row('');r.classList.add('wide');sc.append(rods,r);const rod1=el('div','rod solid'),rod2=el('div','rod solid');[rod1,rod2].forEach(rod=>{for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod)});for(let i=0;i<3;i++)r.appendChild(dot(''));await wait(700);rod2.remove();const items=[];for(let i=0;i<10;i++){const d=dot('in new');items.push(d);r.appendChild(d)}await appear(items,'new',60);await wait(400);const all=Array.from(r.children);for(let i=0;i<5;i++){all[all.length-1-i].classList.add('gone');await wait(200)}sc.appendChild(el('div','bigword','23 − 5 = <em>18</em>'))}},
   {say:`Where you meet it: <em>eggs</em> come in boxes, <em>money</em> comes in dimes and pennies, and your <em>age</em>: at 10 you get your first stick!`,draw:async(sc)=>{sc.appendChild(el('div','bigword','5 years = 5 ones'));sc.appendChild(el('div','bigword','10 years = <em>1 ten</em>'));sc.appendChild(el('div','bigword','a dime = 1 ten of pennies'))}},
   {say:`Your turn! Drag <em>ten</em> blueberries into the box. When it is full, it turns into a stick!`,draw:async(sc)=>{const n=rnd(13,19);sc.appendChild(el('div','instr',`${n} blueberries. Pack ten into the box.`));const box=el('div','stickbox');const zs=zones(10);zs.forEach(z=>box.appendChild(z));const {t,items}=trayOf(n);const rods=el('div','rods');sc.append(rods,box,t);const out=el('div','bigword','');sc.appendChild(out);
     items.forEach(d=>makeDraggable(d,{onDrop:()=>{if(fullCount(zs)===10){box.querySelectorAll('.it2').forEach(x=>x.dataset.locked='1');setTimeout(()=>{const rod=el('div','rod solid pop');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod);box.remove();out.innerHTML=`<em>1</em> ten and <em>${n-10}</em> ones = ${n}`;bugs('happy');confetti();playNote(20)},500)}}}))}},
   {say:`Your turn again, no pictures. Pip says tens and ones. Tap the number.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);let t=0,o=0;const btns=[];const next=()=>{t=rnd(1,5);o=rnd(0,9);big.innerHTML=`<em>${t}</em> tens and <em>${o}</em> ones`;const ans=t*10+o;const opts=shuffle([ans,o*10+t,ans+10,ans-1].filter((v,i,a)=>v>0&&a.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===ans){b.classList.add('hit');got++;playNote(got*4);if(got>=3){big.innerHTML=`${t} tens and ${o} ones = <em>${ans}</em>. You have it!`;bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=`${v} is ${Math.floor(v/10)} tens and ${v%10} ones. Try again.`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>skip counting</em> by tens, and it is what makes <em>Take away</em> work: break a ten when the ones run out.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','10, 20, 30… = sticks'));sc.appendChild(el('div','bigword','no ones left? <em>break a stick</em>'))}}
  ],
  tries:()=>{const kind=pick(['read','build','order','zero']);const n=rnd(11,59);
   if(kind==='read')return{q:`What number is this?`,kind:'num',ans:n,draw:st=>{currentThing='blueberries';const rods=el('div','rods');for(let i=0;i<Math.floor(n/10);i++){const r=el('div','rod solid');for(let j=0;j<10;j++)r.appendChild(el('span','u'));rods.appendChild(r)}st.append(rods,dotsRow2(n%10))},explain:`${Math.floor(n/10)} tens is ${Math.floor(n/10)*10}, and ${n%10} more is ${n}.`};
   if(kind==='build'){const t=rnd(1,5),o=rnd(1,9);return{q:`${t} tens and ${o} ones. What number?`,kind:'num',ans:t*10+o,draw:st=>st.appendChild(el('div','bigword',`${t} tens, ${o} ones`)),explain:`${t*10} + ${o} = ${t*10+o}.`}}
   if(kind==='order'){const a=rnd(1,4),b=rnd(5,9);return{q:`Which number has ${b} tens?`,kind:'choice',opts:[`${b}${a}`,`${a}${b}`],ans:`${b}${a}`,draw:()=>{},explain:`The left digit counts tens: ${b}${a} is ${b} tens and ${a} ones.`}}
   const t=rnd(2,6);return{q:`${t} sticks of ten and no loose ones. What number?`,kind:'num',ans:t*10,draw:st=>{const rods=el('div','rods');for(let i=0;i<t;i++){const r=el('div','rod solid');for(let j=0;j<10;j++)r.appendChild(el('span','u'));rods.appendChild(r)}st.appendChild(rods)},explain:`${t} tens is ${t*10}. The 0 says there are no ones.`}}},
 {id:'compare',strand:'Numbers',title:'Bigger and smaller',line:'Which number is more?',door:'warm',thing:'crayons',book:'learned how to tell which number is bigger',
  pages:[
   {say:`Here is the idea. A <em>bigger</em> number means <em>more</em> things. To compare two numbers, ask: which one would make the taller tower?`,draw:async(sc)=>{const t=el('div','towers');const a=el('div','tower'),b=el('div','tower');t.append(a,b);sc.appendChild(t);for(let i=0;i<12;i++){a.appendChild(el('i'));if(i<9)b.appendChild(el('i'));await wait(120)}a.appendChild(el('b','','12'));b.appendChild(el('b','','9'));await wait(300);a.classList.add('win')}},
   {say:`12 is <em>bigger</em>. It has 3 more blocks. 9 is <em>smaller</em>. We write it 12 > 9, and the wide end of the sign faces the bigger number, like a mouth eating the bigger pile.`,draw:async(sc)=>{const t=el('div','towers');const a=el('div','tower win'),b=el('div','tower');t.append(a,b);sc.appendChild(t);for(let i=0;i<12;i++)a.appendChild(el('i'));for(let i=0;i<9;i++)b.appendChild(el('i'));a.appendChild(el('b','','12'));b.appendChild(el('b','','9'));sc.appendChild(el('div','bigword','12 <em>&gt;</em> 9'))}},
   {say:`A second way: the <em>number line</em>. Numbers further to the right are bigger. 12 is to the right of 9, so 12 is bigger.`,draw:async(sc)=>{const w=el('div','walk');walkTo(w,12);sc.append(w,el('div','bigword','9 … <em>12</em>: 12 is further right'))}},
   {say:`A third way: <em>count up</em>. Say 1, 2, 3… The number you reach <em>later</em> is bigger. You reach 9 first, then keep going to 12.`,draw:async(sc)=>{const strip=el('div','ways strip');for(let i=1;i<=12;i++)strip.appendChild(el('span','way',i));sc.appendChild(strip);const w=el('div','bigword','');sc.appendChild(w);for(let i=1;i<=12;i++){strip.children[i-1].style.background=i===9?'var(--sun)':i===12?'var(--leaf)':'';if(i===12)strip.children[11].style.color='#fff';w.textContent=String(i);playNote(i);await wait(220)}w.innerHTML='9 came first, <em>12</em> came later'}},
   {say:`For <em>big</em> numbers, look at the <em>tens</em> first. 31 has 3 sticks. 28 has only 2. So 31 is bigger, even though 8 is more than 1.`,draw:async(sc)=>{const rods=(n)=>{const r=el('div','rods');for(let i=0;i<Math.floor(n/10);i++){const rod=el('div','rod solid');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));r.appendChild(rod)}return r};const t=el('div','towers');t.style.gap='30px';const a=el('div'),b=el('div');a.append(rods(31),el('div','bigword','<em>3</em>1'));b.append(rods(28),el('div','bigword','<em>2</em>8'));t.append(a,b);sc.appendChild(t)}},
   {say:`Same tens? Then look at the <em>ones</em>. 45 and 43: both have 4 tens, and 5 is more than 3. 45 wins.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','4<span class="ones">5</span> &nbsp;&gt;&nbsp; 4<span class="ones">3</span>'))}},
   {say:`<em>Why</em> tens come first: one stick is worth ten loose ones, so even one extra stick beats any pile of loose ones. 30 beats 29, and 29 has lots of loose ones.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 sticks &gt; 2 sticks + 9 loose'));sc.appendChild(el('div','bigword','30 <em>&gt;</em> 29'))}},
   {say:`The rule: <em>more digits</em> wins. Then <em>tens</em>. Then <em>ones</em>. 100 beats 99. 31 beats 28. 45 beats 43.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','100 &gt; 99: more digits'));sc.appendChild(el('div','bigword','31 &gt; 28: more tens'));sc.appendChild(el('div','bigword','45 &gt; 43: more ones'))}},
   {say:`The trap: a <em>bigger digit</em> does not make a bigger number. 8 is bigger than 1, but 18 is smaller than 81. Where the digit <em>sits</em> matters more than what it is.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 &gt; 1 … but'));sc.appendChild(el('div','bigword','<em>1</em>8 &lt; <em>8</em>1'))}},
   {say:`Where you meet it: <em>ages</em> (your cousin is 7, you are 5: she is older), <em>scores</em> in a game, and <em>prices</em>: 25¢ is more than 10¢.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','7 &gt; 5: older'));sc.appendChild(el('div','bigword','25¢ &gt; 10¢: costs more'))}},
   {say:`Your turn! Build two towers: <em>7</em> blocks and <em>5</em> blocks. Which is taller?`,draw:async(sc)=>{const a=rnd(5,9),b=rnd(2,a-2);sc.appendChild(el('div','instr',`Left tower: ${a} blocks. Right tower: ${b} blocks.`));const tw=el('div','towers');const ba=el('div','towerbase'),bb=el('div','towerbase');const za=zones(a),zb=zones(b);za.forEach(z=>ba.appendChild(z));zb.forEach(z=>bb.appendChild(z));tw.append(ba,bb);const {t,items}=trayOf(a+b);sc.append(tw,t);const out=el('div','bigword','');sc.appendChild(out);
     items.forEach(d=>makeDraggable(d,{onDrop:()=>{if(fullCount(za)+fullCount(zb)===a+b){out.innerHTML=`${a} <em>&gt;</em> ${b}. ${a} is bigger by ${a-b}.`;bugs('happy');confetti()}}}))}},
   {say:`Your turn again, no towers. Tap the <em>bigger</em> number. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const r=el('div','row');r.style.gap='18px';const big=el('div','bigword','');sc.append(r,big);const next=()=>{let a=rnd(5,60),b=rnd(5,60);while(b===a)b=rnd(5,60);r.innerHTML='';[a,b].forEach(v=>{const btn=el('button','choice',v);btn.style.fontSize='2rem';btn.onclick=()=>{if(v===Math.max(a,b)){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`${Math.max(a,b)} &gt; ${Math.min(a,b)}. You have it!`:`${Math.max(a,b)} &gt; ${Math.min(a,b)}`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{btn.classList.add('miss');btn.disabled=true;big.textContent=Math.floor(a/10)!==Math.floor(b/10)?'Look at the tens first.':'Same tens, so look at the ones.';bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Which has more?</em> in the warm-ups, and the same as <em>Number neighbors</em>: the next number up is always a bit bigger.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','more things = <em>bigger</em> number'));sc.appendChild(el('div','bigword','further right = bigger'))}}
  ],
  tries:()=>{const kind=pick(['which','which','tens','trap','digits']);let a=rnd(5,60),b=rnd(5,60);while(b===a)b=rnd(5,60);
   if(kind==='which')return{q:'Which is bigger?',kind:'choice',opts:[String(a),String(b)],ans:String(Math.max(a,b)),draw:()=>{},explain:Math.floor(a/10)!==Math.floor(b/10)?`${Math.max(a,b)} has more tens.`:`Same tens, so look at the ones: ${Math.max(a,b)} wins.`};
   if(kind==='tens'){const t=rnd(2,8);a=t*10;b=(t-1)*10+9;return{q:`Which is bigger, ${a} or ${b}?`,kind:'choice',opts:[String(a),String(b)],ans:String(a),draw:()=>{},explain:`${a} has ${t} sticks; ${b} has only ${t-1}. One stick beats nine loose ones.`}}
   if(kind==='trap'){const x=rnd(1,4),y=rnd(6,9);return{q:`Which is bigger, ${x}${y} or ${y}${x}?`,kind:'choice',opts:[`${x}${y}`,`${y}${x}`],ans:`${y}${x}`,draw:()=>{},explain:`${y}${x} has ${y} tens. Where a digit sits matters more than what it is.`}}
   return{q:'Which is bigger, 100 or 99?',kind:'choice',opts:['100','99'],ans:'100',draw:()=>{},explain:'More digits wins: 100 is one more than 99.'}}},
 {id:'ten',strand:'Adding and taking',title:'Making ten',line:'The pairs that make 10',door:'warm',thing:'buttons',book:'learned the pairs that make ten',
  pages:[
   {say:`Here is the idea. <em>Ten</em> is a special number: a full frame, a full stick, all your fingers. Every number under ten has a <em>partner</em> that fills it up to ten.`,draw:async(sc)=>{const f=tenFrame(0);sc.appendChild(f);for(let i=0;i<10;i++){f.cells[i].className='';playNote(i+1);await wait(110)}sc.appendChild(el('div','bigword','10'))}},
   {say:`7 blue buttons. How many more to fill it? Count the empty boxes: <em>3</em>. So 7 and 3 are partners: 7 + 3 = 10.`,draw:async(sc)=>{const f=tenFrame(7);sc.appendChild(f);await wait(600);for(let i=7;i<10;i++){f.cells[i].className='new';playNote(i);await wait(250)}sc.appendChild(el('div','bigword','7 + <em>3</em> = 10'))}},
   {say:`A second way to see it: <em>fingers</em>. Hold up 7. The ones still down are the partner. 3 down, so 7 + 3 = 10.`,draw:async(sc)=>{const g=el('div','pairs');g.style.gridTemplateRows='repeat(2,1fr)';sc.appendChild(g);for(let i=0;i<10;i++){const d=el('div','it2');d.innerHTML=`<svg viewBox="0 0 40 40"><rect x="14" y="4" width="12" height="32" rx="6" fill="${i<7?'#f4a261':'var(--line)'}"/></svg>`;g.appendChild(d);await wait(120)}sc.appendChild(el('div','bigword','7 up, <em>3</em> down'))}},
   {say:`A third way: the <em>number line</em>. Stand on 7 and hop to 10. Count the hops: 1, 2, 3. The partner of 7 is 3.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=7;walkTo(w,pos);const b=el('div','bigword','7');sc.appendChild(b);for(let i=0;i<3;i++){await wait(650);pos++;walkTo(w,pos);b.textContent=String(pos);playNote(pos)}b.innerHTML='3 hops: 7 + <em>3</em> = 10'}},
   {say:`The pattern. Every number has one partner, and the partners go <em>down</em> as the numbers go <em>up</em>: 1 and 9, 2 and 8, 3 and 7, 4 and 6, 5 and 5.`,draw:async(sc)=>{const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(2,auto);gap:6px 24px;font-family:var(--display);font-size:1.5rem';sc.appendChild(g);for(const [a,b] of [[1,9],[2,8],[3,7],[4,6],[5,5]]){g.appendChild(el('div','',`${a} + <em style="font-style:normal;color:var(--accent)">${b}</em>`));g.appendChild(el('div','','= 10'));playNote(a*2);await wait(380)}}},
   {say:`<em>Why</em> it works: the frame has exactly 10 boxes. Full boxes and empty boxes always add up to 10. So the partner is just the <em>empty boxes</em>, whatever number you start with.`,draw:async(sc)=>{const w=el('div','bigword','');const f=tenFrame(0);sc.append(f,w);for(const k of [4,8,2,6]){f.cells.forEach((d,i)=>d.className=i<k?'':'empty');w.innerHTML=`${k} full + <em>${10-k}</em> empty = 10`;playNote(k);await wait(1100)}}},
   {say:`The rule, in words: to find a partner, <em>count the empties</em>, or <em>count up</em> from your number to ten. Both give the same answer.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','6 → 7, 8, 9, 10'));sc.appendChild(el('div','bigword','4 hops, so <em>4</em>'))}},
   {say:`Two traps. Partners are a <em>pair</em>: 8's partner is 2, and 2's partner is 8, the same pair both ways. And 8 + 8 is not 10! Only one number fits each partner. 5 is the only one that partners itself.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 + 2 = 10 &nbsp; 2 + 8 = 10'));await wait(700);sc.appendChild(el('div','bigword','8 + 8 = 16 ✗'));await wait(700);sc.appendChild(el('div','bigword','5 + <em>5</em> = 10'))}},
   {say:`Where you meet it: ten <em>fingers</em>. A <em>dime</em> is ten pennies, and a nickel and five pennies make it too. Ten blocks make a tower that is "one ten".`,draw:async(sc)=>{sc.appendChild(el('div','bigword','5 fingers + 5 fingers'));sc.appendChild(el('div','bigword','5¢ + 5¢ = <em>10¢</em>'));sc.appendChild(el('div','bigword','10 blocks = <em>1 stick</em>'))}},
   {say:`Your turn! Drag buttons into the frame until it is <em>full</em>. Then count how many you added.`,draw:async(sc)=>{const k=rnd(3,8);sc.appendChild(el('div','instr',`${k} are in already. Fill it up!`));const f=el('div','frame');const zs=[];for(let i=0;i<10;i++){if(i<k){const c=el('div','cell');c.appendChild(dot(''));f.appendChild(c)}else{const z=el('div','cell dz');zs.push(z);f.appendChild(z)}}const {t,items}=trayOf(10-k+2);sc.append(f,t);const out=el('div','bigword','');sc.appendChild(out);
     items.forEach(d=>makeDraggable(d,{onDrop:()=>{if(fullCount(zs)===10-k){out.innerHTML=`${k} + <em>${10-k}</em> = 10`;bugs('happy');confetti()}}}))}},
   {say:`Your turn again, no frame this time. A number lights up. Tap its <em>partner</em>. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const btns=[];for(let i=1;i<=9;i++){const b=el('button','choice',i);btns.push(b);r.appendChild(b)}let cur=0;const next=()=>{cur=rnd(1,9);big.innerHTML=`<em>${cur}</em> and…?`;btns.forEach(b=>{b.classList.remove('hit','miss');b.disabled=false})};next();
     btns.forEach((b,i)=>b.onclick=()=>{const v=i+1;if(v===10-cur){b.classList.add('hit');got++;playNote(10);big.innerHTML=`${cur} + <em>${v}</em> = 10`;if(got>=3){bugs('happy');confetti();big.innerHTML+=' · you have it!'}else setTimeout(next,900)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=`${cur} + ${v} = ${cur+v}, not 10`;bugs('think')}})}},
   {say:`It's the same as <em>Make a ten to add</em>: 8 + 5 is easier as 8 + 2 + 3. And the same as <em>Make the money</em>: a dime is 10¢ however you build it.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 + 5 → 8 + <em>2</em> + 3'));sc.appendChild(el('div','bigword','= 10 + 3 = <em>13</em>'))}}
  ],
  tries:()=>{const kind=pick(['frame','words','back','yesno','fingers']);const k=rnd(1,9);
   if(kind==='frame')return{q:`${k} and what make 10?`,kind:'num',ans:10-k,draw:st=>st.appendChild(tenFrame(k)),explain:`${k} + ${10-k} = 10.`,show:st=>{st.querySelector('.frame').cells.slice(k).forEach(d=>d.className='new')}};
   if(kind==='words')return{q:`No frame this time. What is the partner of ${k}?`,kind:'num',ans:10-k,draw:st=>st.appendChild(el('div','bigword',`${k} + ? = 10`)),explain:`Count up from ${k} to 10: ${10-k} hops.`};
   if(kind==='back')return{q:`10 take away ${k}?`,kind:'num',ans:10-k,draw:st=>st.appendChild(el('div','bigword',`10 − ${k} = ?`)),explain:`It is the same partner: ${k} and ${10-k} make 10, so 10 − ${k} = ${10-k}.`};
   if(kind==='yesno'){const a=rnd(1,9),b=Math.random()<.5?10-a:rnd(1,9);return{q:`Do ${a} and ${b} make 10?`,kind:'choice',opts:['Yes','No'],ans:a+b===10?'Yes':'No',draw:st=>st.appendChild(el('div','bigword',`${a} + ${b}`)),explain:a+b===10?`${a} + ${b} = 10. Partners!`:`${a} + ${b} = ${a+b}, not 10. The partner of ${a} is ${10-a}.`}}
   return{q:`${k} fingers are up. How many are down?`,kind:'num',ans:10-k,draw:st=>st.appendChild(el('div','bigword',`${k} up`)),explain:`10 fingers in all, so ${10-k} are down.`}}},
 {id:'double',strand:'Groups',title:'Double and half',line:'Twice as many, and sharing in two',door:'pat',thing:'gummy bears',book:'learned about doubles and halves',
  pages:[
   {say:`Here is the idea. <em>Double</em> means the same again: 4 and 4 more. <em>Half</em> is the opposite: share into two equal piles and take one pile. They undo each other.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';const a=row(''),b=row('');a.classList.add('wide');b.classList.add('wide');for(let i=0;i<4;i++)a.appendChild(dot(''));r.append(a,el('div','mirrorline'),b);sc.appendChild(r);await wait(600);const items=[];for(let i=0;i<4;i++){const d=dot('in new');items.push(d);b.appendChild(d)}await appear(items,'new',150);sc.appendChild(el('div','bigword','double 4 = 4 + 4 = <em>8</em>'))}},
   {say:`<em>Half</em> of 8: deal them out, one for this pile, one for that pile, round and round. Each pile gets 4. Half of 8 is 4.`,draw:async(sc)=>{const a=row('pile 1'),b=row('pile 2');a.classList.add('wide');b.classList.add('wide');const top=row('');top.classList.add('wide');sc.append(top,a,b);const items=[];for(let i=0;i<8;i++){const d=dot('');items.push(d);top.appendChild(d)}await wait(600);for(let i=0;i<8;i++){await flyTo(items[i],(i%2?b:a).appendChild(dot('slot')));playNote(i+1);await wait(80)}sc.appendChild(el('div','bigword','half of 8 = <em>4</em>'))}},
   {say:`A second way to see double: a <em>mirror</em>. Whatever is on the left shows again on the right. 3 becomes 3 and 3: six.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';const a=row(''),b=row('');for(let i=0;i<3;i++)a.appendChild(dot(''));r.append(a,el('div','mirrorline'),b);sc.appendChild(r);await wait(800);for(let i=0;i<3;i++){const d=dot('in new');b.appendChild(d);await wait(20);d.classList.remove('in');await wait(200)}sc.appendChild(el('div','bigword','3 + 3 = <em>6</em>'))}},
   {say:`A third way: <em>hands</em>. One hand is 5. Both hands is double 5: 10. And half of your ten fingers is one hand, 5.`,draw:async(sc)=>{const d=el('div');d.innerHTML=handSvg(5);const e=el('div');e.innerHTML=handSvg(5).replace('<svg','<svg style="transform:scaleX(-1)"');const r=el('div','row');r.append(d,e);sc.append(r,el('div','bigword','5 + 5 = <em>10</em> · half of 10 = <em>5</em>'))}},
   {say:`The pattern: doubles are the <em>even</em> numbers. Double 1 is 2, double 2 is 4, double 3 is 6, double 4 is 8, double 5 is 10. Know these and lots of adding gets easy.`,draw:async(sc)=>{const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(2,auto);gap:6px 24px;font-family:var(--display);font-size:1.5rem';sc.appendChild(g);for(const [a,b] of [[1,2],[2,4],[3,6],[4,8],[5,10],[6,12]]){g.appendChild(el('div','',`${a} + ${a}`));g.appendChild(el('div','',`= <em style="font-style:normal;color:var(--accent)">${b}</em>`));playNote(b);await wait(330)}}},
   {say:`<em>Why</em> they undo each other: double makes two equal piles into one big pile. Half splits that big pile back into the two equal piles. Double 6 is 12, half of 12 is 6. Back where you started.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','6 → double → <em>12</em>'));await wait(800);sc.appendChild(el('div','bigword','12 → half → <em>6</em>'))}},
   {say:`The rule: to double, <em>add the number to itself</em>. To halve, <em>share into two equal piles</em>, or ask "what number doubled makes this?"`,draw:async(sc)=>{sc.appendChild(el('div','bigword','double 7 = 7 + 7 = <em>14</em>'));sc.appendChild(el('div','bigword','half of 14: 7 + 7, so <em>7</em>'))}},
   {say:`Two traps. Only <em>even</em> numbers halve evenly: half of 7 is 3 and 3 with one left over, so odd numbers have no fair half. And double is <em>not</em> plus two: double 5 is 10, not 7.`,draw:async(sc)=>{const a=row('pile 1'),b=row('pile 2');a.classList.add('wide');b.classList.add('wide');sc.append(a,b);for(let i=0;i<4;i++)a.appendChild(dot(''));for(let i=0;i<3;i++)b.appendChild(dot(''));const x=dot('alone glow');a.lastChild.replaceWith(x);sc.appendChild(el('div','bigword','7 is <em>odd</em>: no fair half'));await wait(900);sc.appendChild(el('div','bigword','double 5 = 10, not 7'))}},
   {say:`Where you meet it: <em>sharing</em> a cookie with one friend (half each), <em>pairs</em> of socks (double), and a clock: <em>half past</em> is half way round.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','1 cookie, 2 friends: <em>half</em> each'));sc.appendChild(el('div','bigword','6 pairs of socks: <em>12</em> socks'))}},
   {say:`Your turn! Share the bears into two piles so both piles are the <em>same</em>.`,draw:async(sc)=>{const n=pick([6,8,10]);sc.appendChild(el('div','instr',`${n} bears. Make two equal piles.`));const tw=el('div','towers');tw.style.alignItems='flex-start';const p1=el('div','pilebox'),p2=el('div','pilebox');const z1=zones(n),z2=zones(n);z1.forEach(z=>p1.appendChild(z));z2.forEach(z=>p2.appendChild(z));tw.append(p1,p2);const {t,items}=trayOf(n);sc.append(tw,t);const out=el('div','bigword','');sc.appendChild(out);
     items.forEach(d=>makeDraggable(d,{onDrop:()=>{const a=fullCount(z1),b=fullCount(z2);if(a+b===n){if(a===b){out.innerHTML=`Half of ${n} is <em>${a}</em>!`;bugs('happy');confetti()}else{out.innerHTML=`${a} and ${b}. Not equal yet!`;bugs('think')}}}}))}},
   {say:`Your turn again, no bears. Pip says double or half. Tap the answer. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const dbl=Math.random()<.5;const n=dbl?rnd(1,8):rnd(1,8)*2;const ans=dbl?n*2:n/2;big.innerHTML=dbl?`double <em>${n}</em>`:`half of <em>${n}</em>`;const opts=shuffle([ans,ans+1,dbl?n+2:n,Math.max(1,ans-1)].filter((v,i,x)=>x.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===ans){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=(dbl?`${n} + ${n} = <em>${ans}</em>`:`${ans} + ${ans} = ${n}, so <em>${ans}</em>`)+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=dbl?`Double means ${n} + ${n}.`:`What number plus itself makes ${n}?`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>even and odd</em> (evens have a fair half), the same as <em>equal groups</em> (double is 2 groups), and the same as a quarter: half of a half.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','double = <em>2 groups</em>'));sc.appendChild(el('div','bigword','half of a half = a <em>quarter</em>'))}}
  ],
  tries:()=>{const kind=pick(['double','half','odd','trap','undo']);
   if(kind==='double'){const n=rnd(1,10);return{q:`What is double ${n}?`,kind:'num',ans:2*n,draw:st=>{currentThing='gummy bears';st.appendChild(dotsRow2(n))},explain:`${n} + ${n} = ${2*n}.`}}
   if(kind==='half'){const n=rnd(1,10)*2;return{q:`What is half of ${n}?`,kind:'num',ans:n/2,draw:st=>{currentThing='gummy bears';st.appendChild(dotsRow2(n))},explain:`Share ${n} into two piles of ${n/2}.`}}
   if(kind==='odd'){const n=rnd(1,5)*2+1;return{q:`Can ${n} be shared into two equal piles?`,kind:'choice',opts:['No, one is left over','Yes'],ans:'No, one is left over',draw:st=>{currentThing='gummy bears';st.appendChild(dotsRow2(n))},explain:`${n} is odd: ${(n-1)/2} and ${(n-1)/2} with one left over.`}}
   if(kind==='trap'){const n=rnd(3,9);return{q:`Double ${n} is…`,kind:'choice',opts:shuffle([String(2*n),String(n+2)]),ans:String(2*n),draw:()=>{},explain:`Double is the number again, not plus 2: ${n} + ${n} = ${2*n}.`}}
   const n=rnd(2,9);return{q:`Double ${n}, then take half. What do you get?`,kind:'num',ans:n,draw:st=>st.appendChild(el('div','bigword',`${n} → double → half → ?`)),explain:`Double and half undo each other: back to ${n}.`}}},
 {id:'counton',title:'Counting on',line:'Start big, then count up',door:'add',thing:'acorns',strand:'Numbers',book:'learned to count on from the bigger number',
  pages:[
   {say:`Here is the idea. To add a few more, you do <em>not</em> have to count everything from 1. Hold the first number in your head and <em>count on</em> from there.`,draw:async(sc)=>{const a=row(''),b=row('');a.classList.add('wide');b.classList.add('wide');sc.append(a,b);const A=[],B=[];for(let i=0;i<8;i++){const d=dot('in');A.push(d);a.appendChild(d)}for(let i=0;i<3;i++){const d=dot('in new');B.push(d);b.appendChild(d)}await appear(A,'',70);await appear(B,'new',150);sc.appendChild(el('div','bigword','8 + 3'))}},
   {say:`Say "<em>8</em>" and hold it. Then touch the new ones: <em>9, 10, 11</em>. 8 + 3 = 11.`,draw:async(sc)=>{const a=row(''),b=row('');a.classList.add('wide');b.classList.add('wide');sc.append(a,b);for(let i=0;i<8;i++)a.appendChild(dot(''));const B=[];for(let i=0;i<3;i++){const d=dot('new');B.push(d);b.appendChild(d)}const w=el('div','bigword','8…');sc.appendChild(w);await wait(700);for(let i=0;i<3;i++){B[i].classList.add('hi');B[i].appendChild(el('b','',9+i));w.textContent=String(9+i);playNote(9+i);await wait(600)}w.innerHTML='8 + 3 = <em>11</em>'}},
   {say:`<em>Why</em> it works: counting all of them from 1 gives the very same answer, it just takes longer. The 8 are already counted; you only need the new ones.`,draw:async(sc)=>{const a=row('');a.classList.add('wide');sc.appendChild(a);const all=[];for(let i=0;i<11;i++){const d=dot(i<8?'':'new');all.push(d);a.appendChild(d)}const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<11;i++){all[i].appendChild(el('b','',i+1));w.textContent=String(i+1);await wait(i<8?170:450)}w.innerHTML='all 11, the slow way';await wait(900);all.forEach((d,i)=>{if(i<8)d.querySelector('b').remove()});w.innerHTML='8… 9, 10, <em>11</em>: the fast way'}},
   {say:`A second way: the <em>number line</em>. Stand on 8, hop 3. You land on 11.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=8;walkTo(w,pos);const b=el('div','bigword','8');sc.appendChild(b);for(let i=0;i<3;i++){await wait(600);pos++;walkTo(w,pos);b.textContent=String(pos);playNote(pos)}b.innerHTML='8 + 3 = <em>11</em>'}},
   {say:`The rule: always start from the <em>bigger</em> number. 3 + 8 is the same as 8 + 3, and starting at 8 means fewer hops.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 + 8'));await wait(700);sc.appendChild(el('div','bigword','= 8 + <em>3</em>'));await wait(500);sc.appendChild(el('div','bigword','8… 9, 10, <em>11</em>'))}},
   {say:`The trap: do not say the start number <em>again</em>. It is "8… 9, 10, 11", not "8, 9, 10". Hold the 8 quietly, then count only the new ones.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8… 9, 10, <em>11</em> ✓'));await wait(800);sc.appendChild(el('div','bigword','<s style="color:var(--muted)">8, 9, 10</s> ✗'))}},
   {say:`Where you meet it: climbing <em>stairs</em>. You are on step 8. Three more steps: 9, 10, 11. Keeping <em>score</em>: you have 6, you win 2 more: 7, 8.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=8;walkTo(w,pos);for(let i=0;i<3;i++){await wait(600);pos++;walkTo(w,pos)}sc.appendChild(el('div','bigword','step 8 → step <em>11</em>'))}},
   {say:`Your turn! Tap the big number first, then tap the acorns one at a time and say the next number out loud.`,draw:async(sc)=>{const a=rnd(6,9),b=rnd(2,4);sc.appendChild(el('div','instr',`${a} + ${b}. Tap ${a}, then the ${b} new ones.`));const big=el('button','bigword',String(a));big.style.cssText='background:var(--sun);border-radius:14px;padding:4px 16px';sc.appendChild(big);const r=row('');r.classList.add('wide');sc.appendChild(r);const B=[];for(let i=0;i<b;i++){const d=dot('new');B.push(d);r.appendChild(d)}const out=el('div','bigword','');sc.appendChild(out);let step=0;
     big.onclick=()=>{if(step===0){step=1;big.classList.add('pop');playNote(a);out.textContent=`${a}…`}};
     B.forEach((d,i)=>d.onclick=()=>{if(step!==i+1||d.querySelector('b'))return;d.appendChild(el('b','',a+i+1));d.classList.add('hi');playNote(a+i+1);step++;out.textContent=String(a+i+1);if(step===b+1){out.innerHTML=`${a} + ${b} = <em>${a+b}</em>`;bugs('happy');confetti()}})}},
   {say:`Your turn again, no acorns. The sum is shown. Tap the numbers you would <em>say</em>, in order, after the big number.`,draw:async(sc)=>{const a=rnd(5,9),b=rnd(2,4);const big=el('div','bigword',`${a} + ${b}: say ${a}, then…`);const r=el('div','row');r.style.gap='8px';sc.append(big,r);let next=a+1;const opts=shuffle(Array.from({length:7},(_,i)=>a-1+i));opts.forEach(v=>{const btn=el('button','choice',v);btn.onclick=()=>{if(btn.classList.contains('hit'))return;if(v===next){btn.classList.add('hit');playNote(v);next++;if(next>a+b){big.innerHTML=`${a} + ${b} = <em>${a+b}</em>`;bugs('happy');confetti()}else big.innerHTML=`${a}… ${Array.from({length:next-a-1},(_,i)=>a+1+i).join(', ')}…`}else{btn.classList.add('miss');setTimeout(()=>btn.classList.remove('miss'),500);big.innerHTML=`After ${next-1} comes…`;bugs('think')}};r.appendChild(btn)})}},
   {say:`It's the same as hopping on the <em>number line</em>, and it is the trick inside <em>Make a ten</em>: 8 + 5 is 8… 9, 10, and then 3 more.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','start at 8'));sc.appendChild(el('div','bigword','hop <em>3</em>'));sc.appendChild(el('div','bigword','land on <em>11</em>'))}}
  ],
  tries:()=>{const kind=pick(['on','bigger','say','stairs']);const a=rnd(5,12),b=rnd(2,5);
   if(kind==='on')return{q:`${b} + ${a} = ? (start from the bigger one)`,kind:'num',ans:a+b,draw:st=>{currentThing='acorns';st.appendChild(el('div','bigword',`${a}… `))},explain:`Start at ${a}, count on ${b}: ${a+b}.`};
   if(kind==='bigger')return{q:`To work out ${b} + ${a}, which number do you start from?`,kind:'choice',opts:[String(a),String(b),'1'],ans:String(a),draw:()=>{},explain:`Start from the bigger one, ${a}, so there are fewer hops.`};
   if(kind==='say')return{q:`${a} + 2. You say "${a}…" and then?`,kind:'choice',opts:[`${a+1}, ${a+2}`,`${a}, ${a+1}`,`${a+2}, ${a+3}`],ans:`${a+1}, ${a+2}`,draw:()=>{},explain:`Do not say ${a} again. The next two are ${a+1}, ${a+2}.`};
   return{q:`You are on step ${a}. You climb ${b} more. Which step now?`,kind:'num',ans:a+b,draw:st=>{const w=el('div','walk');walkTo(w,Math.min(a,20));st.appendChild(w)},explain:`${a}… ${Array.from({length:b},(_,i)=>a+1+i).join(', ')}.`}}},
 {id:'skip',title:'Skip counting',line:'Count by 2s, 5s and 10s',door:'pat',thing:'stickers',strand:'Numbers',book:'learned to count by 2s, 5s and 10s',
  pages:[
   {say:`Here is the idea. When things come in <em>groups</em> that are all the same size, you can count the groups instead of the things. That is skip counting: 2, 4, 6 instead of 1, 2, 3, 4, 5, 6.`,draw:async(sc)=>{const g=el('div','pairgrid');sc.appendChild(g);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<4;i++){const a=dot('in'),b=dot('in');g.append(a,b);await wait(20);a.classList.remove('in');b.classList.remove('in');w.textContent=String((i+1)*2);playNote((i+1)*2);await wait(650)}w.innerHTML='<em>2, 4, 6, 8</em>'}},
   {say:`Shoes come in <em>pairs</em>. Count them two at a time: 2, 4, 6, 8. Four pairs, eight shoes, and you only said four numbers.`,draw:async(sc)=>{const r=el('div','row');sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<4;i++){const h=el('div');h.innerHTML='<svg viewBox="0 0 60 40" style="width:70px"><path d="M4 30c0-8 6-10 14-10h8l6-10h10l-2 10h14c4 0 6 2 6 6v4H4z" fill="#5aa9e6"/><path d="M4 30c0-8 6-10 14-10h8l6-10h10l-2 10h14c4 0 6 2 6 6v4H4z" fill="#5aa9e6" transform="translate(0,0)"/></svg>';h.classList.add('pop');r.appendChild(h);w.textContent=String((i+1)*2);playNote((i+1)*2);await wait(650)}w.innerHTML='4 pairs = <em>8</em> shoes'}},
   {say:`Hands have <em>5</em> fingers. Count hands by fives: 5, 10, 15, 20.`,draw:async(sc)=>{const r=el('div','row');sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<4;i++){const h=el('div','');h.innerHTML='<svg viewBox="0 0 40 40" style="width:56px;height:56px"><path d="M12 36V18M18 36V12M24 36V10M30 36V14M8 36v-8l-4-6" stroke="#f4a261" stroke-width="5" stroke-linecap="round" fill="none"/><rect x="9" y="24" width="24" height="14" rx="6" fill="#f4a261"/></svg>';h.classList.add('pop');r.appendChild(h);w.textContent=String((i+1)*5);playNote((i+1)*5);await wait(650)}w.innerHTML='<em>5, 10, 15, 20</em>'}},
   {say:`Sticks of ten count by <em>tens</em>: 10, 20, 30, 40. That is the fastest counting there is.`,draw:async(sc)=>{const rods=el('div','rods');sc.appendChild(rods);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<4;i++){const rod=el('div','rod solid pop');for(let j=0;j<10;j++)rod.appendChild(el('span','u'));rods.appendChild(rod);w.textContent=String((i+1)*10);playNote((i+1)*10);await wait(650)}w.innerHTML='<em>10, 20, 30, 40</em>'}},
   {say:`<em>Why</em> it works: skip counting is just <em>adding the same number again and again</em>. 2, 4, 6 is +2, +2, +2. The number line shows the hops are all the same size.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=0;walkTo(w,pos);const b=el('div','bigword','0');sc.appendChild(b);for(let i=0;i<5;i++){await wait(550);pos+=2;walkTo(w,pos);b.textContent=String(pos);playNote(pos)}b.innerHTML='+2, +2, +2… same-size <em>hops</em>'}},
   {say:`The pattern, to check yourself. Counting by 2s from 0 lands only on <em>even</em> numbers. Counting by 5s ends in <em>5 or 0</em>, taking turns. Counting by 10s always ends in <em>0</em>.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','2, 4, 6, 8, 1<span class="ones">0</span>'));await wait(600);sc.appendChild(el('div','bigword','<span class="ones">5</span>, 1<span class="ones">0</span>, 1<span class="ones">5</span>, 2<span class="ones">0</span>'));await wait(600);sc.appendChild(el('div','bigword','1<span class="ones">0</span>, 2<span class="ones">0</span>, 3<span class="ones">0</span>'))}},
   {say:`The rule: start at 0, and every hop <em>adds the same</em>. For 2s add 2, for 5s add 5, for 10s add 10. If you are not sure of the next one, add it.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','15 + 5 = <em>20</em>'));sc.appendChild(el('div','bigword','20 + 5 = <em>25</em>'))}},
   {say:`Two traps. If you say 5, 10, <em>12</em>, you have slipped: 12 does not end in 5 or 0. And counting by 2s from <em>1</em> is different: 1, 3, 5, 7, the <em>odd</em> numbers. Where you start matters.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','5, 10, <s style="color:var(--muted)">12</s> ✗'));await wait(700);sc.appendChild(el('div','bigword','from 1: 1, 3, 5, 7 = <em>odd</em>'))}},
   {say:`Where you meet it: <em>nickels</em> count by 5s, <em>dimes</em> by 10s, <em>eggs</em> by the half-dozen, and the <em>clock</em>: the long hand counts by fives.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 nickels: 5, 10, <em>15¢</em>'));sc.appendChild(el('div','bigword','clock: 5, 10, 15… <em>60</em>'))}},
   {say:`Your turn! Drag the stickers into groups of <em>2</em>, then count the groups by twos.`,draw:async(sc)=>{const n=pick([6,8,10]);sc.appendChild(el('div','instr',`${n} stickers. Make pairs, then count 2, 4, 6…`));const pb=el('div','pairbox');const zs=zones(n);zs.forEach(z=>pb.appendChild(z));const {t,items}=trayOf(n);sc.append(pb,t);const out=el('div','bigword','');sc.appendChild(out);items.forEach(d=>makeDraggable(d,{onDrop:()=>{const f=fullCount(zs);if(f%2===0&&f>0)out.textContent=Array.from({length:f/2},(_,i)=>(i+1)*2).join(', ');if(f===n){out.innerHTML=`<em>${n}</em> in ${n/2} pairs!`;bugs('happy');confetti()}}}))}},
   {say:`Your turn again, no pictures. Pip counts and stops. Tap what comes <em>next</em>. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const d=pick([2,5,10]);const st=d===10?rnd(1,5)*10:d*rnd(1,6);const seq=[st,st+d,st+2*d];const ans=st+3*d;big.innerHTML=`${seq.join(', ')}, <em>?</em>`;const opts=shuffle([ans,ans+1,ans-d-1,ans+d].filter((v,i,a)=>a.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===ans){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`${seq.join(', ')}, <em>${ans}</em>. You have it!`:`${seq.join(', ')}, <em>${ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=`It goes up by ${d} each time. ${seq[2]} + ${d} = ?`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as a <em>pattern</em> (+2 each time), the same as <em>equal groups</em> (3 groups of 4 is 4, 8, 12), and the same as the clock's fives.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','2 → 4 → 6 → 8'));sc.appendChild(el('div','bigword','<em>+2</em> each time'))}}
  ],
  tries:()=>{const kind=pick(['next','next','check','groups','start']);const d=pick([2,5,10]),st=d===10?rnd(1,5)*10:d*rnd(1,6);const seq=[st,st+d,st+2*d];
   if(kind==='next')return{q:`${seq.join(', ')}, …what comes next?`,kind:'num',ans:st+3*d,draw:st2=>{st2.appendChild(el('div','bigword',seq.join(', ')+', ?'))},explain:`It goes up by ${d} each time: ${st+3*d}.`};
   if(kind==='check'){const wrong=pick([12,17,23,31]);return{q:`Counting by 5s, could you ever say ${wrong}?`,kind:'choice',opts:['No','Yes'],ans:'No',draw:()=>{},explain:`Counting by 5s always ends in 5 or 0. ${wrong} ends in ${wrong%10}.`}}
   if(kind==='groups'){const g=rnd(2,5);return{q:`${g} pairs of shoes. Count by 2s: how many shoes?`,kind:'num',ans:g*2,draw:st2=>{currentThing='stickers';st2.appendChild(el('div','bigword',`${g} pairs`))},explain:`${Array.from({length:g},(_,i)=>(i+1)*2).join(', ')}: ${g*2} shoes.`}}
   return{q:'Count by 2s starting at 1: 1, 3, 5, … What kind of numbers are these?',kind:'choice',opts:['Odd','Even'],ans:'Odd',draw:()=>{},explain:'Starting at 1 lands on the odd numbers. Starting at 0 lands on the evens.'}}},
 {id:'equals',title:'What = really means',line:'Both sides the same',door:'puz',thing:'buttons',strand:'Adding and taking',book:'learned what the equals sign really means',
  pages:[
   {say:`Here is the idea. The <em>=</em> sign does not mean "the answer is". It means "<em>the same as</em>". Whatever is on this side is worth exactly what is on that side, like a balance.`,draw:async(sc)=>{const d=el('div','scale');sc.appendChild(d);d.innerHTML=scaleSvg('3 + 4','7',0);sc.appendChild(el('div','bigword','3 + 4 <em>=</em> 7'))}},
   {say:`So 7 = 3 + 4 is just as true, written the other way round. And 2 + 5 = 3 + 4 is true too: both sides are worth <em>7</em>. The scale stays level.`,draw:async(sc)=>{const d=el('div','scale');sc.appendChild(d);d.innerHTML=scaleSvg('2 + 5','3 + 4',0);sc.appendChild(el('div','bigword','2 + 5 <em>=</em> 3 + 4'))}},
   {say:`A second way: <em>buttons</em>. 2 and 3 on the left, 4 and 1 on the right. Count each side: 5 and 5. Equal.`,draw:async(sc)=>{const a=row('left'),b=row('right');a.classList.add('wide');b.classList.add('wide');sc.append(a,b);for(let i=0;i<5;i++)a.appendChild(dot(i<2?'':'new'));for(let i=0;i<5;i++)b.appendChild(dot(i<4?'':'new'));sc.appendChild(el('div','bigword','2 + 3 <em>=</em> 4 + 1'))}},
   {say:`A third way: <em>not</em> equal. 3 + 4 on the left, 6 on the right. The left is heavier and sinks. We do not write = there. The sides have to match exactly.`,draw:async(sc)=>{const d=el('div','scale');sc.appendChild(d);d.innerHTML=scaleSvg('3 + 4','6',0);await wait(700);d.innerHTML=scaleSvg('3 + 4','6',-8);sc.appendChild(el('div','bigword','7 is <em>not</em> 6: tips'))}},
   {say:`<em>Why</em> it matters: if = means "the same as", then you can change one side as long as you change the other the same way. Take 1 off both sides and it still balances.`,draw:async(sc)=>{const d=el('div','scale');sc.appendChild(d);d.innerHTML=scaleSvg('3 + 4','7',0);await wait(900);d.innerHTML=scaleSvg('2 + 4','6',0);sc.appendChild(el('div','bigword','1 off each side: <em>still level</em>'))}},
   {say:`The rule: read = as "<em>is the same as</em>". Then any sentence with = is a question: do the two sides really weigh the same?`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 + 4 = 7'));sc.appendChild(el('div','bigword','"3 and 4 <em>is the same as</em> 7"'))}},
   {say:`The trap: lots of kids think = means "write the answer next". Then 4 + 3 = ? + 2 looks strange. It is not! It asks: what makes the <em>right</em> side weigh 7 too? The answer is 5, not 7.`,draw:async(sc)=>{const d=el('div','scale');sc.appendChild(d);d.innerHTML=scaleSvg('4 + 3','? + 2',8);await wait(900);d.innerHTML=scaleSvg('4 + 3','5 + 2',0);sc.appendChild(el('div','bigword','4 + 3 = <em>5</em> + 2'))}},
   {say:`Where you meet it: sharing snacks fairly. "I get 2 + 3, you get 4 + 1" is fair, because <em>5 = 5</em>. And a see-saw: it only stays level when both sides weigh the same.`,draw:async(sc)=>{const a=row('me'),b=row('you');a.classList.add('wide');b.classList.add('wide');sc.append(a,b);for(let i=0;i<5;i++)a.appendChild(dot(i<2?'':'new'));for(let i=0;i<5;i++)b.appendChild(dot(i<4?'':'new'));sc.appendChild(el('div','bigword','2 + 3 <em>=</em> 4 + 1: fair'))}},
   {say:`Your turn! The left pan has some buttons. Drag buttons onto the right pan until it <em>balances</em>.`,draw:async(sc)=>{const L=rnd(4,8);sc.appendChild(el('div','instr',`Left side: ${L}. Make the right side the same.`));const d=el('div','scale');sc.appendChild(d);const pan=el('div','pilebox');pan.classList.add('tray');pan.style.minHeight='56px';const lab=el('div','instr','right pan');const {t,items}=trayOf(L+2);sc.append(lab,pan,t);const out=el('div','bigword','');sc.appendChild(out);const upd=()=>{const R=pan.querySelectorAll('.it2').length;d.innerHTML=scaleSvg(String(L),String(R),L===R?0:(L>R?-8:8));out.innerHTML=L===R?`${L} <em>=</em> ${R}. Balanced!`:'';if(L===R){bugs('happy');confetti()}};upd();items.forEach(x=>makeDraggable(x,{onDrop:upd}))}},
   {say:`Your turn again, no buttons. Is it true or false? Tap. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');sc.append(big,r);const next=()=>{const a=rnd(1,6),b=rnd(1,6),c=rnd(1,6);const truth=Math.random()<.5;const dd=truth?a+b-c:a+b-c+pick([-1,1]);const ok=dd>=0&&a+b===c+dd;big.innerHTML=`${a} + ${b} = ${c} + ${dd<0?0:dd}`;const ans=(a+b===c+(dd<0?0:dd))?'True':'False';r.innerHTML='';['True','False'].forEach(o=>{const btn=el('button','choice',o);btn.onclick=()=>{if(o===ans){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${a+b} and ${c+(dd<0?0:dd)}: <em>${ans}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{btn.classList.add('miss');btn.disabled=true;big.innerHTML=`Left is ${a+b}. Right is ${c+(dd<0?0:dd)}. Same?`;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as the <em>Balance it</em> puzzle, and it is the secret behind <em>Find the missing number</em>: 9 − ? = 4 means "9 take away something weighs the same as 4".`,draw:async(sc)=>{sc.appendChild(el('div','bigword','9 − <span class="ones">?</span> = 4'));sc.appendChild(el('div','bigword','9 − <em>5</em> and 4 weigh the same'))}}
  ],
  tries:()=>{const kind=pick(['missing','missing','truefalse','meaning','other']);const a=rnd(2,6),b=rnd(2,6),c=rnd(1,a+b-1);
   if(kind==='missing')return{q:`${a} + ${b} = ? + ${c}`,kind:'num',ans:a+b-c,draw:st=>{const d=el('div','scale');d.innerHTML=scaleSvg(`${a} + ${b}`,`? + ${c}`,0);st.appendChild(d)},explain:`Left is ${a+b}. ${a+b-c} + ${c} is also ${a+b}.`};
   if(kind==='truefalse'){const t=Math.random()<.5;const r2=t?a+b:a+b+1;return{q:`True or false: ${a} + ${b} = ${r2}`,kind:'choice',opts:['True','False'],ans:t?'True':'False',draw:()=>{},explain:t?`Both sides are ${a+b}.`:`${a} + ${b} is ${a+b}, not ${r2}. The sides do not match.`}}
   if(kind==='meaning')return{q:'What does = mean?',kind:'choice',opts:['The same as','The answer is next','Add them'],ans:'The same as',draw:st=>st.appendChild(el('div','bigword','=')),explain:'Both sides weigh the same, like a balance.'};
   return{q:`Is ${a+b} = ${a} + ${b} true?`,kind:'choice',opts:['Yes','No'],ans:'Yes',draw:()=>{},explain:`It is the same fact written the other way round. Both sides are ${a+b}.`}}},
 {id:'neighbors',title:'Number neighbors',line:'Before, after, between, and 10 more',door:'add',thing:'marbles',strand:'Numbers',book:'learned about number neighbors and 10 more, 10 less',
  pages:[
   {say:`Here is the idea. Numbers live in <em>order</em>, like houses on a street. Every number has neighbors: the one just <em>before</em> and the one just <em>after</em>. 14 lives between 13 and 15.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);walkTo(w,14);sc.appendChild(el('div','bigword','13 ← <em>14</em> → 15'))}},
   {say:`After is <em>one more</em>. Before is <em>one less</em>. 14 + 1 = 15, 14 − 1 = 13. That is all a neighbor is.`,draw:async(sc)=>{const strip=el('div','ways strip');for(let i=10;i<=18;i++)strip.appendChild(el('span','way',i));sc.appendChild(strip);const w=el('div','bigword','');sc.appendChild(w);strip.children[4].style.background='var(--sun)';await wait(600);strip.children[5].style.background='var(--leaf)';strip.children[5].style.color='#fff';w.innerHTML='after: 14 + 1 = <em>15</em>';playNote(15);await wait(1100);strip.children[3].style.background='var(--leaf)';strip.children[3].style.color='#fff';w.innerHTML='before: 14 − 1 = <em>13</em>';playNote(13)}},
   {say:`A second way: numbers live in a big <em>house</em> with 10 rooms on every floor. Going <em>down one floor</em> is 10 more, straight below. 34 → 44 → 54.`,draw:async(sc)=>{sc.appendChild(hundredChart([34,44,54]));sc.appendChild(el('div','bigword','34, 44, <em>54</em>'))}},
   {say:`Going <em>up one floor</em> is 10 less. Look at the ones digit: it <em>never changes</em>, only the tens do. 67 → 57 → 47.`,draw:async(sc)=>{sc.appendChild(hundredChart([67,57,47]));sc.appendChild(el('div','bigword','6<span class="ones">7</span>, 5<span class="ones">7</span>, <em>4</em><span class="ones">7</span>'))}},
   {say:`A third way: <em>sticks</em>. 10 more adds one whole stick and the loose ones stay exactly as they were. 34 is 3 sticks and 4; 44 is 4 sticks and 4.`,draw:async(sc)=>{const rods=el('div','rods');for(let i=0;i<3;i++){const r=el('div','rod solid');for(let j=0;j<10;j++)r.appendChild(el('span','u'));rods.appendChild(r)}const r2=row('');r2.classList.add('wide');for(let i=0;i<4;i++)r2.appendChild(dot(''));sc.append(rods,r2,el('div','bigword','34'));await wait(800);const nr=el('div','rod solid pop');for(let j=0;j<10;j++)nr.appendChild(el('span','u'));rods.appendChild(nr);sc.lastChild.innerHTML='34 + 10 = <em>44</em>'}},
   {say:`The pattern: next-door neighbors change the <em>ones</em>. Upstairs and downstairs neighbors change the <em>tens</em>. 23: beside it 22 and 24; above and below it 13 and 33.`,draw:async(sc)=>{sc.appendChild(hundredChart([13,22,23,24,33]));sc.appendChild(el('div','bigword','22 · <em>23</em> · 24, and 13, 33'))}},
   {say:`The rule: <em>one more</em> or <em>one less</em>: change the ones digit by 1. <em>Ten more</em> or <em>ten less</em>: change the tens digit by 1 and leave the ones alone.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','56 + 1 = 5<span class="ones">7</span>'));sc.appendChild(el('div','bigword','56 + 10 = <em>6</em>6'))}},
   {say:`The trap: 10 more than 39 is <em>not</em> 40. It is 49: same 9, one more ten. 40 is just 1 more. And after 29, one more is 30: the tens tick over.`,draw:async(sc)=>{sc.appendChild(hundredChart([39,49]));sc.appendChild(el('div','bigword','39 + 10 = <em>49</em>'));sc.appendChild(el('div','bigword','39 + 1 = 40'))}},
   {say:`Where you meet it: <em>birthdays</em> (next year you are one more), <em>house numbers</em> (next door is 2 more on your side), and <em>pages</em> in a book: the next page is one more.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','5 → next birthday <em>6</em>'));sc.appendChild(el('div','bigword','page 14 → page <em>15</em>'))}},
   {say:`Your turn! Drag the number tiles into order from <em>smallest to biggest</em>. Neighbors should end up side by side.`,draw:async(sc)=>{const base=rnd(5,80);const nums=shuffle([base,base+1,base+2,base+10,base+11]);sc.appendChild(el('div','instr','Smallest on the left.'));const slots=el('div','srow wide');const zs=zones(5);zs.forEach(z=>{z.style.borderRadius='12px';slots.appendChild(z)});const tray=el('div','srow tray wide');const tiles=nums.map(n=>{const t=el('div','it2');t.innerHTML=`<b style="position:static;min-width:40px;height:40px;font-size:1.2rem;background:var(--sky);color:#fff">${n}</b>`;t.dataset.n=n;tray.appendChild(t);return t});sc.append(slots,tray);const out=el('div','bigword','');sc.appendChild(out);
     tiles.forEach(t=>makeDraggable(t,{onDrop:()=>{if(fullCount(zs)===5){const order=zs.map(z=>+z.querySelector('.it2').dataset.n);const ok=order.every((v,i)=>i===0||v>order[i-1]);out.innerHTML=ok?`<em>${order.join(' < ')}</em>`:'Not in order yet. Which is smallest?';if(ok){bugs('happy');confetti()}else bugs('think')}}}))}},
   {say:`Your turn again, no tiles. Pip asks for a neighbor. Tap it. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const n=rnd(11,85);const k=pick(['before','after','10 more','10 less']);const ans={before:n-1,after:n+1,'10 more':n+10,'10 less':n-10}[k];big.innerHTML=`<em>${k}</em> ${k.includes('10')?'than':''} ${n}`;const opts=shuffle([ans,n+1,n-1,n+10,n-10].filter((v,i,x)=>x.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===ans){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${k} ${k.includes('10')?'than':''} ${n} is <em>${ans}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=k.includes('10')?'Only the tens change; the ones stay.':'Change the ones by just 1.';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>Tens and ones</em>: 10 more adds one stick. And the same as <em>Bigger and smaller</em>: the neighbor after is always a bit bigger.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','+1 → ones · +10 → <em>tens</em>'));sc.appendChild(el('div','bigword','after = a bit <em>bigger</em>'))}}
  ],
  tries:()=>{const n=rnd(11,85);const k=pick(['before','after','10 more','10 less','trap']);
   if(k==='trap'){const m=rnd(2,8)*10-1;return{q:`What is 10 more than ${m}?`,kind:'choice',opts:shuffle([String(m+10),String(m+1)]),ans:String(m+10),draw:st=>st.appendChild(hundredChart([m])),explain:`Same ${m%10}, one more ten: ${m+10}. ${m+1} is only 1 more.`}}
   const ans={before:n-1,after:n+1,'10 more':n+10,'10 less':n-10}[k];return{q:k==='before'?`What comes just before ${n}?`:k==='after'?`What comes just after ${n}?`:`What is ${k} than ${n}?`,kind:'num',ans,draw:st=>st.appendChild(hundredChart([n])),explain:k==='before'||k==='after'?`${n} and ${ans} are neighbors: the ones change by 1.`:`Only the tens change: ${ans}.`}}},
 {id:'groups',title:'Equal groups',line:'The start of multiplying',door:'story',thing:'gummy bears',strand:'Groups',book:'learned about equal groups',
  pages:[
   {say:`Here is the idea. When every group has the <em>same</em> number in it, you can count the <em>groups</em> instead of counting everything. 3 bags, 4 bears in each bag: equal groups.`,draw:async(sc)=>{const r=el('div','row');sc.appendChild(r);for(let i=0;i<3;i++){const bag=el('div','pilebox');r.appendChild(bag);const items=[];for(let j=0;j<4;j++){const d=dot('in');items.push(d);bag.appendChild(d)}await appear(items,'',90)}sc.appendChild(el('div','bigword','3 groups of <em>4</em>'))}},
   {say:`Do not count them one by one. Count by <em>fours</em>: 4, 8, 12. Three bags, twelve bears. We write it <em>3 × 4 = 12</em>: three groups of four.`,draw:async(sc)=>{const r=el('div','row');sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<3;i++){const bag=el('div','pilebox pop');r.appendChild(bag);for(let j=0;j<4;j++)bag.appendChild(dot(''));w.textContent=String((i+1)*4);playNote((i+1)*4);await wait(700)}w.innerHTML='3 × 4 = <em>12</em>'}},
   {say:`A second way: lined up in rows it is an <em>array</em>. 3 rows of 4. Turn it on its side and it is 4 rows of 3. Same 12 either way, so 3 × 4 = 4 × 3.`,draw:async(sc)=>{const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(4,46px);gap:6px;transition:transform .8s';for(let i=0;i<12;i++)g.appendChild(dot(''));sc.appendChild(g);const w=el('div','bigword','3 rows of 4');sc.appendChild(w);await wait(1200);g.style.gridTemplateColumns='repeat(3,46px)';w.innerHTML='4 rows of 3: still <em>12</em>'}},
   {say:`A third way: the <em>number line</em>, hopping 4 at a time. Three hops of 4 land on 12. Equal groups are equal hops.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=0;walkTo(w,pos);const b=el('div','bigword','0');sc.appendChild(b);for(let i=0;i<3;i++){await wait(650);pos+=4;walkTo(w,pos);b.textContent=String(pos);playNote(pos)}b.innerHTML='3 hops of 4 = <em>12</em>'}},
   {say:`<em>Why</em> it works: 3 groups of 4 is just 4 + 4 + 4. Multiplying is adding the <em>same number</em> again and again, and skip counting is the quick way to do that adding.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','4 + 4 + 4 = 12'));await wait(600);sc.appendChild(el('div','bigword','3 × 4 = <em>12</em>'));await wait(600);sc.appendChild(el('div','bigword','4, 8, <em>12</em>'))}},
   {say:`The rule: find how many in <em>one</em> group. Then skip count by that number, once for each group. The number of groups is how many times you count.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','one group = 5'));sc.appendChild(el('div','bigword','4 groups: 5, 10, 15, <em>20</em>'))}},
   {say:`The trap: it only works when the groups are <em>equal</em>. 4, 4 and 3 bears is not 3 × 4. Then you have to add them properly: 4 + 4 + 3 = 11.`,draw:async(sc)=>{const r=el('div','row');sc.appendChild(r);for(const n of [4,4,3]){const bag=el('div','pilebox');for(let j=0;j<n;j++)bag.appendChild(dot(''));r.appendChild(bag)}r.lastChild.style.outline='3px dashed var(--accent)';sc.appendChild(el('div','bigword','not equal: 4 + 4 + 3 = <em>11</em>'))}},
   {say:`Where you meet it: <em>egg boxes</em> (2 rows of 6), <em>wheels</em> on cars (4 each), <em>legs</em> on dogs, <em>fingers</em> on hands. Equal groups are everywhere.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 cars × 4 wheels = <em>12</em>'));sc.appendChild(el('div','bigword','2 dogs × 4 legs = <em>8</em>'))}},
   {say:`Your turn! Put <em>the same number</em> of bears in each box. Then count by that number.`,draw:async(sc)=>{const g=rnd(3,4),e=rnd(2,4);sc.appendChild(el('div','instr',`${g} boxes, ${e} bears each.`));const r=el('div','row');const all=[];for(let i=0;i<g;i++){const b=el('div','pilebox');const zs=zones(e);zs.forEach(z=>{b.appendChild(z);all.push(z)});r.appendChild(b)}const {t,items}=trayOf(g*e);sc.append(r,t);const out=el('div','bigword','');sc.appendChild(out);items.forEach(d=>makeDraggable(d,{onDrop:()=>{if(fullCount(all)===g*e){out.innerHTML=`${g} × ${e} = <em>${g*e}</em>`;bugs('happy');confetti()}}}))}},
   {say:`Your turn again, no bears. Pip says the groups. Tap how many in all. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const g=rnd(2,4),e=rnd(2,5);const ans=g*e;big.innerHTML=`<em>${g}</em> groups of <em>${e}</em>`;const opts=shuffle([ans,g+e,ans+e,ans-1].filter((v,i,x)=>x.indexOf(v)===i&&v>0)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===ans){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${Array.from({length:g},(_,i)=>(i+1)*e).join(', ')}: <em>${ans}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=v===g+e?`Not ${g} + ${e}. Count by ${e}s, ${g} times.`:`Count by ${e}s: ${e}, ${2*e}…`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>skip counting</em> (3 groups of 4 is 4, 8, 12), the same as <em>double</em> (2 equal groups), and the opposite of <em>fair sharing</em>, which takes a pile apart.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','4, 8, 12'));sc.appendChild(el('div','bigword','double 6 = 2 groups of 6 = <em>12</em>'))}}
  ],
  tries:()=>{const kind=pick(['all','all','trap','which','array']);const g=rnd(2,4),e=rnd(2,5);
   if(kind==='all')return{q:`${g} bags with ${e} in each. How many in all?`,kind:'num',ans:g*e,draw:st=>{currentThing='gummy bears';const r=el('div','row');for(let i=0;i<g;i++){const b=el('div','pilebox');for(let j=0;j<e;j++)b.appendChild(dot(''));r.appendChild(b)}st.appendChild(r)},explain:`Count by ${e}s, ${g} times: ${g*e}.`};
   if(kind==='trap')return{q:`Bags of 4, 4 and 3. Are these equal groups?`,kind:'choice',opts:['No','Yes'],ans:'No',draw:st=>{currentThing='gummy bears';const r=el('div','row');for(const n of [4,4,3]){const b=el('div','pilebox');for(let j=0;j<n;j++)b.appendChild(dot(''));r.appendChild(b)}st.appendChild(r)},explain:'One bag has 3. Equal groups must all be the same, so add them: 4 + 4 + 3 = 11.'};
   if(kind==='which')return{q:`${g} groups of ${e}. Which adding is that?`,kind:'choice',opts:shuffle([Array(g).fill(e).join(' + '),Array(e).fill(g).join(' + ')+(g===e?' (same)':''),`${g} + ${e}`]).filter((v,i,x)=>x.indexOf(v)===i),ans:Array(g).fill(e).join(' + '),draw:()=>{},explain:`${g} groups of ${e} is ${e} added ${g} times.`};
   return{q:`3 rows of ${e}. Turn it on its side: how many rows of 3?`,kind:'num',ans:e,draw:st=>{const gr=el('div');gr.style.cssText=`display:grid;grid-template-columns:repeat(${e},34px);gap:5px`;currentThing='gummy bears';for(let i=0;i<3*e;i++){const d=dot('');d.style.width=d.style.height='30px';gr.appendChild(d)}st.appendChild(gr)},explain:`3 × ${e} = ${e} × 3. Same ${3*e} bears.`}}},
 {id:'share',title:'Fair sharing',line:'The start of dividing',door:'story',thing:'strawberries',strand:'Groups',book:'learned how to share fairly',
  pages:[
   {say:`Here is the idea. <em>Fair</em> means everyone gets the <em>same</em>. 12 strawberries, 3 friends. Deal them out: one for you, one for you, one for you, round and round until they are gone.`,draw:async(sc)=>{const r=el('div','row');const plates=[];for(let i=0;i<3;i++){const p=el('div','pilebox');plates.push(p);r.appendChild(p)}sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<12;i++){const d=dot('in');plates[i%3].appendChild(d);await wait(20);d.classList.remove('in');playNote(i);await wait(180)}w.innerHTML='<em>4</em> each'}},
   {say:`Everyone gets <em>4</em>. 12 shared by 3 is 4. We write it <em>12 ÷ 3 = 4</em>. Check it: 4 + 4 + 4 = 12. Nothing lost.`,draw:async(sc)=>{const r=el('div','row');for(let i=0;i<3;i++){const p=el('div','pilebox');for(let j=0;j<4;j++)p.appendChild(dot(''));r.appendChild(p)}sc.appendChild(r);sc.appendChild(el('div','bigword','12 ÷ 3 = <em>4</em>'))}},
   {say:`A second way: <em>grouping</em>. Instead of dealing one at a time, ask "how many 3s are in 12?" Make groups of 3: 1, 2, 3, 4 groups. Same answer, 4.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);const items=[];for(let i=0;i<12;i++){const d=dot('');items.push(d);r.appendChild(d)}const w=el('div','bigword','');sc.appendChild(w);await wait(600);for(let g=0;g<4;g++){for(let j=0;j<3;j++)items[g*3+j].classList.add('glow');w.textContent=`${g+1} group${g?'s':''} of 3`;playNote((g+1)*3);await wait(700);for(let j=0;j<3;j++){items[g*3+j].classList.remove('glow');items[g*3+j].style.opacity='.4'}}w.innerHTML='<em>4</em> groups of 3 in 12'}},
   {say:`A third way: sharing is <em>equal groups backwards</em>. 3 × 4 = 12 puts groups together. 12 ÷ 3 = 4 takes the pile apart again.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 × 4 = 12'));await wait(700);sc.appendChild(el('div','bigword','12 ÷ 3 = <em>4</em>'))}},
   {say:`<em>Why</em> dealing round works: every time round, each friend gets exactly one. So however many times you go round, nobody is ahead. That is what fair means.`,draw:async(sc)=>{const r=el('div','row');const plates=[];for(let i=0;i<3;i++){const p=el('div','pilebox');plates.push(p);r.appendChild(p)}sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let round=0;round<3;round++){for(let i=0;i<3;i++){plates[i].appendChild(dot('new'));await wait(150)}w.textContent=`round ${round+1}: ${round+1} each`;await wait(600)}w.innerHTML='every round, <em>one each</em>'}},
   {say:`Sometimes it does not come out even. 13 shared by 3: 4 each and <em>1 left over</em>. The leftover is called the <em>remainder</em>. You cannot share it fairly, so it stays in the bowl.`,draw:async(sc)=>{const r=el('div','row');for(let i=0;i<3;i++){const p=el('div','pilebox');for(let j=0;j<4;j++)p.appendChild(dot(''));r.appendChild(p)}sc.appendChild(r);const left=row('left over');left.classList.add('wide');left.appendChild(dot('alone glow'));sc.append(left,el('div','bigword','13 ÷ 3 = 4, <em>1 left</em>'))}},
   {say:`The rule: deal one at a time, round and round, until there are not enough left for another full round. Then count one plate. Whatever is left is the remainder.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','deal round and round'));sc.appendChild(el('div','bigword','count <em>one</em> plate'))}},
   {say:`The trap: sharing is <em>not</em> the same as cutting in half. Half is sharing with <em>2</em>. With 3 or 4 friends the piles get smaller: 12 ÷ 2 = 6, 12 ÷ 3 = 4, 12 ÷ 4 = 3. More friends, less each.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','12 ÷ 2 = 6'));sc.appendChild(el('div','bigword','12 ÷ 3 = 4'));sc.appendChild(el('div','bigword','12 ÷ 4 = <em>3</em>'))}},
   {say:`Where you meet it: <em>snacks</em> for the table, <em>cards</em> dealt for a game, <em>teams</em> picked from a class. Any time something has to be fair.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 cookies, 4 kids: <em>2</em> each'));sc.appendChild(el('div','bigword','10 cards, 2 players: <em>5</em> each'))}},
   {say:`Your turn! Share the strawberries onto the plates so every plate has the <em>same</em>.`,draw:async(sc)=>{const k=pick([2,3,4]),e=rnd(2,4),n=k*e;sc.appendChild(el('div','instr',`${n} strawberries, ${k} plates. Make it fair.`));const r=el('div','row');const plates=[];for(let i=0;i<k;i++){const p=el('div','pilebox tray');p.style.minHeight='56px';plates.push(p);r.appendChild(p)}const {t,items}=trayOf(n);sc.append(r,t);const out=el('div','bigword','');sc.appendChild(out);
     const chk=()=>{const counts=plates.map(p=>p.querySelectorAll('.it2').length);const tot=counts.reduce((a,b)=>a+b,0);if(tot<n)return;if(counts.every(c=>c===e)){out.innerHTML=`${n} ÷ ${k} = <em>${e}</em> each!`;bugs('happy');confetti()}else{out.innerHTML=counts.join(', ')+'. Not fair yet!';bugs('think')}};items.forEach(d=>makeDraggable(d,{onDrop:chk}))}},
   {say:`Your turn again, no strawberries. Pip says the pile and the friends. Tap how many each. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const k=rnd(2,4),e=rnd(2,5);const n=k*e;big.innerHTML=`<em>${n}</em> shared by <em>${k}</em> friends`;const opts=shuffle([e,e+1,n-k,Math.max(1,e-1)].filter((v,i,x)=>x.indexOf(v)===i)).slice(0,4);if(!opts.includes(e))opts[0]=e;r.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===e){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${n} ÷ ${k} = <em>${e}</em> each`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=`Check: ${k} friends with ${v} each is ${k*v}, not ${n}.`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>equal groups backwards</em>, the same as <em>half</em> when there are two of you, and the same as <em>How many ways?</em> when the beads have to be split.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','groups put together'));sc.appendChild(el('div','bigword','sharing takes <em>apart</em>'))}}
  ],
  tries:()=>{const kind=pick(['each','each','remainder','trap','check']);const k=rnd(2,4),e=rnd(2,5);
   if(kind==='each')return{q:`${k*e} shared fairly by ${k} friends. How many each?`,kind:'num',ans:e,draw:st=>{currentThing='strawberries';st.appendChild(dotsRow2(k*e))},explain:`Deal them out one at a time: ${e} each.`};
   if(kind==='remainder')return{q:`${k*e+1} shared by ${k} friends. How many are left over?`,kind:'num',ans:1,draw:st=>{currentThing='strawberries';st.appendChild(dotsRow2(k*e+1))},explain:`${e} each uses ${k*e}. One is left over: the remainder.`};
   if(kind==='trap')return{q:'12 cookies. More friends to share with means…',kind:'choice',opts:['fewer each','more each','the same each'],ans:'fewer each',draw:()=>{},explain:'12 ÷ 2 = 6, 12 ÷ 3 = 4, 12 ÷ 4 = 3. More friends, less each.'};
   return{q:`${k} friends got ${e} each. How many were shared out?`,kind:'num',ans:k*e,draw:st=>st.appendChild(el('div','bigword',`${k} × ${e}`)),explain:`${k} × ${e} = ${k*e}. Sharing and equal groups undo each other.`}}},
 {id:'clock',title:'Reading the clock',line:'Hands, o\'clock, half past, and digital',door:'time',thing:'buttons',strand:'Time',book:'learned to read a clock',
  pages:[
   {say:`Here is the idea. A clock has two hands. The <em>short</em> one is slow and points to the hour. The <em>long</em> one is fast and counts the minutes. Read the short one first, then the long one.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);for(let m=0;m<=60;m+=5){c.innerHTML=clockSvg(3,m);await wait(140)}sc.appendChild(el('div','bigword','short = <em>hour</em>, long = <em>minutes</em>'))}},
   {say:`When the long hand points straight up to the 12, it is something <em>o'clock</em>. Short hand on the 3: three o'clock.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);c.innerHTML=clockSvg(3,0);sc.appendChild(el('div','bigword','3 o\'clock &nbsp;=&nbsp; <em>3:00</em>'))}},
   {say:`When the long hand points straight down to the 6, it is <em>half past</em>. It has gone half way round. Look: the short hand has crept half way from 3 to 4.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);c.innerHTML=clockSvg(3,0);await wait(500);for(let m=0;m<=30;m+=2){c.innerHTML=clockSvg(3,m);await wait(60)}sc.appendChild(el('div','bigword','half past 3 &nbsp;=&nbsp; <em>3:30</em>'))}},
   {say:`A second way to see the same time: a <em>digital</em> clock writes it with numbers, hour first, then minutes. 3:20 means short hand just past 3, long hand on the 4.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';const c=el('div');c.innerHTML=clockSvg(3,20,true);const d=el('div','bigword');d.style.cssText='background:#1a1a1a;color:#5fe36b;padding:10px 20px;border-radius:12px;font-family:monospace;letter-spacing:2px';d.textContent='3:20';r.append(c,d);sc.appendChild(r)}},
   {say:`A third way: the clock face is a <em>circle cut in four</em>. Long hand on the 3 is a quarter of the way round: <em>quarter past</em>. On the 9 it is a quarter before the next hour: <em>quarter to</em>.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);const w=el('div','bigword','');sc.appendChild(w);for(const [m,t] of [[15,'quarter past 3'],[30,'half past 3'],[45,'quarter to 4']]){c.innerHTML=clockSvg(3,m);w.textContent=t;playNote(m/5);await wait(1300)}}},
   {say:`The pattern: the numbers 1 to 12 are also <em>minute marks</em>. Each one is 5 minutes for the long hand. Count by fives round the clock: 5, 10, 15… all the way to 60.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);const w=el('div','bigword','');sc.appendChild(w);for(let i=1;i<=12;i++){c.innerHTML=clockSvg(3,i*5,true);w.textContent=String(i*5);playNote(i*5);await wait(380)}w.innerHTML='12 → <em>60 minutes</em> = 1 hour'}},
   {say:`<em>Why</em> the two hands move together: when the long hand goes all the way round once (60 minutes), the short hand moves exactly <em>one number</em>. That is one hour.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);const w=el('div','bigword','');sc.appendChild(w);for(let m=0;m<=60;m+=3){c.innerHTML=clockSvg(3,m);w.textContent=m===60?'the short hand is on 4':`${m} minutes`;await wait(70)}w.innerHTML='60 minutes = short hand <em>one number</em> on'}},
   {say:`The rule: <em>short hand first</em>, for the hour. Then the long hand, counting fives, for the minutes. Then say it: hour, minutes.`,draw:async(sc)=>{const c=el('div');c.innerHTML=clockSvg(7,40,true);sc.append(c,el('div','bigword','short: past 7 · long: 8 fives = 40'),el('div','bigword','<em>7:40</em>'))}},
   {say:`The trap: when the short hand is <em>between</em> two numbers, the hour is the <em>smaller</em> one, the number it has already passed. At 2:50 the short hand is almost at 3, but it is still 2 o'clock-something.`,draw:async(sc)=>{const c=el('div');c.innerHTML=clockSvg(2,50,true);sc.append(c,el('div','bigword','almost 3, but still <em>2</em>:50'))}},
   {say:`Where you meet it: school starts at 8:30, lunch at 12:00, and bedtime at 7:30. When the long hand reaches the 6 and the short hand is past 7, it is time for stories.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='10px';for(const [h,m,t] of [[8,30,'school'],[12,0,'lunch'],[7,30,'bedtime']]){const d=el('div');d.style.textAlign='center';d.innerHTML=clockSvg(h,m).replace('width:200px','width:100px')+`<div class="instr">${t}</div>`;r.appendChild(d)}sc.appendChild(r)}},
   {say:`Your turn! Drag the <em>long hand</em> round the clock to set the time I ask for.`,draw:async(sc)=>{const h=rnd(1,12),m=pick([0,30,15,45,10,20]);sc.appendChild(el('div','instr',`Set the clock to ${h}:${String(m).padStart(2,'0')}`));const c=el('div');c.style.touchAction='none';sc.appendChild(c);let cur=0;const out=el('div','bigword','');sc.appendChild(out);const draw=()=>{c.innerHTML=clockSvg(h,cur,true)};draw();
     const setFrom=e=>{const r=c.querySelector('svg').getBoundingClientRect();const x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2);let a=Math.atan2(x,-y)*180/Math.PI;if(a<0)a+=360;cur=Math.round(a/30)*5%60;draw();if(cur===m){out.innerHTML=`<em>${h}:${String(m).padStart(2,'0')}</em> ✓`;bugs('happy');confetti();playNote(20)}else out.textContent=`${h}:${String(cur).padStart(2,'0')}`};
     let down=false;c.addEventListener('pointerdown',e=>{down=true;setFrom(e)});c.addEventListener('pointermove',e=>{if(down)setFrom(e)});window.addEventListener('pointerup',()=>down=false)}},
   {say:`Your turn again. Read the clock and tap the time. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const c=el('div');const r=el('div','row');r.style.gap='8px';const big=el('div','bigword','');sc.append(c,r,big);const next=()=>{const h=rnd(1,12),m=pick([0,15,30,45]);c.innerHTML=clockSvg(h,m,true);const ans=`${h}:${String(m).padStart(2,'0')}`;const opts=shuffle([ans,`${h%12+1}:${String(m).padStart(2,'0')}`,`${h}:${String((m+30)%60).padStart(2,'0')}`]);r.innerHTML='';opts.forEach(o=>{const b=el('button','choice',o);b.onclick=()=>{if(o===ans){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`<em>${ans}</em>. You have it!`:ans;if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.textContent='Short hand first: which number has it passed?';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>counting by fives</em> (the long hand) and the same as <em>halves and quarters</em> (half past, quarter past). A clock is a number line bent into a circle.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','5, 10, 15… round the clock'));sc.appendChild(el('div','bigword','half past = <em>half</em> way round'))}}
  ],
  tries:()=>{const kind=pick(['read','read','fives','trap','digital']);const h=rnd(1,12);
   if(kind==='read'){const m=pick([0,30,15,45]);const opts=shuffle([`${h}:${String(m).padStart(2,'0')}`,`${h}:${String((m+15)%60).padStart(2,'0')}`,`${h%12+1}:${String(m).padStart(2,'0')}`]);return{q:'What time is it?',kind:'choice',opts,ans:`${h}:${String(m).padStart(2,'0')}`,draw:st=>{const c=el('div');c.innerHTML=clockSvg(h,m,true);st.appendChild(c)},explain:`Short hand near ${h}, long hand on the ${m===0?12:m/5}: ${h}:${String(m).padStart(2,'0')}.`}}
   if(kind==='fives'){const k=rnd(1,11);return{q:`The long hand is on the ${k}. How many minutes?`,kind:'num',ans:k*5,draw:st=>{const c=el('div');c.innerHTML=clockSvg(h,k*5,true);st.appendChild(c)},explain:`${k} fives: ${k*5} minutes.`}}
   if(kind==='trap')return{q:`The short hand is between ${h} and ${h%12+1}, nearly at ${h%12+1}. What is the hour?`,kind:'choice',opts:[String(h),String(h%12+1)],ans:String(h),draw:st=>{const c=el('div');c.innerHTML=clockSvg(h,50,true);st.appendChild(c)},explain:`Until it reaches ${h%12+1}, the hour is still ${h}.`};
   return{q:`Half past ${h}. How is that written on a digital clock?`,kind:'choice',opts:shuffle([`${h}:30`,`${h}:06`,`${h%12+1}:00`]),ans:`${h}:30`,draw:st=>{const c=el('div');c.innerHTML=clockSvg(h,30);st.appendChild(c)},explain:`Half past is 30 minutes: ${h}:30.`}}},
 {id:'history',title:'Before there were clocks',line:'Sun, shadows, sand and bells',door:'story',thing:'stickers',strand:'Time',book:'learned how people told time before clocks',
  pages:[
   {say:`Here is the idea. A clock is anything that <em>counts something steady</em>. Before machines, people found steady things in nature and counted those. This is the story of what they used.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','sun → shadow → sand → bell → <em>atom</em>'))}},
   {say:`Long, long ago there were no clocks at all. People looked at the <em>sun</em>. Low in the east: morning. High overhead: midday. Low in the west: evening.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=20;i++){const t=i/20;const x=40+320*t,y=150-130*Math.sin(Math.PI*t);d.innerHTML=`<svg viewBox="0 0 400 170" style="width:100%;max-width:420px"><path d="M40 150 Q200 -80 360 150" stroke="rgba(255,200,61,.4)" stroke-width="3" fill="none" stroke-dasharray="6 6"/><rect x="0" y="150" width="400" height="20" fill="var(--soil)"/><circle cx="${x}" cy="${y}" r="22" fill="#ffc83d"/><text x="40" y="168" font-size="12" fill="#fff" font-family="var(--display)">east</text><text x="330" y="168" font-size="12" fill="#fff" font-family="var(--display)">west</text></svg>`;await wait(90)}sc.appendChild(el('div','bigword','the sun was the first clock'))}},
   {say:`Then someone noticed <em>shadows</em>. A stick in the ground makes a shadow that swings round as the sun moves. Mark where the shadow falls each hour and you have a <em>sundial</em>.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=16;i++){const a=-70+140*(i/16);d.innerHTML=`<svg viewBox="0 0 300 180" style="width:100%;max-width:340px"><ellipse cx="150" cy="140" rx="120" ry="30" fill="rgba(255,255,255,.5)"/><g transform="rotate(${a} 150 140)"><rect x="147" y="60" width="6" height="80" fill="rgba(0,0,0,.35)"/></g><rect x="146" y="70" width="8" height="70" rx="3" fill="#6b4a2b"/><circle cx="${150+120*Math.sin(-a*Math.PI/180)}" cy="${40-20*Math.cos(a*Math.PI/180)}" r="16" fill="#ffc83d"/></svg>`;await wait(120)}sc.appendChild(el('div','bigword','a <em>sundial</em>'))}},
   {say:`<em>Why</em> the sundial works: the shadow moves because the Earth is turning under the sun, steadily, the same every day. Anything steady can be a clock. But a sundial does not work at night, or under clouds!`,draw:async(sc)=>{sc.appendChild(el('div','bigword','steady turning → steady shadow'));sc.appendChild(el('div','bigword','no sun, <em>no shadow</em>'))}},
   {say:`For the night they used things that <em>run out</em> steadily: water dripping from a bowl, sand falling through a glass, a candle with marks. When the sand is gone, the time is up!`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=20;i++){const t=i/20;d.innerHTML=`<svg viewBox="0 0 200 200" style="width:160px"><path d="M60 20h80l-35 80 35 80H60l35-80z" fill="rgba(255,255,255,.6)" stroke="var(--fg)" stroke-width="3"/><path d="M${65+30*t} ${22+70*t} L${135-30*t} ${22+70*t} L100 98z" fill="#f4a261"/><path d="M${100-38*t} 178 L${100+38*t} 178 L100 ${178-60*t}z" fill="#f4a261"/><rect x="99" y="98" width="2" height="${80*(t<1?1:0)}" fill="#f4a261"/></svg>`;await wait(100)}sc.appendChild(el('div','bigword','a <em>sand timer</em>'))}},
   {say:`A sand timer measures <em>how long</em>, not <em>what time</em>. It says "three minutes have passed", not "it is three o'clock". Those are two different questions, and both are time.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','sundial: <em>what time</em> is it?'));sc.appendChild(el('div','bigword','sand: <em>how long</em> has it been?'))}},
   {say:`About 700 years ago, people built the first big <em>clocks</em> in towers, with gears and a swinging weight, and bells so the whole town could hear the hour. Later clocks got small enough for a pocket, then for a <em>wrist</em>.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='flex-end';r.innerHTML=`<svg viewBox="0 0 80 140" style="width:70px"><rect x="20" y="40" width="40" height="100" fill="#b98a5b"/><path d="M15 40L40 10l25 30z" fill="#8a6442"/><circle cx="40" cy="70" r="14" fill="#fff" stroke="#1a1a1a" stroke-width="2"/><path d="M40 70V60M40 70l6 4" stroke="#1a1a1a" stroke-width="2"/></svg>`+clockSvg(10,10).replace('style="width:200px','style="width:90px')+`<svg viewBox="0 0 80 100" style="width:60px"><rect x="30" y="0" width="20" height="100" rx="6" fill="#2b4c9b"/><circle cx="40" cy="50" r="22" fill="#fff" stroke="#1a1a1a" stroke-width="3"/><path d="M40 50V36M40 50l9 5" stroke="#1a1a1a" stroke-width="2.5"/></svg>`;sc.appendChild(r);sc.appendChild(el('div','bigword','tower → pocket → <em>wrist</em>'))}},
   {say:`Even before clocks, the very first farmers watched the <em>Moon</em> and the <em>stars</em>. When a certain bright star rose at dawn, it was time to plant. They cut notches in a bone, one for each night: the first <em>calendar</em>.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);let stars='';for(let i=0;i<40;i++)stars+=`<circle cx="${rnd(5,395)}" cy="${rnd(5,90)}" r="${Math.random()*1.5+.6}" fill="#fff"/>`;d.innerHTML=`<svg viewBox="0 0 400 120" style="width:100%;max-width:420px"><rect width="400" height="120" fill="#1b2a4a" rx="12"/>${stars}<circle cx="340" cy="30" r="14" fill="#f3f0e6"/><rect x="0" y="100" width="400" height="20" fill="#3b2f22"/></svg>`;const bone=el('div');sc.appendChild(bone);let n='';for(let i=0;i<29;i++){n+=`<rect x="${20+i*12}" y="${i%7===6?8:14}" width="3" height="${i%7===6?26:14}" fill="#5a3f28"/>`}bone.innerHTML=`<svg viewBox="0 0 380 40" style="width:100%;max-width:400px"><rect x="8" y="6" width="364" height="28" rx="14" fill="#e9dcc3"/>${n}</svg>`;sc.appendChild(el('div','bigword','one notch, one night: <em>29</em> = a moon'))}},
   {say:`The pattern: every clock in this story counts something <em>steady</em>. Drips, sand, a swing, the turning sky. People kept finding things that were steadier, so clocks got better.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','drip… drip… drip…'));sc.appendChild(el('div','bigword','tick… tick… <em>tick…</em>'))}},
   {say:`The trap: a clock does not <em>make</em> time. Time passes whether anyone counts it or not. A clock only helps us <em>agree</em> on it, so we can meet at the same moment.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','no clock? time <em>still</em> passes'));sc.appendChild(el('div','bigword','a clock is for <em>agreeing</em>'))}},
   {say:`Today the best clocks count the tiny wobble of an <em>atom</em>, 9 billion times a second, and satellites send that time to the clock in your phone. From sun to shadow to sand to atom, always something steadier to count.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';r.innerHTML=`<svg viewBox="0 0 80 80" style="width:70px"><circle cx="40" cy="40" r="6" fill="var(--accent)"/><ellipse cx="40" cy="40" rx="34" ry="12" fill="none" stroke="var(--sky)" stroke-width="2"/><ellipse cx="40" cy="40" rx="34" ry="12" fill="none" stroke="var(--sky)" stroke-width="2" transform="rotate(60 40 40)"/><ellipse cx="40" cy="40" rx="34" ry="12" fill="none" stroke="var(--sky)" stroke-width="2" transform="rotate(120 40 40)"/></svg><div class="bigword">→</div><svg viewBox="0 0 60 100" style="width:44px"><rect x="8" y="4" width="44" height="92" rx="8" fill="#1a1a1a"/><rect x="12" y="12" width="36" height="72" fill="#fff"/><text x="30" y="52" text-anchor="middle" font-size="12" font-family="var(--display)" font-weight="700">7:45</text></svg>`;sc.appendChild(r);sc.appendChild(el('div','bigword','sun → shadow → sand → <em>atom</em>'))}},
   {say:`Your turn! Put the time-tellers in order, from the <em>oldest</em> to the newest.`,draw:async(sc)=>{const order=['stars','sundial','sand timer','tower clock','phone'];sc.appendChild(el('div','instr','Oldest on the left.'));const slots=el('div','srow wide');const zs=zones(5);zs.forEach(z=>{z.style.cssText='border-radius:12px;width:64px;height:54px';slots.appendChild(z)});const tray=el('div','srow tray wide');const tiles=shuffle(order).map(n=>{const t=el('div','it2');t.style.cssText='width:64px;height:54px';t.innerHTML=`<b style="position:static;width:62px;height:52px;font-size:.75rem;background:var(--plum);color:#fff;border-radius:10px;line-height:1.1;text-align:center">${n}</b>`;t.dataset.n=n;tray.appendChild(t);return t});sc.append(slots,tray);const out=el('div','bigword','');sc.appendChild(out);
     tiles.forEach(t=>makeDraggable(t,{onDrop:()=>{if(fullCount(zs)===5){const got=zs.map(z=>z.querySelector('.it2').dataset.n);const ok=got.every((v,i)=>v===order[i]);out.innerHTML=ok?'<em>Right order!</em>':'Not quite. What came first, the sun or the sundial?';if(ok){bugs('happy');confetti()}else bugs('think')}}}))}},
   {say:`Your turn again. Pip names a time-teller. Tap what it counts. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');sc.append(big,r);const items=[['sundial','a moving shadow'],['sand timer','sand running out'],['tower clock','a swinging weight'],['atomic clock','a wobbling atom'],['bone calendar','nights, one notch each']];const next=()=>{const [q,a]=pick(items);big.innerHTML=`a <em>${q}</em> counts…`;r.innerHTML='';shuffle(items.map(x=>x[1])).slice(0,5).forEach(o=>{const b=el('button','choice',o);b.style.fontSize='1rem';b.onclick=()=>{if(o===a){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${q}: <em>${a}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>Day and night</em>: the sundial works because we turn. And the same as <em>Reading the clock</em>: a clock is a steady count made easy to read.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','steady count → <em>clock</em>'))}}
  ],
  tries:()=>{const qs=[{q:'What did people use first to tell the time?',opts:['The sun','A wristwatch','A phone'],ans:'The sun',explain:'Low sun meant morning or evening, high sun meant midday.'},{q:'Why was a sundial no good at night?',opts:['No sun, no shadow','It was too heavy','It was too loud'],ans:'No sun, no shadow',explain:'A sundial needs sunlight to make a shadow.'},{q:'What did a sand timer measure?',opts:['How much time had passed','What time it was','How hot it was'],ans:'How much time had passed',explain:'When the sand ran out, the time was up.'},{q:'Which came last?',opts:['Wristwatch','Tower clock','Sundial'],ans:'Wristwatch',explain:'Clocks got smaller and smaller: tower, pocket, wrist.'},{q:'What did the first farmers watch to know when to plant?',opts:['The stars and the Moon','A phone','A sand timer'],ans:'The stars and the Moon',explain:'A bright star rising at dawn meant planting time; notches on a bone counted the nights.'},{q:'What does the best clock today count?',opts:['The wobble of an atom','Drips of water','Steps of a horse'],ans:'The wobble of an atom',explain:'Nine billion wobbles a second, sent to your phone by satellites.'},{q:'What do all clocks have in common?',opts:['They count something steady','They have hands','They are round'],ans:'They count something steady',explain:'Drips, sand, a swing, a wobble: always something steady.'},{q:'If every clock vanished, would time stop?',opts:['No, clocks only help us agree','Yes'],ans:'No, clocks only help us agree',explain:'Time passes whether anyone counts it or not.'}];const t=pick(qs);return{q:t.q,kind:'choice',opts:shuffle(t.opts),ans:t.ans,draw:()=>{},explain:t.explain}}},
 {id:'precious',title:'Why time is precious',line:'Three little stories',door:'story',thing:'strawberries',strand:'Time',book:'read the stories about why time is precious',
  pages:[
   {say:`Here is the idea. Every day has <em>24 hours</em>. You cannot buy more, and you cannot save one for tomorrow. When an hour is gone, it is gone. That is why time is the most precious thing you have.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);for(let h=0;h<=24;h++){c.innerHTML=clockSvg(h%12||12,0);await wait(70)}sc.appendChild(el('div','bigword','24 hours. <em>Every</em> day.'))}},
   {say:`A way to see it: a jar of 24 marbles, one for each hour. Sleeping takes about 10. School and meals take some more. What is left is <em>yours</em>, and it is not very many.`,draw:async(sc)=>{const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(8,30px);gap:5px';currentThing='marbles';const items=[];for(let i=0;i<24;i++){const d=dot('');d.style.width=d.style.height='28px';items.push(d);g.appendChild(d)}sc.appendChild(g);const w=el('div','bigword','24');sc.appendChild(w);await wait(800);for(let i=0;i<10;i++){items[i].classList.add('gone');await wait(90)}w.innerHTML='10 for sleep…';await wait(800);for(let i=10;i<18;i++){items[i].classList.add('gone');await wait(90)}w.innerHTML='8 for school and meals…';await wait(800);w.innerHTML='<em>6</em> left for you'}},
   {say:`<em>Pip and the sunrise.</em> Pip is me, the ladybug telling you this. I love sunrises. One night I said "I'll get up when I feel like it." The sun came up at 6… and I woke at 9. The sky was plain blue. The pink and gold had gone without me.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);d.innerHTML=`<div style="display:flex;gap:14px;align-items:flex-end"><svg viewBox="0 0 60 60" class="bug" style="width:70px;height:70px;transform:rotate(90deg)">${BUG}</svg>${clockSvg(9,0).replace('width:200px','width:120px')}</div>`;sc.appendChild(el('div','bigword','the sunrise doesn\'t wait'))}},
   {say:`The next night I set my leaf-alarm for 5:45. It was hard to get up. I was sleepy. I got up anyway. And I saw the <em>whole</em> sky turn gold. "Getting up was hard for one minute," I said, "and the sunrise was wonderful for thirty."`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);d.innerHTML=`<div style="display:flex;gap:14px;align-items:center"><svg viewBox="0 0 60 60" class="bug" style="width:70px;height:70px">${BUG}</svg>${clockSvg(5,45).replace('width:200px','width:120px')}</div>`;const sky=el('div');sky.style.cssText='width:100%;max-width:300px;height:40px;border-radius:12px;background:linear-gradient(90deg,#ff7a59,#ffc83d,#5aa9e6)';sc.append(sky,el('div','bigword','hard for 1 minute, <em>wonderful</em> for 30'))}},
   {say:`<em>Why</em> the sunrise story matters: some good things only happen at <em>one time</em>, and they do not wait. The hard minute is the price of the wonderful thirty. That is a good trade.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','1 hard minute'));sc.appendChild(el('div','bigword','for <em>30</em> wonderful ones'))}},
   {say:`<em>The half-built tower.</em> Max started a block tower, 20 blocks tall. At 12 blocks he got tired and bored. "I'll stop," he thought. Then he remembered: a half-built tower is not a tower at all. He put on 8 more. Finishing was the best part.`,draw:async(sc)=>{const t=el('div','towers');const a=el('div','tower');t.appendChild(a);sc.appendChild(t);for(let i=0;i<20;i++){const b=el('i');if(i>=12)b.style.background='var(--accent)';a.appendChild(b);await wait(i<12?70:160)}sc.appendChild(el('div','bigword','12 + <em>8</em> = finished'))}},
   {say:`<em>The strawberry's journey.</em> A strawberry on your plate took 3 months to grow. Rain fell on it. A farmer picked it at dawn. A truck drove it all night. Leaving it on the plate throws all of that away. Eating it says <em>thank you</em> to everyone who helped.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);currentThing='strawberries';const items=[];for(let i=0;i<5;i++){const d=dot('in');items.push(d);r.appendChild(d)}await appear(items,'',200);sc.appendChild(el('div','bigword','rain → farmer → truck → <em>you</em>'))}},
   {say:`The pattern in all three stories: time already spent, by you or by someone else, can be <em>wasted</em> or <em>kept</em>. Getting up, finishing, eating: each one keeps the time from being wasted.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','get up · finish · <em>say thank you</em>'))}},
   {say:`The trap: "later" feels free, but it is not. "I'll do it later" spends an hour from <em>tomorrow's</em> jar, and tomorrow's jar is just as small. Later is not extra time; it is the same time, moved.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','"later" = tomorrow\'s hour'));sc.appendChild(el('div','bigword','and tomorrow has <em>24</em> too'))}},
   {say:`Where you meet it: when the alarm goes, when a tower is half built, when a plate is half eaten, when a friend is waiting. Every one is a little choice about an hour you cannot get back.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','alarm · tower · plate · <em>friend</em>'))}},
   {say:`Your turn! Drag Pip's morning into the right order so she doesn't miss a thing.`,draw:async(sc)=>{const order=['wake up','brush teeth','eat breakfast','pack bag','go to school'];sc.appendChild(el('div','instr','First thing on the left.'));const slots=el('div','srow wide');const zs=zones(5);zs.forEach(z=>{z.style.cssText='border-radius:12px;width:64px;height:54px';slots.appendChild(z)});const tray=el('div','srow tray wide');const tiles=shuffle(order).map(n=>{const t=el('div','it2');t.style.cssText='width:64px;height:54px';t.innerHTML=`<b style="position:static;width:62px;height:52px;font-size:.72rem;background:var(--leaf);color:#fff;border-radius:10px;line-height:1.1;text-align:center">${n}</b>`;t.dataset.n=n;tray.appendChild(t);return t});sc.append(slots,tray);const out=el('div','bigword','');sc.appendChild(out);
     tiles.forEach(t=>makeDraggable(t,{onDrop:()=>{if(fullCount(zs)===5){const got=zs.map(z=>z.querySelector('.it2').dataset.n);const ok=got.every((v,i)=>v===order[i]);out.innerHTML=ok?'<em>A great morning!</em>':'Hmm. What has to happen before breakfast?';if(ok){bugs('happy');confetti()}else bugs('think')}}}))}},
   {say:`Your turn again. Pip tells you a moment. Tap what keeps the time from being wasted. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');sc.append(big,r);const items=[['The alarm rings at sunrise','get up now','sleep till 9'],['The tower is half built','finish it','leave it'],['Half the strawberries are left','eat them','throw them away'],['A friend is waiting to play','go now','say "later"']];const next=()=>{const [q,a,b]=pick(items);big.innerHTML=`<em>${q}.</em>`;r.innerHTML='';shuffle([a,b]).forEach(o=>{const btn=el('button','choice',o);btn.onclick=()=>{if(o===a){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${q}: <em>${a}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{btn.classList.add('miss');btn.disabled=true;big.innerHTML='That hour would be gone for good.';bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>What is time for?</em>, the next book: once you know an hour cannot come back, the question is what to spend it on.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','an hour spent well is <em>kept</em>'))}}
  ],
  tries:()=>{const qs=[{q:'What did Pip miss when she got up late?',opts:['The sunrise','Her breakfast','Her friend'],ans:'The sunrise',explain:'The sun came up at 6 and Pip woke at 9.'},{q:'Why did Max finish the tower?',opts:['A half-built tower is not a tower','He was told to','He was not tired'],ans:'A half-built tower is not a tower',explain:'He was tired, and he finished anyway. That was the best part.'},{q:'How long did the strawberry take to grow?',opts:['3 months','3 minutes','3 years'],ans:'3 months',explain:'Rain, a farmer, and a truck all helped it reach your plate.'},{q:'How many hours does a day have?',opts:['24','12','60'],ans:'24',explain:'And none of them can be saved for tomorrow.'},{q:'Getting up early was hard for Pip for how long?',opts:['About a minute','All day','A week'],ans:'About a minute',explain:'Hard for one minute, wonderful for thirty.'},{q:'"I\'ll do it later" means…',opts:['Spending an hour from tomorrow','Getting extra time','It costs nothing'],ans:'Spending an hour from tomorrow',explain:'Later is the same time, moved. Tomorrow has 24 hours too.'},{q:'Can you save an hour for tomorrow?',opts:['No','Yes, in a jar'],ans:'No',explain:'When an hour is gone, it is gone.'}];const t=pick(qs);return{q:t.q,kind:'choice',opts:shuffle(t.opts),ans:t.ans,draw:()=>{},explain:t.explain}}},
 {id:'daynight',title:'Day and night',line:'The Earth spins like a top',door:'pat',thing:'marbles',strand:'Time',book:'learned why we have day and night',
  pages:[
   {say:`Here is the idea. The Earth is a giant ball and it <em>spins</em>. The side facing the sun has day. The side facing away has night. Day and night are not the sun switching on and off; they are <em>us turning</em>.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=40;i++){d.innerHTML=globeSvg(i*9,true);await wait(70)}sc.appendChild(el('div','bigword','spin… <em>day</em>, night, day, night'))}},
   {say:`One full spin takes <em>24 hours</em>. That is one day. I'm Pip, the ladybug. I stand still, but the Earth turns me towards the sun in the morning and away at night.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);const w=el('div','bigword','');sc.appendChild(w);const labels=['midnight','sunrise','midday','sunset','midnight'];for(let i=0;i<=4;i++){d.innerHTML=globeSvg(180+i*90,true);w.textContent=labels[i];playNote(i*5);await wait(900)}w.innerHTML='one spin = <em>24 hours</em>'}},
   {say:`A second way to see it: a <em>torch and a ball</em> in a dark room. Shine the torch at the ball: one side is bright, the other dark. Turn the ball slowly and a spot on it goes bright, dark, bright, dark.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=30;i++){const t=i/30;d.innerHTML=`<svg viewBox="0 0 400 160" style="width:100%;max-width:420px"><rect x="330" y="60" width="50" height="40" rx="8" fill="#555"/><path d="M330 80L150 20v120z" fill="rgba(255,200,61,.25)"/><g transform="rotate(${t*360} 150 80)"><circle cx="150" cy="80" r="50" fill="#5aa9e6"/><path d="M150 30a50 50 0 0 0 0 100z" fill="rgba(0,0,0,.5)"/><circle cx="195" cy="80" r="6" fill="var(--accent)"/></g></svg>`;await wait(90)}sc.appendChild(el('div','bigword','the spot: bright, dark, bright, dark'))}},
   {say:`A third way: the <em>clock</em>. Midday is when your side faces the sun straight on, and the clock says 12. Midnight is the far side, and the clock says 12 again. Morning and evening are the edges, where the light is slanted and the sky goes orange.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);d.innerHTML=globeSvg(90,true,true);sc.appendChild(el('div','bigword','morning · <em>midday</em> · evening · night'))}},
   {say:`The pattern: it <em>never stops</em>. Day, night, day, night, every 24 hours, for as long as the Earth spins. That is why tomorrow always comes.`,draw:async(sc)=>{const strip=el('div','ways strip');for(let i=0;i<8;i++){const s=el('span','way',i%2?'night':'day');s.style.background=i%2?'#1b2a4a':'var(--sun)';s.style.color=i%2?'#fff':'#1a1a1a';strip.appendChild(s)}sc.append(strip,el('div','bigword','round and round, <em>forever</em>'))}},
   {say:`<em>Why</em> the sun seems to move: it does not. The sun sits still and <em>we</em> turn under it. Like when a car drives past and the trees seem to slide backwards: the trees are not moving, you are.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=30;i++){const t=i/30;d.innerHTML=`<svg viewBox="0 0 400 160" style="width:100%;max-width:420px"><circle cx="330" cy="80" r="30" fill="#ffc83d"/><g transform="rotate(${t*360} 120 80)"><circle cx="120" cy="80" r="50" fill="#5aa9e6"/><path d="M120 30a50 50 0 0 0 0 100z" fill="rgba(0,0,0,.35)"/><g transform="translate(160,70) scale(.33)">${BUG}</g></g></svg>`;await wait(90)}sc.appendChild(el('div','bigword','the sun stays. <em>we</em> turn.'))}},
   {say:`The rule, if you want to know what time of day it is on the globe: find where you are on the ball. Facing the sun is day. Facing away is night. On the edge, it is sunrise or sunset.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','facing the sun = <em>day</em>'));sc.appendChild(el('div','bigword','facing away = <em>night</em>'))}},
   {say:`Two traps. The sun does <em>not</em> go to sleep at night: it is still shining, on the other side of the world, where kids are having their day. And the moon is not "the night sun": it is a rock that reflects sunlight, and you can often see it in the daytime.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);d.innerHTML=globeSvg(0,true);sc.appendChild(el('div','bigword','my night = <em>their day</em>'))}},
   {say:`Where you meet it: when it is bedtime for you, children on the other side of the Earth are eating breakfast. And on a long summer day the sun seems to go across the sky: that is one spin, seen from the ground.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=20;i++){const t=i/20;const x=40+320*t,y=150-130*Math.sin(Math.PI*t);d.innerHTML=`<svg viewBox="0 0 400 170" style="width:100%;max-width:420px"><path d="M40 150 Q200 -80 360 150" stroke="rgba(255,200,61,.4)" stroke-width="3" fill="none" stroke-dasharray="6 6"/><rect x="0" y="150" width="400" height="20" fill="var(--soil)"/><circle cx="${x}" cy="${y}" r="22" fill="#ffc83d"/></svg>`;await wait(90)}sc.appendChild(el('div','bigword','the sun "crossing": us <em>turning</em>'))}},
   {say:`Your turn! Spin the Earth with your finger and stop when Pip the ladybug is at <em>midday</em>, facing the sun.`,draw:async(sc)=>{sc.appendChild(el('div','instr','Drag left or right to spin. Stop at midday.'));const d=el('div');d.style.touchAction='none';sc.appendChild(d);let ang=rnd(100,340),down=false,lastX=0;const out=el('div','bigword','');sc.appendChild(out);const draw=()=>{d.innerHTML=globeSvg(ang,true);const a=((ang%360)+360)%360;const label=a<22||a>338?'midnight':Math.abs(a-180)<22?'midday!':a<180?'morning':'evening';out.innerHTML=label==='midday!'?'<em>midday!</em>':label;if(label==='midday!'){bugs('happy');if(!d.done){d.done=true;confetti();playNote(20)}}};draw();
     d.addEventListener('pointerdown',e=>{down=true;lastX=e.clientX});d.addEventListener('pointermove',e=>{if(!down)return;ang+=(e.clientX-lastX)*1.2;lastX=e.clientX;draw()});window.addEventListener('pointerup',()=>down=false)}},
   {say:`Your turn again. Pip is somewhere on the globe. Tap what time of day it is for her. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const d=el('div');const r=el('div','row');const big=el('div','bigword','');sc.append(d,r,big);const next=()=>{const opts=[['midday',180],['midnight',0],['morning',110],['evening',250]];const [name,ang]=pick(opts);d.innerHTML=globeSvg(ang,true);r.innerHTML='';shuffle(opts).forEach(([o])=>{const b=el('button','choice',o);b.onclick=()=>{if(o===name){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`<em>${name}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.textContent='Is Pip facing the sun, away from it, or on the edge?';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same spin that makes the <em>clock</em> go round: the clock is a tiny copy of the Earth turning. 12 hours of light, 12 of dark, round and round.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';r.innerHTML=clockSvg(6,0).replace('width:200px','width:140px')+'<div class="bigword">=</div>'+globeSvg(180,true).replace('width:220px','width:140px');sc.appendChild(r)}}
  ],
  tries:()=>{const qs=[{q:'Why do we have night?',opts:['Our side of Earth turns away from the sun','The sun switches off','The moon covers the sun'],ans:'Our side of Earth turns away from the sun',explain:'The Earth keeps spinning; our side faces away for a while.'},{q:'How long does one spin of the Earth take?',opts:['24 hours','1 hour','1 year'],ans:'24 hours',explain:'One spin is one day.'},{q:'When is it midday?',opts:['When your side faces the sun straight on','When the moon is up','When it is cloudy'],ans:'When your side faces the sun straight on',explain:'Midnight is the opposite: the far side from the sun.'},{q:'Does the sun really move across the sky?',opts:['No, we turn','Yes, it flies','Only on Mondays'],ans:'No, we turn',explain:'Like trees sliding past a car window.'},{q:'When it is night for you, what is the sun doing?',opts:['Shining on the other side of the world','Sleeping','Turned off'],ans:'Shining on the other side of the world',explain:'Your night is their day.'},{q:'Can you see the moon in the daytime?',opts:['Yes, often','Never'],ans:'Yes, often',explain:'The moon is a rock reflecting sunlight. It is not a night-time sun.'}];const t=pick(qs);return{q:t.q,kind:'choice',opts:shuffle(t.opts),ans:t.ans,draw:()=>{},explain:t.explain}}},
 {id:'sixty',title:'Why 24, 60 and 60?',line:'Finger counting and a very friendly number',door:'puz',thing:'buttons',strand:'Time',book:'learned why hours have 60 minutes and days have 24 hours',
  pages:[
   {say:`Here is the idea. Nobody <em>found</em> 24 hours and 60 minutes in nature. People <em>chose</em> them, long ago, and they chose well. This book is the story of why.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','24 hours'));sc.appendChild(el('div','bigword','60 minutes'));sc.appendChild(el('div','bigword','60 seconds'))}},
   {say:`Long ago in Egypt, people counted on their fingers in a clever way: with the thumb, they touched the <em>three bones</em> of each of the other four fingers. 3 × 4 = <em>12</em> on one hand.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);const w=el('div','bigword','');sc.appendChild(w);for(let i=0;i<=12;i++){d.innerHTML=handSvg(i);w.textContent=i?String(i):'';if(i)playNote(i);await wait(260)}w.innerHTML='one hand = <em>12</em>'}},
   {say:`So they cut the daytime into <em>12</em> pieces, and the night into 12 more. 12 + 12 = <em>24</em> hours. That is why your clock has 12 numbers and goes round twice a day.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','12 day + 12 night'));await wait(600);sc.appendChild(el('div','bigword','= <em>24</em> hours'));const r=el('div','row');r.innerHTML=clockSvg(12,0).replace('width:200px','width:120px')+clockSvg(12,0).replace('width:200px','width:120px');sc.appendChild(r)}},
   {say:`Then the people of Babylon chose <em>60</em> for minutes and seconds. Why 60? Because 60 is the friendliest number there is: you can share it into halves, thirds, quarters, fifths and sixths with <em>nothing left over</em>.`,draw:async(sc)=>{const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(2,auto);gap:4px 20px;font-family:var(--display);font-size:1.4rem';sc.appendChild(g);for(const [k,v] of [[2,30],[3,20],[4,15],[5,12],[6,10],[10,6],[12,5]]){g.appendChild(el('div','',`60 ÷ ${k}`));g.appendChild(el('div','',`= <em style="font-style:normal;color:var(--accent)">${v}</em>`));playNote(k);await wait(220)}}},
   {say:`A second way to see "friendly": 60 buttons in <em>rows</em>. Rows of 2, rows of 3, rows of 4, rows of 5, rows of 6: every one comes out neat, no stragglers.`,draw:async(sc)=>{const g=el('div');sc.appendChild(g);const w=el('div','bigword','');sc.appendChild(w);for(const k of [4,5,6]){g.style.cssText=`display:grid;grid-template-columns:repeat(${60/k},14px);gap:3px;justify-content:center`;g.innerHTML='';for(let i=0;i<60;i++){const c=el('div','');c.style.cssText='width:14px;height:14px;border-radius:50%;background:var(--sky)';g.appendChild(c)}w.innerHTML=`${k} rows of <em>${60/k}</em>`;await wait(1100)}}},
   {say:`<em>Why</em> that matters for time: half an hour is 30 minutes, a quarter of an hour is 15, a third is 20. All whole numbers. "Meet me in a quarter of an hour" works because 60 shares so well.`,draw:async(sc)=>{const c=el('div');sc.appendChild(c);const w=el('div','bigword','');sc.appendChild(w);for(const [m,t] of [[30,'half: 30'],[15,'quarter: 15'],[20,'third: 20']]){c.innerHTML=clockSvg(12,m);w.innerHTML=t;playNote(m/5);await wait(1100)}}},
   {say:`The trap: try that with <em>100</em>. 100 ÷ 3 does not come out even, and neither does 100 ÷ 6. That is why nobody chose 100 minutes in an hour, even though 100 looks so neat.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','100 ÷ 3 = 33 and a bit ✗'));sc.appendChild(el('div','bigword','60 ÷ 3 = <em>20</em> ✓'));sc.appendChild(el('div','bigword','100 ÷ 6 = 16 and a bit ✗'))}},
   {say:`The rule for a "friendly" number: the more ways it can be shared with nothing left over, the friendlier it is. 12 is friendly (2, 3, 4, 6). 60 is a champion. 7 is not friendly at all: only 1 and 7.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','12: shares by 2, 3, 4, 6'));sc.appendChild(el('div','bigword','7: shares by <em>nothing</em> else'))}},
   {say:`Where you meet it: <em>eggs</em> come in dozens because 12 shares so well. A <em>year</em> has 12 months. A <em>foot</em> has 12 inches. People kept choosing 12 and 60 for the same reason.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','12 eggs, 12 months, 12 inches'));sc.appendChild(el('div','bigword','60 minutes, 60 seconds'))}},
   {say:`Your turn! Here are 60 buttons. Tap a number and see if 60 shares into that many equal rows with <em>nothing left over</em>.`,draw:async(sc)=>{sc.appendChild(el('div','instr','Tap a number: 2, 3, 4, 5, 6, 7, 8?'));const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(12,22px);gap:4px;justify-content:center';const cells=[];for(let i=0;i<60;i++){const c=el('div','');c.style.cssText='width:22px;height:22px;border-radius:50%;background:var(--sky);transition:background .3s';cells.push(c);g.appendChild(c)}sc.appendChild(g);const out=el('div','bigword','');sc.appendChild(out);const b=el('div','toybtns');[2,3,4,5,6,7,8].forEach(k=>{const kb=el('button','num',k);kb.style.minWidth='48px';kb.onclick=()=>{const cols=['var(--accent)','var(--leaf)','var(--sun)','var(--plum)','var(--sky)','#e63946','#f4a261','#2b4c9b'];const each=Math.floor(60/k),rem=60%k;cells.forEach((c,i)=>{const grp=Math.floor(i/each);c.style.background=i<each*k?cols[grp%cols.length]:'var(--line)'});out.innerHTML=rem===0?`60 ÷ ${k} = <em>${each}</em>. Perfect!`:`60 ÷ ${k}: ${each} each and <em>${rem} left over</em>. Not even!`;if(rem===0){bugs('happy');playNote(k*3)}else bugs('think')};b.appendChild(kb)});sc.appendChild(b)}},
   {say:`Your turn again. Tap the number that shares 60 with <em>nothing left over</em>. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');sc.append(big,r);const next=()=>{const good=pick([2,3,4,5,6,10,12]);const bad=pick([7,8,9,11]);big.innerHTML='Which shares 60 evenly?';r.innerHTML='';shuffle([good,bad]).forEach(v=>{const b=el('button','choice',v);b.onclick=()=>{if(v===good){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`60 ÷ ${good} = <em>${60/good}</em>, nothing left`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.innerHTML=`60 ÷ ${bad} leaves ${60%bad} over.`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same idea as <em>fair sharing</em>: the best numbers for sharing are the ones with lots of ways to split. And it is why the clock face has 12 numbers, each worth 5 minutes.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','12 = 2 × 6 = 3 × 4'));sc.appendChild(el('div','bigword','60 = 5 × 12 = <em>lots</em> of ways'))}}
  ],
  tries:()=>{const qs=[{q:'How did Egyptians get the number 12 on one hand?',opts:['3 bones on each of 4 fingers','12 fingers','They counted toes too'],ans:'3 bones on each of 4 fingers',explain:'Thumb touches each bone: 3 × 4 = 12.'},{q:'Why is 60 a good number for minutes?',opts:['It shares evenly in many ways','It is the biggest number','It is easy to write'],ans:'It shares evenly in many ways',explain:'Halves, thirds, quarters, fifths, sixths: no leftovers.'},{q:'12 hours of day plus 12 of night makes…',opts:['24','12','60'],ans:'24',explain:'That is why your clock goes round twice a day.'},{q:'Which of these does NOT share 60 evenly?',opts:['7','5','6'],ans:'7',explain:'60 ÷ 7 leaves 4 over. 60 ÷ 5 = 12 and 60 ÷ 6 = 10 are perfect.'},{q:'A quarter of an hour is how many minutes?',opts:['15','25','4'],ans:'15',explain:'60 ÷ 4 = 15.'},{q:'Why do eggs come in dozens?',opts:['12 shares well: by 2, 3, 4 and 6','Hens lay 12 a day','12 is the biggest box'],ans:'12 shares well: by 2, 3, 4 and 6',explain:'People kept choosing friendly numbers.'}];const t=pick(qs);return{q:t.q,kind:'choice',opts:shuffle(t.opts),ans:t.ans,draw:()=>{},explain:t.explain}}},
 {id:'mars',title:'A day on Mars',line:'Sols, moons, months and years',door:'story',thing:'stickers',strand:'Time',book:'learned about days on other worlds and where months and years come from',
  pages:[
   {say:`Here is the idea. A <em>day</em> is one spin of a world. A <em>month</em> is one trip of the Moon around us. A <em>year</em> is one trip of the Earth around the sun. Three clocks, all made of things going round.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','day = 1 <em>spin</em>'));sc.appendChild(el('div','bigword','month = 1 <em>moon</em>'));sc.appendChild(el('div','bigword','year = 1 trip round the <em>sun</em>'))}},
   {say:`Every planet spins, but not at the same speed. <em>Mars</em> spins a little slower than Earth. A Mars day is 24 hours and 37 minutes, and the people who drive the Mars rovers call it a <em>sol</em>.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=40;i++){d.innerHTML=`<div style="display:flex;gap:30px;align-items:center">${globeSvg(i*9,false).replace('width:220px','width:130px')}${globeSvg(i*8.7,false,false,'#e07a4a').replace('width:220px','width:110px')}</div>`;await wait(70)}sc.appendChild(el('div','bigword','Earth: 24 h &nbsp; Mars: 1 <em>sol</em> ≈ 24 h 37 min'))}},
   {say:`<em>Jupiter</em> is huge but spins super fast: a Jupiter day is only about <em>10 hours</em>! You would get a sunrise, lunch, and bedtime before an Earth day was even half done.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=40;i++){d.innerHTML=`<div style="display:flex;gap:24px;align-items:center">${globeSvg(i*9,false).replace('width:220px','width:110px')}${globeSvg(i*22,false,false,'#d9a066').replace('width:220px','width:180px')}</div>`;await wait(70)}sc.appendChild(el('div','bigword','Jupiter day ≈ <em>10 hours</em>'))}},
   {say:`The <em>Moon</em> turns so slowly that one Moon day lasts about <em>29 Earth days</em>. Two weeks of sunshine, then two weeks of dark. Imagine a bedtime that lasts two weeks!`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=40;i++){d.innerHTML=globeSvg(i*2.5,false,false,'#cfd3d6');await wait(70)}sc.appendChild(el('div','bigword','Moon day ≈ <em>29 Earth days</em>'))}},
   {say:`<em>Why</em> days are different lengths: a day is just one spin, and a world can spin fast or slow. There is nothing special about 24 hours; it is only how fast <em>our</em> ball happens to turn.`,draw:async(sc)=>{const strip=el('div','ways');[['Jupiter','10 h'],['Earth','24 h'],['Mars','24 h 37 m'],['Moon','29 days']].forEach(([n,t])=>{const s=el('span','way',`${n}: ${t}`);strip.appendChild(s)});sc.append(strip,el('div','bigword','fast spin = <em>short</em> day'))}},
   {say:`Now the <em>month</em>. The Moon goes round the Earth, and as it goes we see more or less of its lit side: thin, half, full, half, thin. One full round is about 29 days. That is where "month" comes from: a <em>moonth</em>.`,draw:async(sc)=>{const r=el('div','row');sc.appendChild(r);const phases=[0,.25,.5,.75,1,.75,.5,.25,0];for(const ph of phases){const m=el('div');m.innerHTML=`<svg viewBox="0 0 40 40" style="width:34px"><circle cx="20" cy="20" r="16" fill="#cfd3d6"/><path d="M20 4a16 16 0 0 1 0 32a${16*(1-2*ph)} 16 0 0 ${ph>.5?1:0} 0 -32z" fill="rgba(20,30,60,.85)"/></svg>`;r.appendChild(m);await wait(180)}sc.appendChild(el('div','bigword','29 days = 1 <em>month</em>'))}},
   {say:`And the <em>year</em>: one whole trip of the Earth around the sun, 365 days. On the way round, our tilt gives us the <em>seasons</em>: summer when our half leans toward the sun, winter when it leans away.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=24;i++){const a=i/24*2*Math.PI;d.innerHTML=`<svg viewBox="0 0 300 120" style="width:100%;max-width:320px"><ellipse cx="150" cy="60" rx="120" ry="40" fill="none" stroke="rgba(255,255,255,.6)" stroke-dasharray="5 5"/><circle cx="150" cy="60" r="18" fill="#ffc83d"/><circle cx="${150+120*Math.cos(a)}" cy="${60+40*Math.sin(a)}" r="9" fill="#5aa9e6"/></svg>`;await wait(60)}sc.appendChild(el('div','bigword','1 trip round the sun = 1 <em>year</em>'))}},
   {say:`The pattern: 7 days make a week, about 4 weeks make a month, 12 months make a year. So a year is 12 moons, and about 52 weeks, and 365 days. Different ways of counting the same trip.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','7 days = 1 week'));sc.appendChild(el('div','bigword','12 months = 1 year'));sc.appendChild(el('div','bigword','365 days = 1 <em>year</em>'))}},
   {say:`The trap: the Moon does not <em>make</em> light. It is a rock, and the "shape" we see is just the part the sun is lighting. A half moon is a whole moon with half of it in shadow.`,draw:async(sc)=>{const m=el('div');m.innerHTML=`<svg viewBox="0 0 40 40" style="width:120px"><circle cx="20" cy="20" r="16" fill="#cfd3d6"/><path d="M20 4a16 16 0 0 1 0 32a0 16 0 0 0 0 -32z" fill="rgba(20,30,60,.85)"/></svg>`;sc.append(m,el('div','bigword','a whole moon, <em>half</em> in shadow'))}},
   {say:`Where you meet it: your <em>birthday</em> comes once a trip round the sun. The <em>calendar</em> on the wall is 12 moons. And a rover on Mars wakes up every sol, 37 minutes later each Earth day.`,draw:async(sc)=>{const strip=el('div','ways strip');MONTHS.forEach(m=>strip.appendChild(el('span','way',m.slice(0,3))));sc.append(strip,el('div','bigword','12 moons = your next <em>birthday</em>'))}},
   {say:`Your turn! Put these days in order from the <em>shortest</em> to the longest.`,draw:async(sc)=>{const order=['Jupiter 10 h','Earth 24 h','Mars 24 h 37 m','Moon 29 days'];sc.appendChild(el('div','instr','Shortest day on the left.'));const slots=el('div','srow wide');const zs=zones(4);zs.forEach(z=>{z.style.cssText='border-radius:12px;width:74px;height:54px';slots.appendChild(z)});const tray=el('div','srow tray wide');const tiles=shuffle(order).map(n=>{const t=el('div','it2');t.style.cssText='width:74px;height:54px';t.innerHTML=`<b style="position:static;width:72px;height:52px;font-size:.72rem;background:var(--plum);color:#fff;border-radius:10px;line-height:1.1;text-align:center">${n}</b>`;t.dataset.n=n;tray.appendChild(t);return t});sc.append(slots,tray);const out=el('div','bigword','');sc.appendChild(out);
     tiles.forEach(t=>makeDraggable(t,{onDrop:()=>{if(fullCount(zs)===4){const got=zs.map(z=>z.querySelector('.it2').dataset.n);const ok=got.every((v,i)=>v===order[i]);out.innerHTML=ok?'<em>Right!</em> Jupiter is the speedy one.':'Not yet. Which spins fastest?';if(ok){bugs('happy');confetti()}else bugs('think')}}}))}},
   {say:`Your turn again. Pip names a stretch of time. Tap which clock it is: a spin, a moon, or a trip round the sun. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');sc.append(big,r);const items=[['a day','a spin'],['a month','a moon'],['a year','a trip round the sun'],['24 hours','a spin'],['29 days','a moon'],['365 days','a trip round the sun']];const next=()=>{const [q,a]=pick(items);big.innerHTML=`<em>${q}</em> is…`;r.innerHTML='';shuffle(['a spin','a moon','a trip round the sun']).forEach(o=>{const b=el('button','choice',o);b.onclick=()=>{if(o===a){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${q} = <em>${a}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>Day and night</em> (a day is a spin) and the same as <em>Days and months</em> on the Time door: the week and the year going round and round.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','spin · moon · <em>sun</em>'));sc.appendChild(el('div','bigword','three clocks, all going <em>round</em>'))}}
  ],
  tries:()=>{const qs=[{q:'What do rover drivers call a day on Mars?',opts:['A sol','A moon','A tick'],ans:'A sol',explain:'A sol is about 24 hours and 37 minutes.'},{q:'Which has the shortest day?',opts:['Jupiter','Earth','The Moon'],ans:'Jupiter',explain:'Jupiter spins round in about 10 hours.'},{q:'Where does the month come from?',opts:['The Moon going round once','The sun getting hotter','The Earth spinning once'],ans:'The Moon going round once',explain:'Thin crescent to full and back takes about 29 days.'},{q:'What is a year?',opts:['One trip of Earth round the sun','One spin of Earth','One Moon'],ans:'One trip of Earth round the sun',explain:'About 365 days.'},{q:'About how long is a day on the Moon?',opts:['29 Earth days','24 hours','10 hours'],ans:'29 Earth days',explain:'Two weeks of light, two weeks of dark.'},{q:'Why do days have different lengths on different worlds?',opts:['Worlds spin at different speeds','Some suns are bigger','Clocks are different there'],ans:'Worlds spin at different speeds',explain:'A day is one spin. Fast spin, short day.'},{q:'A half moon is…',opts:['A whole moon with half in shadow','Half a moon','A broken moon'],ans:'A whole moon with half in shadow',explain:'The Moon makes no light; we see the part the sun lights.'}];const t=pick(qs);return{q:t.q,kind:'choice',opts:shuffle(t.opts),ans:t.ans,draw:()=>{},explain:t.explain}}},
 {id:'purpose',title:'What is time for?',line:'Growing, learning, making, helping, resting',door:'story',thing:'strawberries',strand:'Time',book:'read about what time is for',
  pages:[
   {say:`Here is the idea. Time is not for keeping. It is for <em>spending</em>, like seeds. A seed in a jar stays a seed. A seed in the ground, given time, becomes a flower. This book is about what to plant.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);for(let i=0;i<=24;i++){const t=i/24;d.innerHTML=`<svg viewBox="0 0 200 160" style="width:180px"><rect x="0" y="130" width="200" height="30" fill="var(--soil)"/>${flowerSvg(100,130,t*70,'var(--accent)',1+t)}</svg>`;await wait(90)}sc.appendChild(el('div','bigword','time + seed = <em>flower</em>'))}},
   {say:`Time is for <em>growing</em>. You were a baby once. Hours of eating and sleeping and running made you bigger, and you did not even notice. Growing is time doing its quiet work.`,draw:async(sc)=>{const t=el('div','towers');t.style.alignItems='flex-end';sc.appendChild(t);for(const [n,l] of [[3,'baby'],[6,'two'],[9,'five']]){const c=el('div','tower');for(let i=0;i<n;i++)c.appendChild(el('i'));c.appendChild(el('b','',l));t.appendChild(c);await wait(600)}sc.appendChild(el('div','bigword','hours → <em>taller</em>'))}},
   {say:`Time is for <em>learning</em>. A year ago you could not read this sentence. Hours of looking at letters did that. Nobody can read for you; the hours have to be yours.`,draw:async(sc)=>{const w=el('div','bigword','c a t');sc.appendChild(w);await wait(900);w.innerHTML='<em>cat</em>';await wait(700);sc.appendChild(el('div','bigword','the cat sat on the mat'));await wait(700);sc.appendChild(el('div','bigword','…then a whole <em>book</em>'))}},
   {say:`Time is for <em>making</em> things that were not there before: a tower, a drawing, a garden, a song. The world has one more good thing in it because you spent an hour.`,draw:async(sc)=>{const t=el('div','towers');const a=el('div','tower');t.appendChild(a);sc.appendChild(t);for(let i=0;i<14;i++){const b=el('i');b.style.background=['var(--accent)','var(--sun)','var(--leaf)','var(--sky)','var(--plum)'][i%5];a.appendChild(b);await wait(110)}sc.appendChild(el('div','bigword','made by <em>you</em>'))}},
   {say:`Time is for <em>people</em>. When you give someone your time, listening, helping, playing, you give them something you can never get back. That is why it is the biggest gift there is.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';r.innerHTML=`<svg viewBox="0 0 60 60" style="width:64px">${BUG}</svg><div class="bigword">+</div><svg viewBox="0 0 60 60" style="width:64px;transform:scaleX(-1)">${BUG.replace(/#e63946/g,'#5aa9e6')}</svg>`;sc.appendChild(r);const h=el('div');h.innerHTML='<svg viewBox="0 0 60 60" style="width:60px"><path d="M30 52S6 36 6 20a12 12 0 0 1 24-4 12 12 0 0 1 24 4c0 16-24 32-24 32z" fill="var(--accent)"/></svg>';h.classList.add('pop');sc.appendChild(h);sc.appendChild(el('div','bigword','your time is a <em>gift</em>'))}},
   {say:`And time is for <em>resting</em>. Sleep is not wasted time: that is when your brain packs away everything you learned, like putting toys on the right shelf. Rest well, then go again.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);d.innerHTML=`<svg viewBox="0 0 220 120" style="width:220px"><rect x="10" y="60" width="200" height="50" rx="12" fill="#cfe3d7"/><rect x="20" y="40" width="60" height="30" rx="10" fill="#fff"/><g transform="translate(110,52) scale(.8)">${BUG}</g><text x="175" y="40" font-size="18" fill="var(--muted)" font-family="var(--display)">z</text><text x="188" y="26" font-size="22" fill="var(--muted)" font-family="var(--display)">z</text><text x="203" y="10" font-size="26" fill="var(--muted)" font-family="var(--display)">z</text></svg>`;sc.appendChild(el('div','bigword','rest is part of <em>growing</em>'))}},
   {say:`The pattern: five things time is for. <em>Grow, learn, make, help, rest.</em> A good day has a little of each. A day with none of them is a day that slipped away.`,draw:async(sc)=>{const strip=el('div','ways');['grow','learn','make','help','rest'].forEach((w,i)=>{const s=el('span','way',w);s.style.background=['var(--leaf)','var(--sky)','var(--accent)','var(--plum)','var(--sun)'][i];s.style.color=i===4?'#1a1a1a':'#fff';strip.appendChild(s)});sc.append(strip,el('div','bigword','a little of <em>each</em>'))}},
   {say:`<em>Why</em> it matters which you pick: an hour spent on a screen doing nothing leaves nothing behind. An hour spent on any of the five leaves something: a taller you, a new word, a tower, a happy friend, a rested brain.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','nothing → <em>nothing</em>'));sc.appendChild(el('div','bigword','grow, learn, make, help, rest → <em>something</em>'))}},
   {say:`The trap: thinking fun and these five are enemies. They are not! Making a tower is fun. Playing with a friend is helping. Learning a song is making. The best fun usually <em>is</em> one of the five.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','fun <em>and</em> making'));sc.appendChild(el('div','bigword','fun <em>and</em> helping'))}},
   {say:`Where you meet it: every morning, when you wake up with a fresh jar of hours and nobody has spent them yet. The jar is yours. What will you plant today?`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);d.innerHTML=`<svg viewBox="0 0 120 140" style="width:110px"><path d="M30 30h60v90a20 20 0 0 1-20 20H50a20 20 0 0 1-20-20z" fill="rgba(255,255,255,.6)" stroke="var(--fg)" stroke-width="3"/><rect x="26" y="20" width="68" height="14" rx="5" fill="var(--soil)"/>${Array.from({length:24},(_,i)=>`<circle cx="${42+(i%4)*12}" cy="${128-Math.floor(i/4)*12}" r="5" fill="var(--sun)"/>`).join('')}</svg>`;sc.appendChild(el('div','bigword','a fresh jar of <em>24</em>'))}},
   {say:`Your turn! Pick three things you want to spend time on <em>today</em> and drag them into your basket. There is no wrong answer.`,draw:async(sc)=>{const picks=['read a book','build something','help at home','play outside','learn a new thing','draw a picture','call a grandparent','practice maths'];sc.appendChild(el('div','instr','Three for today.'));const basket=el('div','pilebox tray');basket.style.cssText='min-height:64px;border:3px solid var(--sun)';const tray=el('div','srow tray wide');const tiles=shuffle(picks).map(n=>{const t=el('div','it2');t.style.cssText='width:76px;height:50px';t.innerHTML=`<b style="position:static;width:74px;height:48px;font-size:.7rem;background:var(--leaf);color:#fff;border-radius:10px;line-height:1.1;text-align:center">${n}</b>`;t.dataset.n=n;tray.appendChild(t);return t});sc.append(el('div','instr','my basket'),basket,tray);const out=el('div','bigword','');sc.appendChild(out);
     const chk=()=>{const got=Array.from(basket.querySelectorAll('.it2')).map(t=>t.dataset.n);if(got.length>=3){out.innerHTML=`<em>Today:</em> ${got.slice(0,3).join(', ')}.`;if(!basket.done){basket.done=true;addPage(`${KID()} chose to spend time on: ${got.slice(0,3).join(', ')}.`,false);save();bugs('happy');confetti()}}};tiles.forEach(t=>makeDraggable(t,{onDrop:chk}))}},
   {say:`Your turn again. Pip names something you might do. Tap which of the five it is. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');sc.append(big,r);const items=[['practising letters','learn'],['building a fort','make'],['a nap after lunch','rest'],['setting the table','help'],['eating your vegetables','grow'],['drawing a dragon','make'],['reading with Papa','learn'],['bedtime','rest']];const next=()=>{const [q,a]=pick(items);big.innerHTML=`<em>${q}</em> is for…`;r.innerHTML='';['grow','learn','make','help','rest'].forEach(o=>{const b=el('button','choice',o);b.onclick=()=>{if(o===a){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`${q}: <em>${a}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`So when something feels hard or boring, remember <em>Pip and the sunrise</em> (that's me, in Why time is precious): hard for a minute, wonderful for thirty. And when you're tired, rest. Then plant another seed.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','grow · learn · make'));sc.appendChild(el('div','bigword','help · <em>rest</em>'))}}
  ],
  tries:()=>{const qs=[{q:'What happens to a seed kept in a jar?',opts:['It stays a seed','It becomes a flower','It becomes a tree'],ans:'It stays a seed',explain:'Time only works on a seed that is planted.'},{q:'Is sleep wasted time?',opts:['No, the brain packs away what it learned','Yes, always','Only at night'],ans:'No, the brain packs away what it learned',explain:'Rest is part of growing.'},{q:'Why is giving someone your time a big gift?',opts:['You can never get it back','It costs money','It is heavy'],ans:'You can never get it back',explain:'An hour spent with someone is gone from your day, and given to theirs.'},{q:'What made you able to read?',opts:['Hours of looking at letters','A magic hat','Being born with it'],ans:'Hours of looking at letters',explain:'Nobody can read for you; the hours have to be yours.'},{q:'Which of the five is building a tower?',opts:['make','rest','grow'],ans:'make',explain:'Making leaves something new in the world.'},{q:'Are fun and the five things enemies?',opts:['No, the best fun is usually one of them','Yes'],ans:'No, the best fun is usually one of them',explain:'Building is fun and making. Playing with a friend is fun and helping.'},{q:'What are the five things time is for?',opts:['grow, learn, make, help, rest','eat, sleep, play, watch, wait','run, jump, hop, skip, stop'],ans:'grow, learn, make, help, rest',explain:'A good day has a little of each.'}];const t=pick(qs);return{q:t.q,kind:'choice',opts:shuffle(t.opts),ans:t.ans,draw:()=>{},explain:t.explain}}},
 {id:'shapes',strand:'Shapes',title:'Shapes and mirrors',line:'Sides, corners, turning and flipping',door:'space',thing:'buttons',book:'learned about sides, corners, turning and mirrors',
  pages:[
   {say:`Here is the idea. A shape is known by its <em>sides</em> and <em>corners</em>, not by its colour, its size, or which way up it is. A triangle has 3 sides and 3 corners. A square has 4 sides, all the same length.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='40px';sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(const [s,n,c] of [['tri',3,'var(--accent)'],['square',4,'var(--sky)']]){const d=el('div');d.innerHTML=`<svg viewBox="0 0 40 40" style="width:110px;height:110px">${shapes[s](c)}</svg>`;r.appendChild(d);const svg=d.firstChild;const pts=s==='tri'?[[20,4],[37,35],[3,35]]:[[5,5],[35,5],[35,35],[5,35]];for(let i=0;i<pts.length;i++){svg.insertAdjacentHTML('beforeend',`<circle cx="${pts[i][0]}" cy="${pts[i][1]}" r="3.5" fill="#1a1a1a"/>`);w.textContent=`${i+1} corner${i?'s':''}`;playNote(i+1);await wait(380)}await wait(400)}w.innerHTML='triangle: <em>3</em> · square: <em>4</em>'}},
   {say:`A circle has <em>no</em> corners and one round side. A rectangle has 4 corners like a square, but two sides are longer. Count corners and you can name almost anything.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='30px';[['circle','var(--leaf)','0 corners'],['square','var(--sky)','4 same sides']].forEach(([s,c,t])=>{const d=el('div');d.style.textAlign='center';d.innerHTML=`<svg viewBox="0 0 40 40" style="width:90px;height:90px">${shapes[s](c)}</svg><div class="instr">${t}</div>`;r.appendChild(d)});const rect=el('div');rect.style.textAlign='center';rect.innerHTML=`<svg viewBox="0 0 60 40" style="width:120px;height:80px"><rect x="4" y="8" width="52" height="24" rx="4" fill="var(--plum)"/></svg><div class="instr">4 corners, 2 long sides</div>`;r.appendChild(rect);sc.appendChild(r)}},
   {say:`<em>Turn</em> a shape round and it is still the same shape. A square standing on its corner is still a square. Turning is called a <em>rotation</em>, and it changes nothing about the shape.`,draw:async(sc)=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 40 40" style="width:120px;height:120px;transition:transform .6s">${shapes.square('var(--sky)')}</svg>`;sc.appendChild(d);const w=el('div','bigword','a square');sc.appendChild(w);for(const a of [45,90,135,180]){await wait(700);d.firstChild.style.transform=`rotate(${a}deg)`;w.innerHTML=a===45||a===135?'still a <em>square</em>':'a square'}}},
   {say:`A <em>mirror</em> flips. Left becomes right. The part touching the mirror stays touching it, and up stays up.`,draw:async(sc)=>{const g=PIECES.L;const r=el('div','row');r.style.alignItems='center';r.innerHTML=`${gridSvg(g,'var(--sky)')}<div class="mirrorline" style="height:120px"></div><div class="refl" style="width:${g[0].length*40}px"></div>`;sc.appendChild(r);await wait(900);const ref=r.querySelector('.refl');ref.innerHTML=gridSvg(flipH(g),'var(--accent)');ref.classList.add('pop');sc.appendChild(el('div','bigword','left ↔ <em>right</em>'))}},
   {say:`A second way to see a mirror: your own <em>hands</em>. Put them together: one is the mirror of the other. Thumbs meet in the middle, little fingers are far apart. You cannot turn a left hand into a right hand, only flip it.`,draw:async(sc)=>{const d=el('div');d.innerHTML=handSvg(0).replace('<svg','<svg style="transform:scaleX(-1)"');const e=el('div');e.innerHTML=handSvg(0);const r=el('div','row');r.style.gap='0';r.append(d,e);sc.append(r,el('div','bigword','left hand ↔ <em>right hand</em>'))}},
   {say:`<em>Why</em> turning and flipping are different: a turn slides round in a circle and every corner keeps its neighbours. A flip swaps them over. Turn the L as much as you like; its foot always points the same way <em>round</em>. Only a flip points it the other way.`,draw:async(sc)=>{const g=PIECES.L;const r=el('div','row');r.style.gap='22px';[[g,'start','var(--sky)'],[rot(rot(g)),'turned','var(--leaf)'],[flipH(g),'flipped','var(--accent)']].forEach(([x,t,c])=>{const d=el('div');d.style.textAlign='center';d.innerHTML=gridSvg(x,c,18)+`<div class="instr">${t}</div>`;r.appendChild(d)});sc.appendChild(r)}},
   {say:`The rule: to name a shape, <em>count its corners</em>. To check a mirror picture, ask: did left become right, with the touching part still touching? To check a turn, ask: is it the same shape, just spun?`,draw:async(sc)=>{sc.appendChild(el('div','bigword','corners → <em>name</em>'));sc.appendChild(el('div','bigword','left ↔ right → <em>mirror</em>'));sc.appendChild(el('div','bigword','spun round → <em>turn</em>'))}},
   {say:`Two traps. A thin, pointy triangle and a fat, wide triangle are <em>both</em> triangles: 3 corners is all it takes. And a mirror does <em>not</em> turn things upside down: up stays up, only left and right swap.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='24px';r.innerHTML=`<svg viewBox="0 0 40 40" style="width:80px;height:80px"><path d="M20 2L30 38H10z" fill="var(--accent)"/></svg><svg viewBox="0 0 40 40" style="width:80px;height:80px"><path d="M20 14L39 36H1z" fill="var(--accent)"/></svg>`;sc.append(r,el('div','bigword','both <em>triangles</em>: 3 corners'));await wait(900);sc.appendChild(el('div','bigword','mirror: up stays <em>up</em>'))}},
   {say:`Where you meet it: <em>road signs</em> (a triangle warns, a circle orders), <em>windows</em> and <em>doors</em> are rectangles, a <em>ball</em> is a circle from every side, and your face in the mirror has its hair parted on the other side.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='20px';r.innerHTML=`<svg viewBox="0 0 40 40" style="width:70px"><path d="M20 4L37 35H3z" fill="#e63946"/><path d="M20 9L33 32H7z" fill="#fff"/></svg><svg viewBox="0 0 40 40" style="width:70px"><circle cx="20" cy="20" r="17" fill="#e63946"/><circle cx="20" cy="20" r="12" fill="#fff"/></svg><svg viewBox="0 0 40 50" style="width:60px"><rect x="6" y="2" width="28" height="46" rx="3" fill="#b98a5b"/><circle cx="28" cy="26" r="2" fill="#1a1a1a"/></svg>`;sc.append(r,el('div','bigword','triangle warns · circle orders · <em>door</em>'))}},
   {say:`Your turn! Tap every <em>triangle</em>. Some are turned, some are big, some are small, but 3 corners means triangle.`,draw:async(sc)=>{const items=shuffle([['tri',1],['tri',1],['tri',1],['square',0],['circle',0],['star',0],['tri',1],['square',0]]);const cols=['var(--accent)','var(--leaf)','var(--sky)','var(--plum)'];const r=el('div','row');r.style.gap='14px';let got=0;const need=items.filter(x=>x[1]).length;const out=el('div','bigword','');sc.append(el('div','instr',`Find all ${need} triangles.`),r,out);
     items.forEach(([s,isT],i)=>{const b=el('button','');b.innerHTML=`<svg viewBox="0 0 40 40" style="width:56px;height:56px;transform:rotate(${rnd(0,3)*90+(s==='tri'?rnd(-30,30):0)}deg) scale(${s==='tri'?pick([.7,1,1.2]):1})">${shapes[s](cols[i%4])}</svg>`;b.onclick=()=>{if(b.done)return;b.done=true;if(isT){got++;b.style.outline='4px solid var(--sun)';b.style.borderRadius='12px';out.textContent=`${got} of ${need}`;playNote(got*3);if(got===need){out.innerHTML=`<em>${need}</em> triangles!`;bugs('happy');confetti()}}else{b.style.opacity='.35';out.textContent='Count its corners: not 3.';bugs('think')}};r.appendChild(b)})}},
   {say:`Your turn again. Pip shows a shape and three pictures. Tap the one that is its <em>mirror</em>, not its turn. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const top=el('div'),r=el('div','row'),big=el('div','bigword','');sc.append(top,r,big);const next=()=>{const g=PIECES[pick(['L','Z','P','C'])];const ans=flipH(g);top.innerHTML=`<div style="display:flex;align-items:center;gap:10px">${gridSvg(g,'var(--sky)',18)}<div class="mirrorline" style="height:70px"></div></div>`;const opts=shuffle([ans,rot(rot(g)),rot(g)]);r.innerHTML='';opts.forEach(o=>{const b=el('button','choice');b.innerHTML=gridSvg(o,'var(--accent)',14);b.onclick=()=>{if(sameGrid(o,ans)){b.classList.add('hit');got++;playNote(got*4);big.innerHTML='left became <em>right</em>'+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.textContent='That one is turned, not flipped.';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>Fit the hole</em> and <em>Mirror it</em>: a piece fits a hole when it is the same shape, maybe turned. And <em>Finish the mirror</em> is just flipping, square by square.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','same shape, <em>turned</em> → fits'));sc.appendChild(el('div','bigword','left ↔ right → <em>mirror</em>'))}}
  ],
  tries:()=>{const t=pick([{q:'How many corners does a triangle have?',kind:'num',ans:3,s:'tri',explain:'Tri means three: 3 sides, 3 corners.'},{q:'How many sides does a square have?',kind:'num',ans:4,s:'square',explain:'4 sides, all the same length, and 4 corners.'},{q:'How many corners does a circle have?',kind:'num',ans:0,s:'circle',explain:'A circle is one round side and no corners at all.'},{q:'Turn a square half way round. What is it now?',kind:'choice',opts:['Still a square','A triangle','A circle'],ans:'Still a square',s:'square',explain:'Turning never changes the shape.'},{q:'In a mirror, which way does a shape flip?',kind:'choice',opts:['Left and right','Up and down','It does not flip'],ans:'Left and right',s:'star',explain:'Left becomes right. Up stays up.'},{q:'A thin pointy triangle and a fat wide one are…',kind:'choice',opts:['Both triangles','Different shapes'],ans:'Both triangles',s:'tri',explain:'3 corners is all it takes.'}]);return{q:t.q,kind:t.kind,opts:t.opts&&shuffle(t.opts),ans:t.ans,draw:st=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 40 40" style="width:90px;height:90px">${shapes[t.s]('var(--sky)')}</svg>`;st.appendChild(d)},explain:t.explain}}},
 {id:'money',strand:'Measure',title:'Money',line:'Cents, coins and a dollar',door:'puz',thing:'buttons',book:'learned about cents, coins and a dollar',
  pages:[
   {say:`Here is the idea. We swap money for things. Money is counted in <em>cents</em>, and a coin is worth some number of cents. The number is written right on it. <em>¢</em> means cents.`,draw:async(sc)=>{const r=el('div','coins');sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let i=1;i<=5;i++){const c=coinBtn(COINS[0]);c.disabled=true;c.classList.add('pop');r.appendChild(c);w.innerHTML=`${i}¢`;playNote(i);await wait(400)}w.innerHTML='5 pennies = <em>5¢</em>'}},
   {say:`Four coins to know. <em>Penny</em> 1¢, <em>nickel</em> 5¢, <em>dime</em> 10¢, <em>quarter</em> 25¢. Read the number; that is the value.`,draw:async(sc)=>{const r=el('div','coins');sc.appendChild(r);for(const c of COINS){const w=coinBtn(c,true);w.btn.disabled=true;w.classList.add('pop');r.appendChild(w);playNote(c.v/5+1);await wait(500)}}},
   {say:`A second way to see a coin: as a <em>pile of pennies</em>. A nickel is 5 pennies squashed into one coin. A dime is 10 pennies. A quarter is 25 pennies. The coin is just quicker to carry.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';const n=coinBtn(COINS[1]);n.disabled=true;const pen=el('div','coins');for(let i=0;i<5;i++){const p=coinBtn(COINS[0]);p.disabled=true;p.style.width=p.style.height='28px';p.style.fontSize='.6rem';pen.appendChild(p)}r.append(n,el('div','bigword','='),pen);sc.append(r,el('div','bigword','1 nickel = <em>5</em> pennies'))}},
   {say:`A third way: <em>making the same amount</em> different ways. 10¢ is a dime, or two nickels, or ten pennies, or a nickel and five pennies. Same money, different coins.`,draw:async(sc)=>{const rows=[[COINS[2]],[COINS[1],COINS[1]],[COINS[1],COINS[0],COINS[0],COINS[0],COINS[0],COINS[0]]];for(const cs of rows){const r=el('div','coins');cs.forEach(c=>{const b=coinBtn(c);b.disabled=true;b.style.transform='scale(.8)';r.appendChild(b)});sc.appendChild(r);await wait(600)}sc.appendChild(el('div','bigword','all <em>10¢</em>'))}},
   {say:`The rule for counting coins: start with the <em>biggest</em> and count on. Quarter, dime, penny: <em>25, 35, 36</em>. Big first means fewer steps.`,draw:async(sc)=>{const r=el('div','coins');sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);let t=0;for(const c of [COINS[3],COINS[2],COINS[0]]){const b=coinBtn(c);b.disabled=true;b.classList.add('pop');r.appendChild(b);t+=c.v;w.textContent=`${t}¢`;playNote(t/3);await wait(800)}w.innerHTML='25, 35, <em>36¢</em>'}},
   {say:`<em>Why</em> the pattern: <em>100</em> cents make one <em>dollar</em>. Four quarters make a dollar: 25, 50, 75, 100. That is why it is called a quarter: a quarter of a dollar, like a quarter of a pizza.`,draw:async(sc)=>{const r=el('div','coins');sc.appendChild(r);const w=el('div','bigword','');sc.appendChild(w);for(let i=1;i<=4;i++){const b=coinBtn(COINS[3]);b.disabled=true;b.classList.add('pop');r.appendChild(b);w.textContent=`${i*25}¢`;playNote(i*5);await wait(700)}w.innerHTML='100¢ = <em>1 dollar</em>'}},
   {say:`The trap: the <em>dime</em> is the smallest coin, but it is worth <em>more</em> than the big nickel. Size does not tell you the value. The number does. Always read the number.`,draw:async(sc)=>{const r=el('div','coins');r.style.gap='30px';[COINS[1],COINS[2]].forEach(c=>{const w=coinBtn(c,true);w.btn.disabled=true;w.btn.style.transform='scale(1.5)';w.btn.style.margin='14px';r.appendChild(w)});sc.append(r,el('div','bigword','small dime: <em>10¢</em> · big nickel: 5¢'))}},
   {say:`Another trap: <em>more coins</em> is not more money. Three pennies is 3¢. One dime is 10¢. A small handful can be worth more than a big one. Count the cents, not the coins.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='30px';const a=el('div','coins');for(let i=0;i<3;i++){const b=coinBtn(COINS[0]);b.disabled=true;a.appendChild(b)}const b=coinBtn(COINS[2]);b.disabled=true;r.append(a,el('div','bigword','vs'),b);sc.append(r,el('div','bigword','3 coins = 3¢ · 1 coin = <em>10¢</em>'))}},
   {say:`Where you meet it: a <em>gumball</em> machine wants a quarter, a <em>sticker</em> costs a dime, and when you pay with a quarter for a 20¢ sticker, you get a nickel <em>back</em>. That is change.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','pay 25¢ for 20¢'));sc.appendChild(el('div','bigword','change: <em>5¢</em> back'))}},
   {say:`Your turn! Tap coins to make <em>15¢</em>. Tap a coin in the tray to take it back.`,draw:async(sc)=>{const target=15;const bar=el('div','coins'),tray=el('div','tray'),w=el('div','bigword','0¢');let sum=0;sc.append(el('div','instr','Make 15¢ with pennies, nickels and dimes.'),bar,tray,w);
     COINS.slice(0,3).forEach(c=>{const b=coinBtn(c,true);b.btn.onclick=()=>{const t=coinBtn(c);t.onclick=()=>{t.remove();sum-=c.v;w.textContent=sum+'¢'};tray.appendChild(t);sum+=c.v;w.textContent=sum+'¢';if(sum===target){w.innerHTML='<em>15¢</em>! Can you make it another way?';bugs('happy');confetti()}else if(sum>target){w.innerHTML=`${sum}¢ is too much`;bugs('think')}};bar.appendChild(b)})}},
   {say:`Your turn again, no tray. Pip shows some coins. Tap how many cents. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const r=el('div','coins'),big=el('div','bigword',''),ch=el('div','row');ch.style.gap='8px';sc.append(r,big,ch);const next=()=>{const cs=[pick(COINS)];cs.push(pick(COINS.slice(0,2)));if(Math.random()<.5)cs.push(COINS[0]);cs.sort((a,b)=>b.v-a.v);const total=cs.reduce((t,c)=>t+c.v,0);r.innerHTML='';cs.forEach(c=>{const b=coinBtn(c);b.disabled=true;r.appendChild(b)});big.textContent='how many cents?';const opts=shuffle([total,total+5,total-1,cs.length].filter((v,i,x)=>x.indexOf(v)===i&&v>0)).slice(0,4);if(!opts.includes(total))opts[0]=total;ch.innerHTML='';opts.forEach(v=>{const b=el('button','choice',v+'¢');b.onclick=()=>{if(v===total){b.classList.add('hit');got++;playNote(got*4);let run=0;big.innerHTML=cs.map(c=>run+=c.v).join(', ')+` = <em>${total}¢</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{b.classList.add('miss');b.disabled=true;big.textContent=v===cs.length?'Count the cents, not the coins.':`Start with the ${cs[0].name}: ${cs[0].v}, then count on.`;bugs('think')}};ch.appendChild(b)})};next()}},
   {say:`It's the same as <em>Make 10</em> (two nickels make a dime like 5 + 5), the same as <em>Tens and ones</em> (dimes are sticks, pennies are loose ones), and the same as <em>counting on</em>.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','5¢ + 5¢ = <em>10¢</em>'));sc.appendChild(el('div','bigword','2 dimes + 3 pennies = <em>23¢</em>'))}}
  ],
  tries:()=>{const t=pick([{q:'How much is a dime worth?',kind:'choice',opts:['10¢','5¢','1¢'],ans:'10¢',c:2,explain:'The dime is small but worth 10 cents.'},{q:'A nickel and a penny. How many cents?',kind:'num',ans:6,c:1,explain:'5, then one more: 6¢.'},{q:'How many quarters make a dollar?',kind:'num',ans:4,c:3,explain:'25, 50, 75, 100.'},{q:'Which coin is worth the most?',kind:'choice',opts:['quarter','dime','nickel'],ans:'quarter',c:3,explain:'A quarter is 25¢, a dime 10¢, a nickel 5¢.'},{q:'A dime and a nickel. How many cents?',kind:'num',ans:15,c:2,explain:'10, then 5 more: 15¢.'},{q:'Three pennies or one dime: which is more money?',kind:'choice',opts:['One dime','Three pennies'],ans:'One dime',c:2,explain:'3 coins is only 3¢. The dime is 10¢. Count cents, not coins.'},{q:'How many nickels make a dime?',kind:'num',ans:2,c:1,explain:'5 + 5 = 10.'}]);return{q:t.q,kind:t.kind,opts:t.opts&&shuffle(t.opts),ans:t.ans,draw:st=>{const w=coinBtn(COINS[t.c],true);w.btn.disabled=true;st.appendChild(w)},explain:t.explain}}},
 {id:'measuring',strand:'Measure',title:'Measuring',line:'How long, with no gaps',door:'meas',thing:'crayons',book:'learned how to measure with units laid end to end',
  pages:[
   {say:`Here is the idea. "How long?" is a counting question. Pick a <em>unit</em>, something small and all the same size, lay copies of it along the thing end to end, and <em>count them</em>. The count is the length.`,draw:async(sc)=>{const d=el('div');sc.appendChild(d);const w=el('div','bigword','');sc.appendChild(w);for(let n=0;n<=6;n++){d.innerHTML=`<svg viewBox="0 0 180 70" style="width:300px;max-width:100%"><rect x="10" y="10" width="144" height="26" rx="13" fill="#4cae7c"/>${Array.from({length:n},(_,i)=>`<rect x="${12+i*24}" y="44" width="20" height="14" rx="7" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}</svg>`;w.textContent=n?String(n):'';if(n)playNote(n);await wait(450)}w.innerHTML='<em>6</em> paperclips long'}},
   {say:`The rule: start right at the <em>end</em>, leave <em>no gaps</em>, no overlaps, and use units that are all the <em>same size</em>. Break any of those and the count is wrong.`,draw:async(sc)=>{const row=(ok)=>`<svg viewBox="0 0 180 70" style="width:280px;max-width:100%"><rect x="10" y="10" width="144" height="26" rx="13" fill="#4cae7c"/>${(ok?[0,1,2,3,4,5]:[0,1,3,4.6,5.2]).map(i=>`<rect x="${12+i*24}" y="44" width="20" height="14" rx="7" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}<text x="165" y="58" font-size="20" font-family="var(--display)" fill="${ok?'var(--leaf)':'var(--accent)'}">${ok?'✓':'✗'}</text></svg>`;const d=el('div');d.innerHTML=row(true)+row(false);sc.append(d,el('div','bigword','no gaps, <em>no overlaps</em>'))}},
   {say:`A second way to see it: <em>comparing</em>. Put two things side by side, starting at the same end. The one that sticks out further is longer. No units needed, just a fair start.`,draw:async(sc)=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 180 80" style="width:300px;max-width:100%"><line x1="10" y1="5" x2="10" y2="75" stroke="var(--fg)" stroke-width="2" stroke-dasharray="4 3"/><rect x="10" y="10" width="144" height="22" rx="11" fill="#9b6bd6"/><rect x="10" y="44" width="96" height="22" rx="11" fill="#f4a261"/></svg>`;sc.append(d,el('div','bigword','same start → purple is <em>longer</em>'))}},
   {say:`A third way: the <em>number line</em>. Each hop is one unit, all the same size, and you count the hops. A ruler is a number line you can hold.`,draw:async(sc)=>{const wk=el('div','walk');walkTo(wk,6);sc.append(wk,el('div','bigword','same-size hops, <em>counted</em>'))}},
   {say:`<em>Why</em> the unit has to be the same size: if some clips are big and some are small, "6 clips" could mean two different lengths. Same size means the count always means the same thing.`,draw:async(sc)=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 180 70" style="width:300px;max-width:100%"><rect x="10" y="10" width="144" height="26" rx="13" fill="#4cae7c"/>${[[12,20],[36,32],[72,16],[92,40],[136,16]].map(([x,w])=>`<rect x="${x}" y="44" width="${w}" height="14" rx="7" fill="var(--card)" stroke="var(--accent)" stroke-width="2"/>`).join('')}</svg>`;sc.append(d,el('div','bigword','5 mixed clips: <em>5 of what?</em>'))}},
   {say:`The trap: a <em>bigger</em> unit gives a <em>smaller</em> number. The same worm is 6 paperclips long but only 3 big blocks long. So always say the unit: "6 paperclips", not just "6".`,draw:async(sc)=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 180 110" style="width:300px;max-width:100%"><rect x="10" y="10" width="144" height="26" rx="13" fill="#4cae7c"/>${[0,1,2,3,4,5].map(i=>`<rect x="${12+i*24}" y="44" width="20" height="14" rx="7" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}${[0,1,2].map(i=>`<rect x="${12+i*48}" y="70" width="44" height="30" rx="4" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}</svg>`;sc.append(d,el('div','bigword','6 clips = <em>3</em> blocks'))}},
   {say:`Another trap: measuring from the <em>middle</em>. If the first clip starts half way along, the count comes out small. Start exactly at the end.`,draw:async(sc)=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 180 70" style="width:300px;max-width:100%"><rect x="10" y="10" width="144" height="26" rx="13" fill="#4cae7c"/>${[2,3,4,5].map(i=>`<rect x="${12+i*24}" y="44" width="20" height="14" rx="7" fill="var(--card)" stroke="var(--accent)" stroke-width="2"/>`).join('')}<text x="20" y="62" font-size="14" fill="var(--accent)" font-family="var(--display)">started here ✗</text></svg>`;sc.append(d,el('div','bigword','start at the <em>end</em>'))}},
   {say:`Where you meet it: how tall are you in <em>hands</em>? How long is the table in <em>steps</em>? How wide is the door in <em>shoes</em>? Anything can be a unit, as long as every copy is the same size.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','me = 7 <em>hands</em> tall'));sc.appendChild(el('div','bigword','table = 5 <em>steps</em> long'))}},
   {say:`Your turn! Tap to lay paperclips under the pencil, end to end, until it is covered. Then count them.`,draw:async(sc)=>{const len=rnd(4,7);const d=el('div');sc.appendChild(d);let n=0;const w=el('div','bigword','');sc.append(el('div','instr','Tap to add a paperclip.'),w);const draw=()=>{d.innerHTML=`<svg viewBox="0 0 190 70" style="width:300px;max-width:100%;cursor:pointer"><rect x="10" y="10" width="${len*24}" height="26" rx="8" fill="#f4a261"/>${Array.from({length:n},(_,i)=>`<rect x="${12+i*24}" y="44" width="20" height="14" rx="7" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}</svg>`;w.textContent=n?String(n):''};draw();
     d.onclick=()=>{if(n>=len+1)return;n++;draw();playNote(n);if(n===len){w.innerHTML=`<em>${len}</em> paperclips long!`;bugs('happy');confetti()}else if(n>len){w.innerHTML=`${n}: that one sticks out past the end`;bugs('think')}}}},
   {say:`Your turn again, no laying out. Pip shows a measured ribbon. Tap how long it is, with the unit. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const d=el('div'),big=el('div','bigword',''),r=el('div','row');r.style.gap='8px';sc.append(d,big,r);const next=()=>{const n=rnd(3,7);const bigU=Math.random()<.4;const uw=bigU?36:24;d.innerHTML=`<svg viewBox="0 0 ${20+n*uw} ${bigU?72:64}" style="width:${Math.min(320,(20+n*uw)*1.3)}px;max-width:100%"><rect x="10" y="10" width="${n*uw}" height="26" rx="8" fill="#9b6bd6"/>${Array.from({length:n},(_,i)=>`<rect x="${12+i*uw}" y="44" width="${uw-4}" height="${bigU?22:14}" rx="${bigU?3:7}" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}</svg>`;const unit=bigU?'blocks':'clips';big.textContent='how long?';const opts=shuffle([`${n} ${unit}`,`${n+1} ${unit}`,`${n} ${bigU?'clips':'blocks'}`,`${Math.max(1,n-1)} ${unit}`]);r.innerHTML='';opts.forEach(o=>{const b=el('button','choice',o);b.onclick=()=>{if(o===`${n} ${unit}`){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`<em>${n} ${unit}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.textContent=o.endsWith(unit)?'Count the units again, no gaps.':'Say the unit that is really there.';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as the <em>number line</em> (same-size hops, counted), the same as <em>Which has more?</em> (line them up from the same end), and it is what a <em>ruler</em> does, with the clips already drawn on.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','a ruler = clips <em>drawn on</em>'))}}
  ],
  tries:()=>{const t=pick([{q:'The ribbon is 4 paperclips long. A big block is as long as 2 paperclips. How many big blocks long?',kind:'num',ans:2,explain:'Every block is 2 clips: 2, 4. Two blocks.'},{q:'To measure well, the paperclips must have…',kind:'choice',opts:['no gaps between them','big gaps','some on top of each other'],ans:'no gaps between them',explain:'End to end, no gaps, no overlaps.'},{q:'A bigger unit gives a…',kind:'choice',opts:['smaller number','bigger number','the same number'],ans:'smaller number',explain:'Fewer big blocks fit than small clips.'},{q:'A worm is 3 blocks long. Each block is 2 clips. How many clips?',kind:'num',ans:6,explain:'2, 4, 6 clips.'},{q:'Where should the first paperclip go?',kind:'choice',opts:['Right at the end','In the middle','Anywhere'],ans:'Right at the end',explain:'Start at the end, or the count comes out small.'},{q:'Mixed big and small clips. Is the count a good measure?',kind:'choice',opts:['No, units must be the same size','Yes'],ans:'No, units must be the same size',explain:'"5 clips" must always mean the same length.'}]);return{q:t.q,kind:t.kind,opts:t.opts&&shuffle(t.opts),ans:t.ans,draw:st=>{const d=el('div');d.innerHTML=`<svg viewBox="0 0 180 60" style="width:240px"><rect x="10" y="10" width="96" height="26" rx="13" fill="#9b6bd6"/>${[0,1,2,3].map(i=>`<rect x="${12+i*24}" y="44" width="20" height="14" rx="7" fill="var(--card)" stroke="var(--fg)" stroke-width="2"/>`).join('')}</svg>`;st.appendChild(d)},explain:t.explain}}},
 {id:'rules',strand:'Patterns',title:'Rules and machines',line:'Do the same thing every time',door:'pat',thing:'marbles',book:'learned what a rule is and how to find one',
  pages:[
   {say:`Here is the idea. A <em>rule</em> is something you do the same way <em>every time</em>. "Add 2" is a rule: 3 becomes 5, 6 becomes 8, 10 becomes 12. Whatever goes in, the same thing happens to it.`,draw:async(sc)=>{const m=el('div','machine');m.appendChild(el('div','io head','<span>in</span><span></span><span>out</span>'));sc.appendChild(m);for(const x of [3,6,10]){const io=el('div','io',`<span>${x}</span><span>→</span><span class="q" style="color:var(--accent)">?</span>`);m.appendChild(io);await wait(600);io.querySelector('.q').textContent=x+2;io.querySelector('.q').style.color='';playNote(x);await wait(500)}m.appendChild(el('div','mbox','adds 2'))}},
   {say:`To <em>find</em> a rule, look at one row. 4 went in, 7 came out: it got bigger by 3. Then <em>check</em> it on another row: 9 → 12. Bigger by 3 again. The rule is "add 3".`,draw:async(sc)=>{const m=el('div','machine');m.innerHTML='<div class="io head"><span>in</span><span></span><span>out</span></div><div class="io"><span>4</span><span>→</span><span>7</span></div><div class="io"><span>9</span><span>→</span><span>12</span></div>';sc.appendChild(m);const w=el('div','bigword','');sc.appendChild(w);await wait(800);w.innerHTML='4 → 7: bigger by <em>3</em>';await wait(1200);w.innerHTML='9 → 12: bigger by <em>3</em> ✓';await wait(900);m.appendChild(el('div','mbox','adds 3'))}},
   {say:`A second kind of rule: <em>if-then</em>. IF it is red, THEN it goes in the box. The "if" is a test. The "then" is what you do when the test is true. If the test is false, nothing happens.`,draw:async(sc)=>{const r=el('div','row');r.style.alignItems='center';const tray=el('div','tray');tray.style.maxWidth='200px';const items=[['circle','var(--accent)',1],['square','var(--sky)',0],['star','var(--accent)',1],['tri','var(--leaf)',0]];const pile=el('div','row');items.forEach(([s,c])=>pile.appendChild(svgShape(s,c)));r.append(pile,el('div','plus','→'),tray);sc.append(el('div','bigword','IF red, THEN in the box'),r);await wait(800);for(const [s,c,go] of items){await wait(600);const e=pile.firstChild;if(go){tray.appendChild(e);playNote(10)}else{e.style.opacity='.3';pile.appendChild(e)}}}},
   {say:`A third way to see a rule: a <em>pattern</em>. 2, 4, 6, 8 is the rule "add 2" used over and over, each answer going back in. A rule run again and again makes a pattern.`,draw:async(sc)=>{const seq=el('div','seq');sc.appendChild(seq);const w=el('div','bigword','');sc.appendChild(w);let v=2;for(let i=0;i<5;i++){seq.appendChild(el('div','it',v));w.innerHTML=i?`${v-2} + 2 = <em>${v}</em>`:'2';playNote(v);v+=2;await wait(600)}w.innerHTML='<em>add 2</em>, again and again'}},
   {say:`<em>Why</em> rules are useful: once you know the rule, you can say what comes out for a number you have <em>never seen</em>. The machine adds 3? Then 100 goes to 103, without trying it.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','adds 3'));await wait(600);sc.appendChild(el('div','bigword','100 → <em>103</em>'));await wait(600);sc.appendChild(el('div','bigword','no need to try it'))}},
   {say:`The rule for finding rules: look at <em>one</em> row and ask "bigger or smaller, and by how much, or doubled?" Then <em>check</em> on a second row. If it works on both, you have it.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','1. one row: what happened?'));sc.appendChild(el('div','bigword','2. second row: <em>check</em>'))}},
   {say:`The trap: one row can fit <em>two</em> rules. 2 → 4 could be "add 2" or "double". You need a second row: 5 → 7 means add 2; 5 → 10 would mean double. Never trust one row.`,draw:async(sc)=>{const w=el('div','bigword','2 → 4');sc.appendChild(w);await wait(700);sc.appendChild(el('div','bigword','add 2? or <em>double</em>?'));await wait(1000);sc.appendChild(el('div','bigword','5 → 7 … so <em>add 2</em>'))}},
   {say:`Another trap: a rule is not a rule if it <em>changes</em>. 3 → 5, 6 → 9 is not one rule: the first adds 2, the second adds 3. A real rule does exactly the same thing every time.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','3 → 5 (+2)'));sc.appendChild(el('div','bigword','6 → 9 (+3) ✗ <em>not one rule</em>'))}},
   {say:`Where you meet it: <em>games</em> (if you land on a ladder, then you climb), <em>recipes</em> (every cookie gets the same two chips), <em>traffic lights</em> (if red, then stop), and <em>computers</em>, which are rules all the way down.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','IF red, THEN <em>stop</em>'));sc.appendChild(el('div','bigword','every cookie: <em>2 chips</em>'))}},
   {say:`Your turn! Pick a rule for your machine, then tap numbers to feed it and watch what comes out.`,draw:async(sc)=>{const rules=[['adds 2',x=>x+2],['adds 5',x=>x+5],['doubles it',x=>x*2],['takes away 1',x=>x-1]];let rule=null;const picks=el('div','toybtns');const m=el('div','machine');m.appendChild(el('div','io head','<span>in</span><span></span><span>out</span>'));const feed=el('div','toybtns');sc.append(el('div','instr','1. Pick a rule'),picks,m,el('div','instr','2. Feed it numbers'),feed);let fed=0;
     rules.forEach(([t,f])=>{const b=el('button','num',t);b.style.minWidth='96px';b.style.fontSize='1rem';b.onclick=()=>{rule=[t,f];picks.querySelectorAll('.num').forEach(x=>x.classList.remove('hit'));b.classList.add('hit');m.querySelectorAll('.io:not(.head)').forEach(x=>x.remove());const mb=m.querySelector('.mbox');if(mb)mb.remove();m.appendChild(el('div','mbox',t));fed=0};picks.appendChild(b)});
     [2,3,5,7,10].forEach(x=>{const b=el('button','num',x);b.onclick=()=>{if(!rule)return bugs('think');const io=el('div','io',`<span>${x}</span><span>→</span><span class="q" style="color:var(--accent)">?</span>`);m.insertBefore(io,m.querySelector('.mbox'));setTimeout(()=>{io.querySelector('.q').textContent=rule[1](x);io.querySelector('.q').style.color='';playNote(x);if(++fed===3){bugs('happy');confetti()}},500)};feed.appendChild(b)})}},
   {say:`Your turn again. Pip shows two rows of a machine. Tap the rule. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const m=el('div','machine'),r=el('div','row'),big=el('div','bigword','');r.style.gap='8px';sc.append(m,r,big);const all=[['adds 1',x=>x+1],['adds 2',x=>x+2],['adds 3',x=>x+3],['adds 5',x=>x+5],['takes away 1',x=>x-1],['takes away 2',x=>x-2],['doubles it',x=>x*2]];const next=()=>{const rule=pick(all);const ins=shuffle([2,3,4,5,6,7,8]).filter(x=>rule[1](x)>=1).slice(0,2);m.innerHTML='<div class="io head"><span>in</span><span></span><span>out</span></div>'+ins.map(x=>`<div class="io"><span>${x}</span><span>→</span><span>${rule[1](x)}</span></div>`).join('');const opts=shuffle([rule].concat(shuffle(all.filter(x=>x!==rule)).slice(0,2)));r.innerHTML='';opts.forEach(o=>{const b=el('button','choice',o[0]);b.style.fontSize='1rem';b.onclick=()=>{if(o===rule){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=`it <em>${rule[0]}</em>`+(got>=3?'. You have it!':'');if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{b.classList.add('miss');b.disabled=true;big.textContent=`Try it on the first row: ${ins[0]} goes in. Would ${o[1](ins[0])} come out?`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as the <em>Rule machine</em> and <em>If this, then that</em> games, the same as a <em>pattern</em>, and the same as <em>You make the rule</em>, where you are the machine.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','2 → 4 → 6 → 8'));sc.appendChild(el('div','bigword','<em>one rule</em>, every time'))}}
  ],
  tries:()=>{const t=pick([{q:'The machine adds 3. 6 goes in. What comes out?',kind:'num',ans:9,explain:'6 + 3 = 9.'},{q:'4 → 8 and 5 → 10. What is the rule?',kind:'choice',opts:['doubles it','adds 4','adds 5'],ans:'doubles it',explain:'4 + 4 = 8 and 5 + 5 = 10: doubling works for both rows.'},{q:'The rule is "take away 2". 9 goes in. What comes out?',kind:'num',ans:7,explain:'9 − 2 = 7.'},{q:'IF it is blue, THEN it goes in the box. A red star comes along. What happens?',kind:'choice',opts:['It stays out','It goes in the box','It turns blue'],ans:'It stays out',explain:'The test is "blue". Red fails the test, so the "then" does not happen.'},{q:'2 → 4. Which rule could it be?',kind:'choice',opts:['Both add 2 and double','Only add 2','Only double'],ans:'Both add 2 and double',explain:'One row is not enough. You need a second row to be sure.'},{q:'The machine adds 3. What comes out for 100?',kind:'num',ans:103,explain:'Once you know the rule, you can do any number: 100 + 3 = 103.'},{q:'3 → 5 and 6 → 9. Is that one rule?',kind:'choice',opts:['No, the first adds 2 and the second adds 3','Yes'],ans:'No, the first adds 2 and the second adds 3',explain:'A real rule does exactly the same thing every time.'}]);return{q:t.q,kind:t.kind,opts:t.opts&&shuffle(t.opts),ans:t.ans,draw:st=>{const m=el('div','machine');m.innerHTML='<div class="io head"><span>in</span><span></span><span>out</span></div>';st.appendChild(m)},explain:t.explain}}},
 {id:'bars',strand:'Ways of thinking',title:'Bars that tell a story',line:'Draw the story before you solve it',door:'story',thing:'marbles',book:'learned how a bar shows a story',
  pages:[
   {say:`Here is the whole idea in one sentence. A <em>bar</em> is a picture of a story: each number in the story is a piece of the bar, and the question is the piece with a <em>?</em>. ${KID()} has 4 red marbles and 3 blue. How many in all?`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);const A=[];for(let i=0;i<7;i++){const d=dot('');A.push(d);r.appendChild(d)}await appear(A,'',110)}},
   {say:`Watch the marbles squeeze into one bar. The red part, then the blue part, side by side. The <em>whole bar</em> is the question.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);for(let i=0;i<7;i++)r.appendChild(dot(''));await wait(700);r.remove();const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:3}],whole:'?'});sc.appendChild(b);await wait(900);sc.appendChild(el('div','bigword','4 + 3 = <em>7</em>'))}},
   {say:`A second shape. This time we know the <em>whole</em>: 9 marbles. 5 are red. The blue part is hidden inside the bar. Count up from 5 to 9: <em>4</em>.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:5,t:5,col:'var(--accent)'},{n:4,t:'?',q:1}],whole:9});sc.appendChild(b);await wait(1200);b.innerHTML=barSvg({parts:[{n:5,t:5,col:'var(--accent)'},{n:4,t:4}],whole:9});sc.appendChild(el('div','bigword','9 − 5 = <em>4</em>'))}},
   {say:`A third shape: two people, two bars, lined up at the left. ${KID()} has 8, Max has 5. The bit that <em>sticks out</em> is how many more ${KID()} has: <em>3</em>.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({compare:[{n:8,t:`${KID()} 8`},{n:5,t:'Max 5'}]});sc.appendChild(b);await wait(1200);b.innerHTML=barSvg({compare:[{n:8,t:`${KID()} 8`},{n:5,t:'Max 5'}],gap:3});sc.appendChild(el('div','bigword','8 − 5 = <em>3</em>'))}},
   {say:`The rule: a bar has <em>parts</em> and a <em>whole</em>. If you know the parts, add them to get the whole. If you know the whole and one part, take away to get the other part.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','part + part = <em>whole</em>'));await wait(600);sc.appendChild(el('div','bigword','whole − part = <em>part</em>'))}},
   {say:`<em>Why</em> it works: the bar is drawn to size. A part of 5 is longer than a part of 3, so your eyes see what the numbers say. Nothing is hidden except the ?.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:5,t:5,col:'var(--accent)'},{n:3,t:3}],whole:8});sc.appendChild(b);sc.appendChild(el('div','bigword','5 is <em>longer</em> than 3'))}},
   {say:`The trap: the ? is not always at the end. "How many in all" puts the ? over the whole bar. "How many are blue" puts the ? <em>inside</em> the bar. Read the question before you draw.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:3}],whole:'?'});const c=el('div','nline');c.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:'?',q:1}],whole:7});sc.append(b,c)}},
   {say:`Where you meet it: every story in the Stories door, and bigger ones later. In Russia, Singapore and many schools, children draw bars for years before they write an equation. The bar is the thinking; the sum is just the last line.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','draw it, <em>then</em> solve it'))}},
   {say:`Your turn! Read the story. Tap the bar that shows it. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const st=el('div','instr','');const b=el('div','bigword','');const r=el('div','row');r.classList.add('barpicks');sc.append(st,r,b);const next=()=>{const a=rnd(2,5),n=rnd(a+2,a+6),kind=pick(['whole','part','more']);st.textContent=kind==='whole'?`${KID()} has ${a} red marbles and ${n} blue. How many in all?`:kind==='part'?`${KID()} has ${n} marbles. ${a} are red. How many are blue?`:`${KID()} has ${n}. Max has ${a}. How many more does ${KID()} have?`;const bars={whole:barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n,t:n}],whole:'?'}),part:barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:n-a,t:'?',q:1}],whole:n}),more:barSvg({compare:[{n,t:`${KID()} ${n}`},{n:a,t:`Max ${a}`}],gap:'?'})};r.innerHTML='';b.textContent='';shuffle(['whole','part','more']).forEach(kd=>{const btn=el('button','choice');const d=el('div','barpick');d.innerHTML=bars[kd];btn.appendChild(d);btn.onclick=()=>{if(kd===kind){btn.classList.add('hit');got++;playNote(got*4);b.innerHTML=got>=3?'You have it!':'<em>Yes</em>, that shape.';if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{btn.classList.add('miss');btn.disabled=true;b.textContent=kind==='more'?'Two people: two bars.':kind==='whole'?'Both parts are known: the ? is the whole.':'The whole is known: the ? is inside.';bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`Your turn again, no picture. ${KID()} has 12 marbles, 7 are red. In your head, see the bar: whole 12, part 7, part ?. Tap the blue part.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const w=rnd(7,15),a=rnd(2,w-2),ans=w-a;big.innerHTML=`${w} in all, ${a} are red. How many blue?`;const opts=shuffle([ans,ans+1,w+a,Math.max(1,ans-1)].filter((v,i,x)=>x.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const btn=el('button','choice',v);btn.onclick=()=>{if(v===ans){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`${w} − ${a} = <em>${ans}</em>. You have it!`:`${w} − ${a} = <em>${ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{btn.classList.add('miss');btn.disabled=true;big.innerHTML=v===w+a?'Not together. The whole is already known.':`The whole bar is ${w}. Count up from ${a}.`;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>How far apart</em> (two bars, the bit that sticks out), <em>Find the missing number</em> (a part with a ?), and <em>Making ten</em> (two parts that fill a whole of 10).`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:6,t:6,col:'var(--accent)'},{n:4,t:'?',q:1}],whole:10});sc.appendChild(b);sc.appendChild(el('div','bigword','6 + <span class="ones">?</span> = 10'))}}
  ],
  tries:()=>{const kind=pick(['whole','part','more','shape']);const a=rnd(2,6),b=rnd(a+1,a+7);
   if(kind==='whole')return{q:`${a} red and ${b} blue. How many in all?`,kind:'num',ans:a+b,draw:st=>{const d=el('div','nline');d.innerHTML=barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:b,t:b}],whole:'?'});st.appendChild(d)},explain:`Both parts together: ${a} + ${b} = ${a+b}.`};
   if(kind==='part')return{q:`${b} in all. ${a} are red. How many blue?`,kind:'num',ans:b-a,draw:st=>{const d=el('div','nline');d.innerHTML=barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:b-a,t:'?',q:1}],whole:b});st.appendChild(d)},explain:`The whole is ${b}, one part is ${a}, so the other is ${b-a}.`};
   if(kind==='more')return{q:`${KID()} has ${b}. Max has ${a}. How many more does ${KID()} have?`,kind:'num',ans:b-a,draw:st=>{const d=el('div','nline');d.innerHTML=barSvg({compare:[{n:b,t:`${KID()} ${b}`},{n:a,t:`Max ${a}`}],gap:'?'});st.appendChild(d)},explain:`The bit that sticks out is ${b} − ${a} = ${b-a}.`};
   return{q:`"${b} marbles, ${a} are red, how many blue?" Where does the ? go?`,kind:'choice',opts:['over the whole bar','inside the bar, as a part'],ans:'inside the bar, as a part',draw:()=>{},explain:`The whole (${b}) is known. The blue part is the hidden piece inside the bar.`}}},
 {id:'backwards',strand:'Ways of thinking',title:'Walking backwards',line:'Start at the end and undo',door:'puz',thing:'stickers',book:'learned how to work backwards from the end of a story',
  pages:[
   {say:`Here is the whole idea in one sentence. When a story tells you the <em>end</em> but hides the <em>start</em>, walk backwards: go to the end and <em>undo</em> each thing that happened. I had some stickers, got 3 more, and now I have 8.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);const A=[];for(let i=0;i<8;i++){const d=dot('');A.push(d);r.appendChild(d)}await appear(A,'',100);sc.appendChild(el('div','bigword','now: 8'))}},
   {say:`Getting 3 more is undone by <em>taking 3 away</em>. Watch: 8, take the 3 that came last. What is left is where I started: <em>5</em>.`,draw:async(sc)=>{const r=row('');r.classList.add('wide');sc.appendChild(r);const A=[];for(let i=0;i<8;i++){const d=dot('');A.push(d);r.appendChild(d)}await wait(600);for(let i=7;i>=5;i--){A[i].classList.add('gone');playNote(i);await wait(350)}sc.appendChild(el('div','bigword','8 − 3 = <em>5</em>: I started with 5'))}},
   {say:`A second way to see it: on the number line. Forward 3 landed on 8. So walk <em>back</em> 3: 7, 6, 5.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=8;walkTo(w,pos);const b=el('div','bigword','8');sc.appendChild(b);for(let i=0;i<3;i++){await wait(650);pos--;walkTo(w,pos);b.textContent=String(pos);playNote(pos)}b.innerHTML='back 3: <em>5</em>'}},
   {say:`Every step has an <em>undo</em>. Got more? Take them away. Gave away? Put them back. Doubled? Halve. Halved? Double. The undo is the opposite step.`,draw:async(sc)=>{const ch=el('div','chain h');ch.innerHTML='<span class="node">got 3</span><span class="arrow undo">undo</span><span class="node">take 3</span>';const c2=el('div','chain h');c2.innerHTML='<span class="node">gave 2</span><span class="arrow undo">undo</span><span class="node">put 2 back</span>';const c3=el('div','chain h');c3.innerHTML='<span class="node">doubled</span><span class="arrow undo">undo</span><span class="node">halve</span>';sc.append(ch,c2,c3)}},
   {say:`When <em>two</em> things happened, undo the <em>last</em> one first, like taking off your shoes before your socks. Got 4, then gave 2, now 9. Undo "gave 2": 11. Undo "got 4": <em>7</em>.`,draw:async(sc)=>{const ch=el('div','chain');ch.innerHTML='<span class="node q">?</span><span class="arrow">got 4</span><span class="node q">?</span><span class="arrow">gave 2</span><span class="node">9</span>';sc.appendChild(ch);const ns=ch.querySelectorAll('.node'),as=ch.querySelectorAll('.arrow');await wait(900);as[1].textContent='put 2 back';as[1].classList.add('undo');ns[1].textContent='11';ns[1].classList.remove('q');ns[1].classList.add('glow');await wait(1000);as[0].textContent='take 4 away';as[0].classList.add('undo');ns[0].textContent='7';ns[0].classList.remove('q');ns[0].classList.add('glow');sc.appendChild(el('div','bigword','started with <em>7</em>'))}},
   {say:`<em>Why</em> it works: a step and its undo cancel out. Forward 3 then back 3 leaves you exactly where you were. So undoing every step, from the end, walks you back to the start.`,draw:async(sc)=>{const w=el('div','walk');sc.appendChild(w);let pos=5;walkTo(w,pos);const b=el('div','bigword','5');sc.appendChild(b);for(let i=0;i<3;i++){await wait(400);pos++;walkTo(w,pos);b.textContent=String(pos)}await wait(500);for(let i=0;i<3;i++){await wait(400);pos--;walkTo(w,pos);b.textContent=String(pos)}b.innerHTML='forward 3, back 3: <em>home</em>'}},
   {say:`The trap: going <em>forwards</em> from the end. "Got 3 more, now 8" is not 8 + 3. The 3 came <em>after</em> the start, so to find the start you take it <em>off</em>. Always ask: which way undoes it?`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 + 3 = 11 ✗'));await wait(700);sc.appendChild(el('div','bigword','8 − 3 = <em>5</em> ✓'))}},
   {say:`Where you meet it: "I spent 4 and have 6 left, how much did I have?" "The bus dropped 3 people and 7 are on it, how many got on?" And every maze: the way out is easy to find from the exit.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','spent 4, have 6: <em>10</em>'));sc.appendChild(el('div','bigword','3 got off, 7 left: <em>10</em>'))}},
   {say:`Your turn! Read it, then tap where the story <em>started</em>. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const start=rnd(2,9),n=rnd(1,5),op=pick(['+','-']);const end=op==='+'?start+n:start-n;if(end<1){next();return}big.innerHTML=`Had some. ${op==='+'?`Got ${n} more`:`Gave ${n} away`}. Now ${end}. Started with?`;const wrong=op==='+'?end+n:end-n;const opts=shuffle([start,wrong,start+1,Math.max(1,start-1)].filter((v,i,x)=>x.indexOf(v)===i&&v>0)).slice(0,4);if(!opts.includes(start))opts[0]=start;r.innerHTML='';opts.forEach(v=>{const btn=el('button','choice',v);btn.onclick=()=>{if(v===start){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`Started with <em>${start}</em>. You have it!`:`${end} ${op==='+'?'−':'+'} ${n} = <em>${start}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,800)}else{btn.classList.add('miss');btn.disabled=true;big.innerHTML=v===wrong?'That went forwards. Undo it instead.':`Start at ${end} and ${op==='+'?`take ${n} away`:`put ${n} back`}.`;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Find the missing number</em> (? + 3 = 8), the same as the <em>Rule machine</em> run in reverse, and the same as <em>How far apart</em>: the gap between the end and the start.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','<span class="ones">?</span> + 3 = 8'));sc.appendChild(el('div','bigword','8 − 3 = <em>5</em>'))}}
  ],
  tries:()=>{const kind=pick(['one','one','two','undo']);const s=rnd(2,9),n=rnd(1,5);
   if(kind==='one'){const op=pick(['+','-']);const end=op==='+'?s+n:Math.max(1,s-n);const st=op==='+'?end-n:end+n;return{q:`Had some. ${op==='+'?`Got ${n} more`:`Gave ${n} away`}. Now ${end}. How many at the start?`,kind:'num',ans:st,draw:x=>{const ch=el('div','chain');ch.innerHTML=`<span class="node q">?</span><span class="arrow">${op==='+'?`got ${n}`:`gave ${n}`}</span><span class="node">${end}</span>`;x.appendChild(ch)},explain:`Undo it: ${end} ${op==='+'?'−':'+'} ${n} = ${st}.`}}
   if(kind==='two'){const a=rnd(1,4),b=rnd(1,4);const end=s+a-b;if(end<1)return null;return{q:`Had some. Got ${a} more, then gave ${b} away. Now ${end}. How many at the start?`,kind:'num',ans:s,draw:x=>{const ch=el('div','chain');ch.innerHTML=`<span class="node q">?</span><span class="arrow">got ${a}</span><span class="node q">?</span><span class="arrow">gave ${b}</span><span class="node">${end}</span>`;x.appendChild(ch)},explain:`Last thing first: ${end} + ${b} = ${end+b}, then ${end+b} − ${a} = ${s}.`}}
   const op=pick(['got more','gave away','doubled']);const und={'got more':'take away','gave away':'put back','doubled':'halve'}[op];return{q:`To undo "${op}", you…`,kind:'choice',opts:shuffle(['take away','put back','halve']),ans:und,draw:()=>{},explain:`The undo is the opposite step: "${op}" is undone by "${und}".`}}},
 {id:'tricks',strand:'Ways of thinking',title:'Tricks with names',line:'Know the name, know what to do',door:'add',thing:'marbles',book:'learned the names of the adding tricks',
  pages:[
   {say:`Here is the whole idea in one sentence. Good adders do not count every dot: they look at the two numbers, spot a <em>trick</em>, and the trick has a <em>name</em>. Say the name and you know what to do. Here are the names.`,draw:async(sc)=>{for(const t of ['Doubles','Near doubles','Count on','Ten and more','Make ten']){sc.appendChild(el('div','bigword',t));await wait(350)}}},
   {say:`<em>Doubles</em>: the same number twice. 4 + 4. Two rows, the same. You just know it: 8. Doubles are the ones to learn by heart.`,draw:async(sc)=>{const d=el('div','ta');d.innerHTML=TRICKS.dbl.pic(4,4);sc.appendChild(d);await wait(700);sc.appendChild(el('div','bigword','4 + 4 = <em>8</em>'))}},
   {say:`<em>Near doubles</em>: one apart, like 4 + 5. Do the double, 4 + 4 = 8, then add the one that is left over: <em>9</em>.`,draw:async(sc)=>{const d=el('div','ta');d.innerHTML=TRICKS.near.pic(4,5);sc.appendChild(d);await wait(700);sc.appendChild(el('div','bigword','8 + 1 = <em>9</em>'))}},
   {say:`<em>Count on</em>: when one number is tiny, 1 or 2. 7 + 2: do not start at 1. Start at the big one, 7, and hop: 8, <em>9</em>.`,draw:async(sc)=>{const d=el('div','ta');d.innerHTML=TRICKS.on.pic(7,2);sc.appendChild(d);await wait(700);sc.appendChild(el('div','bigword','7… 8, <em>9</em>'))}},
   {say:`<em>Ten and more</em>: when one number is 10. 10 + 3 is just a ten and 3 ones: <em>13</em>. The ten does all the work.`,draw:async(sc)=>{const d=el('div','ta');d.innerHTML=TRICKS.tenmore.pic(10,3);sc.appendChild(d);await wait(700);sc.appendChild(el('div','bigword','10 + 3 = <em>13</em>'))}},
   {say:`<em>Make ten</em>: when one number is 7, 8 or 9. 8 + 5: eight is nearly ten, so borrow 2 from the 5 to fill the ten. Then 10 and 3: <em>13</em>.`,draw:async(sc)=>{const d=el('div','ta');d.innerHTML=dotRows([{n:8},{n:5}]);sc.appendChild(d);await wait(1000);d.innerHTML=TRICKS.ten.pic(8,5);await wait(500);sc.appendChild(el('div','bigword','10 + 3 = <em>13</em>'))}},
   {say:`The rule: <em>look before you count</em>. Same numbers? Doubles. One apart? Near doubles. One is tiny? Count on. One is 10? Ten and more. One is 8 or 9? Make ten.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','same → Doubles'));sc.appendChild(el('div','bigword','one apart → Near doubles'));sc.appendChild(el('div','bigword','tiny → Count on'));sc.appendChild(el('div','bigword','8 or 9 → Make ten'))}},
   {say:`<em>Why</em> names help: a name is a handle. "Near doubles" is three words that carry the whole plan. When grown-ups say "I just know it", this is what they mean: they saw the trick before they started.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','see the trick <em>first</em>'))}},
   {say:`The trap: counting every dot from one. It works, but it is slow, and you lose your place. Counting all of 8 + 5 is 13 counts. Make ten is <em>two moves</em>.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','count all: 13 counts'));await wait(700);sc.appendChild(el('div','bigword','make ten: <em>2</em> moves'))}},
   {say:`Your turn! Look at the sum and tap the trick. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(big,r);const next=()=>{const p=trickProblem(2);if(!p){next();return}big.innerHTML=`${p.a} + ${p.b}`;r.innerHTML='';p.opts.forEach(id=>{const btn=el('button','choice',TRICKS[id].name);btn.onclick=()=>{if(id===p.id){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`${TRICKS[id].name}: ${p.a} + ${p.b} = <em>${p.ans}</em>. You have it!`:`${TRICKS[id].name}: <em>${p.ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{btn.classList.add('miss');btn.disabled=true;big.textContent=TRICKS[id].no;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Making ten</em> (the Make ten trick), <em>Double and half</em> (the Doubles trick) and <em>Counting on</em>. The tricks are those ideas with their names on.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 + 5 = 10 + <em>3</em>'));sc.appendChild(el('div','bigword','6 + 6 = <em>12</em>'))}}
  ],
  tries:()=>{const kind=pick(['name','name','use','why']);const p=trickProblem(2);if(!p)return null;const T=TRICKS[p.id];
   if(kind==='name')return{q:`${p.a} + ${p.b}: which trick?`,kind:'choice',opts:p.opts.map(id=>TRICKS[id].name),ans:T.name,draw:st=>st.appendChild(el('div','bigword',`${p.a} + ${p.b}`)),explain:`${T.name}. ${T.why(p.a,p.b)}`};
   if(kind==='use')return{q:`Use ${T.name}: ${p.a} + ${p.b} = ?`,kind:'num',ans:p.ans,draw:st=>{const d=el('div','ta');d.innerHTML=T.pic(p.a,p.b);st.appendChild(d)},explain:T.why(p.a,p.b)};
   return{q:`Make ten is for…`,kind:'choice',opts:['a number near 10, like 8 or 9','two numbers the same'],ans:'a number near 10, like 8 or 9',draw:()=>{},explain:'Make ten borrows a few to fill the ten: 8 + 5 becomes 10 + 3.'}}},
 {id:'reading',strand:'Ways of thinking',title:'Reading a story',line:'Know, want, picture, solve, check',door:'story',thing:'marbles',book:'learned the five steps for reading a story problem',
  pages:[
   {say:`Here is the whole idea in one sentence. A story problem is not "find two numbers and add them". It is a <em>story</em>, and you read it like a detective: <em>know</em>, <em>want</em>, <em>picture</em>, <em>solve</em>, <em>check</em>. Five words. Say them with me.`,draw:async(sc)=>{for(const w of ['know','want','picture','solve','check']){sc.appendChild(el('div','bigword',w));await wait(400)}}},
   {say:`<em>Know</em>: what does the story tell us? Not the numbers first, the <em>facts</em>. "Max has 3 red marbles and 5 blue." We know: 3 red. 5 blue. That is all.`,draw:async(sc)=>{sc.appendChild(el('div','story','Max has 3 red marbles and 5 blue marbles. How many in all?'));await wait(800);sc.appendChild(el('div','bigword','know: 3 red, 5 blue'))}},
   {say:`<em>Want</em>: what is it asking? The question is usually the last sentence. "How many in all?" Say it in your own words: <em>all of them together</em>.`,draw:async(sc)=>{sc.appendChild(el('div','story','Max has 3 red marbles and 5 blue marbles. How many in all?'));await wait(800);sc.appendChild(el('div','bigword','want: <em>all together</em>'))}},
   {say:`<em>Picture</em>: draw what you know. Both parts known, the whole hidden. Now the picture tells you what to do: the parts go together.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:3,t:3,col:'var(--accent)'},{n:5,t:5}],whole:'?'});sc.appendChild(b);await wait(800);sc.appendChild(el('div','bigword','parts known, whole hidden'))}},
   {say:`<em>Solve</em> comes fourth, and it is the easy part. 3 and 5: <em>8</em>. The thinking was already done by the picture.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:3,t:3,col:'var(--accent)'},{n:5,t:5}],whole:8});sc.appendChild(b);sc.appendChild(el('div','bigword','3 + 5 = <em>8</em>'))}},
   {say:`<em>Check</em>: does 8 make sense? Max put two piles together, so he must have <em>more</em> than 5. He does. If you had said 2, the story would say: no, that is fewer than one pile!`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8 is more than 5 ✓'));await wait(700);sc.appendChild(el('div','bigword','2 is fewer than 5 ✗'))}},
   {say:`A story has a shape even with <em>no numbers</em>. "Lila had some stickers and gave some away." Does she have more or fewer? <em>Fewer</em>. You knew that without a single number. The shape comes first; the numbers only say how much.`,draw:async(sc)=>{sc.appendChild(el('div','story','Lila had some stickers. She gave some away.'));await wait(900);sc.appendChild(el('div','bigword','gave away → <em>fewer</em>'))}},
   {say:`The trap: grabbing the numbers and adding them. "Max has 7, Lila has 4, how many more does Max have?" is <em>not</em> 11. Nobody put the piles together. Read what <em>happened</em>, not what numbers are there.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','7 + 4 = 11 ✗'));await wait(700);sc.appendChild(el('div','bigword','the gap: 7 − 4 = <em>3</em> ✓'))}},
   {say:`Where you meet it: every story in the Stories door, every puzzle at school, and real life. "We need 6 plates and have 4." Know: need 6, have 4. Want: how many more. Picture: two bars. Solve: 2. Check: fewer than 6, yes.`,draw:async(sc)=>{const b=el('div','nline');b.innerHTML=barSvg({compare:[{n:6,t:'need 6'},{n:4,t:'have 4'}],gap:'?'});sc.appendChild(b);sc.appendChild(el('div','bigword','<em>2</em> more plates'))}},
   {say:`Your turn! No numbers. Read it and tap: more, fewer, or the same. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const st=el('div','story','');const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(st,r,big);const next=()=>{const d=detectiveStory(1,KID(),'marbles');if(d.opts[0]!=='more'){next();return}st.textContent=d.text;big.textContent='';r.innerHTML='';shuffle(d.opts).forEach(o=>{const btn=el('button','choice',o);btn.onclick=()=>{if(o===d.ans){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':`<em>${d.ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{btn.classList.add('miss');btn.disabled=true;big.textContent=d.why;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`Your turn again. Read the story and tap <em>what it is asking</em>, not the answer. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const st=el('div','story','');const big=el('div','bigword','');const r=el('div','row');r.classList.add('cards');sc.append(st,r,big);const next=()=>{const d=detectiveStory(2,KID(),'marbles');st.textContent=d.text;big.textContent='';r.innerHTML='';shuffle([d.qs.right].concat(d.qs.wrong)).forEach(o=>{const btn=el('button','choice',o);btn.onclick=()=>{if(o===d.qs.right){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':'<em>That</em> is the question.';if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{btn.classList.add('miss');btn.disabled=true;big.textContent='Read the last sentence again.';bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Bars that tell a story</em> (the picture step), <em>Walking backwards</em> (when the ? is at the start) and <em>How far apart</em> (when the story says "more than"). Know, want, picture, solve, check.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','know · want · picture'));sc.appendChild(el('div','bigword','solve · <em>check</em>'))}}
  ],
  tries:()=>{const kind=pick(['none','none','ask','check']);
   if(kind==='none'){const d=detectiveStory(1,KID(),'marbles');return{q:d.text,kind:'choice',opts:shuffle(d.opts),ans:d.ans,draw:()=>{},explain:d.why}}
   if(kind==='ask'){const d=detectiveStory(2,KID(),'marbles');return{q:`"${d.text}" What is it asking?`,kind:'choice',opts:shuffle([d.qs.right].concat(d.qs.wrong)),ans:d.qs.right,draw:()=>{},explain:`The question is the last sentence: ${d.qs.right}`}}
   const a=rnd(2,5),b=rnd(a+1,a+5);return{q:`${KID()} has ${a} red and ${b} blue. ${P().s[0].toUpperCase()+P().s.slice(1)} ${vb('says','say')} "${a+b+b}" in all. Does that make sense?`,kind:'choice',opts:['yes','no'],ans:'no',draw:st=>st.appendChild(el('div','bigword',`${a} and ${b}`)),explain:`${a} and ${b} together is ${a+b}. Check: more than ${b}, yes, but ${a+b+b} is far too many.`}}},
 {id:'views',strand:'Shapes',title:'Top, front and side',line:'One stack, many pictures',door:'space',thing:'marbles',book:'learned what the top, front and side views of a stack are',
  pages:[
   {say:`Here is the whole idea in one sentence. A stack of cubes is <em>one thing</em>, but it makes a <em>different picture</em> from every place you stand. Watch it turn.`,draw:async(sc)=>{const d=el('div','spin');sc.appendChild(d);const hm=[[1,2],[2,1]];const stop=spinCubes(d,hm,{step:1.2});await wait(4000);stop();d.replaceWith(turnable(hm,{width:220}))}},
   {say:`Every face has a colour. <em>Yellow</em> is a top. <em>Blue</em> is a front. <em>Green</em> is a side. Stand in <em>front</em> and look straight at it: you see only blue faces, like a wall. This is the <em>front view</em>. Tall towers hide short ones behind them.`,draw:async(sc)=>{const hm=[[1,2],[2,1]];const d=el('div','spin');d.innerHTML=view3d(hm,30,28,{width:200});sc.appendChild(d);await wait(900);const r=viewRow(hm,['front'],160);sc.appendChild(r)}},
   {say:`Walk round to the <em>side</em>. Now a <em>green</em> wall. Towers that were behind each other are side by side. This is the <em>side view</em>.`,draw:async(sc)=>{const hm=[[1,2],[2,1]];const d=el('div','spin');d.innerHTML=view3d(hm,30,28,{width:200});sc.appendChild(d);await wait(900);sc.appendChild(viewRow(hm,['side'],160))}},
   {say:`Now fly up like a bird and look straight <em>down</em>. Only <em>yellow</em> tops. Every tower is a square, tall or short, and the number on it says how tall. This is the <em>top view</em>, the one that tells you <em>how many towers</em> there are.`,draw:async(sc)=>{const hm=[[1,2],[2,1]];const d=el('div','spin');d.innerHTML=view3d(hm,30,28,{width:200});sc.appendChild(d);await wait(900);sc.appendChild(viewRow(hm,['top'],160));sc.appendChild(el('div','bigword','4 squares = <em>4 towers</em>'))}},
   {say:`All three together. Same stack, three pictures. Builders and engineers draw all three, because one picture is never enough to know a shape.`,draw:async(sc)=>{const hm=[[1,2],[2,1]];sc.appendChild(viewRow(hm,['front','side','top'],105))}},
   {say:`The rule: the <em>top view</em> tells you how many towers. The <em>front view</em> tells you how tall the tallest tower in each column is. Together they tell you almost everything about the stack.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','top → <em>how many towers</em>'));await wait(600);sc.appendChild(el('div','bigword','front → <em>how tall</em>'))}},
   {say:`<em>Why</em> cubes hide: a tall tower in front is like a wall. Everything behind it, shorter than it, is out of sight. Turn the stack and the hidden ones come out.`,draw:async(sc)=>{const hm=[[1,0,1],[0,0,0],[2,2,2]];const d=el('div','spin');sc.appendChild(d);d.innerHTML=view3d(hm,0,10,{width:220});sc.appendChild(el('div','bigword','from the front: a wall of 3'));await wait(1600);const stop=spinCubes(d,hm,{from:0,once:true,width:220});sc.onLeave=stop;await wait(1500);sc.lastChild.innerHTML='turn it: <em>2 more</em> at the back'}},
   {say:`The trap: counting only what you can see. From the corner this stack shows 6 cube tops, but one tower is 3 high: under every top there is a whole tower standing on the floor. Count towers, not faces.`,draw:async(sc)=>{const hm=[[1,3],[2,1]];const d=el('div','spin');d.innerHTML=view3d(hm,30,28,{width:200,labels:true});sc.appendChild(d);sc.appendChild(el('div','bigword','1 + 3 + 2 + 1 = <em>7</em>'))}},
   {say:`Where you meet it: a city from an aeroplane window is a top view. A photo of a house is a front view. Lego instructions show the corner view so you can see three sides at once.`,draw:async(sc)=>{const hm=[[2,1,3],[1,2,1]];sc.appendChild(viewRow(hm,['top','front','iso'],105))}},
   {say:`Your turn! Turn the stack yourself. Drag it round with your finger, or tap <em>front</em>, <em>side</em> and <em>top</em>. Find the cube that hides behind the tall tower.`,draw:async(sc)=>{sc.appendChild(turnable([[1,2,1],[3,0,1]],{width:260}))}},
   {say:`Your turn again. Here is a stack from the corner. Tap its <em>top view</em>. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const d=el('div','spin');const big=el('div','bigword','');const r=el('div','row');sc.append(d,r,big);const next=()=>{let hm;do{hm=[[rnd(0,2),rnd(1,2)],[rnd(1,3),rnd(0,2)]]}while(hm.flat().filter(Boolean).length<2);d.innerHTML=view3d(hm,30,28,{width:200});const wrong1=hm.map(r=>r.map(v=>v?0:1));const wrong2=[[hm[1][1],hm[0][0]],[hm[0][1],hm[1][0]]];const opts=shuffle([{hm,ok:true},{hm:wrong1,ok:false},{hm:wrong2,ok:false}].filter(o=>o.hm.flat().some(Boolean)));if(!opts.some(o=>o.ok))opts.push({hm,ok:true});r.innerHTML='';big.textContent='';opts.forEach(o=>{const btn=el('button','choice');const v=el('div','vcard');v.innerHTML=view3d(o.hm,0,90,{width:80,fixed:[-35,-35,70,70]});btn.appendChild(v);btn.onclick=()=>{if(o.ok){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':'<em>Yes</em>, that is the top.';if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{btn.classList.add('miss');btn.disabled=true;big.textContent=JSON.stringify(o.hm)===JSON.stringify(wrong1)?'Those squares are where the gaps are.':'That one is twisted round. Look where the tall tower stands.';bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Count the cubes</em> (count the towers from the top, then their heights), <em>Build the stack</em> (the views backwards: build what they show), and a map: a map is the top view of a town.`,draw:async(sc)=>{const hm=[[2,1],[1,2]];sc.appendChild(viewRow(hm,['iso','top'],120))}}
  ],
  tries:()=>{const kind=pick(['towers','top','hidden']);let hm;do{hm=[[rnd(0,2),rnd(1,3)],[rnd(1,3),rnd(0,2)]]}while(hm.flat().filter(Boolean).length<2);const towers=hm.flat().filter(Boolean).length;
   if(kind==='towers')return{q:'How many towers are in this stack? Count the squares in the top view.',kind:'num',ans:towers,draw:st=>st.appendChild(viewRow(hm,['top','iso'],120)),explain:`The top view shows ${towers} squares: ${towers} towers.`};
   if(kind==='top')return{q:'Which view is the top view?',kind:'choice',opts:['the one with only squares','the one with a wall of cubes'],ans:'the one with only squares',draw:st=>st.appendChild(viewRow(hm,['top','front'],120)),explain:'From above every tower is a square, tall or short.'};
   return{q:'A tall tower stands in front of a short one. From the front, can you see the short one?',kind:'choice',opts:['no, it is hidden','yes, always'],ans:'no, it is hidden',draw:st=>{const d=el('div','spin');d.innerHTML=view3d([[1],[2]],0,0,{width:120});st.appendChild(d)},explain:'The tall tower is a wall. Turn the stack or look from above to find the short one.'}}},
 {id:'allsome',strand:'Ways of thinking',title:'All, some, none',line:'Three little words that do big work',door:'think',thing:'marbles',book:'learned what all, some and none really mean',
  pages:[
   {say:`Here is the whole idea in one sentence. <em>All</em> means every single one, <em>some</em> means at least one, and <em>none</em> means not even one. Three little words, and each one is a promise about a whole group.`,draw:async(sc)=>{sc.innerHTML=ballRow(['red','red','red','red','red']);sc.appendChild(el('div','bigword','all red'))}},
   {say:`<em>All</em> the balls are red. Check every one. Yes, yes, yes, yes, yes. "All" is true only when not a single one breaks it.`,draw:async(sc)=>{sc.innerHTML=ballRow(['red','red','red','red','red']);await wait(600);sc.appendChild(el('div','bigword','5 of 5: <em>all</em>'))}},
   {say:`One blue ball, and "all red" is <em>broken</em>. It takes only one to break "all". Now the true word is <em>some</em>: some are red.`,draw:async(sc)=>{sc.innerHTML=ballRow(['red','red','blue','red','red']);await wait(600);sc.appendChild(el('div','bigword','not all. <em>some</em> are red'))}},
   {say:`<em>Some</em> is a sneaky word. It means at least one. One red ball out of five? Some are red. Four out of five? Also some. Even all five: still true, just a weak way to say it.`,draw:async(sc)=>{sc.innerHTML=ballRow(['red','blue','blue','blue','blue']);sc.appendChild(el('div','bigword','1 of 5: <em>some</em>'));await wait(700);sc.innerHTML+=ballRow(['red','red','red','red','blue']);sc.appendChild(el('div','bigword','4 of 5: still <em>some</em>'))}},
   {say:`<em>None</em> means not even one. "None of the balls are green." Look at each ball: red, blue, red, blue, red. Not one green. None is true.`,draw:async(sc)=>{sc.innerHTML=ballRow(['red','blue','red','blue','red']);await wait(600);sc.appendChild(el('div','bigword','0 green: <em>none</em>'))}},
   {say:`The rule: <em>all</em> needs every one. <em>Some</em> needs just one. <em>None</em> needs zero. To check "all", you must look at every ball. To check "some", one is enough.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','all → every one'));sc.appendChild(el('div','bigword','some → at least one'));sc.appendChild(el('div','bigword','none → not even one'))}},
   {say:`<em>Why</em> it matters: a rule about a whole group is strong. "All ladybugs have spots" tells you about every ladybug in the world. But the rule points one way only. Spots do not tell you it is a ladybug; butterflies have spots too.`,draw:async(sc)=>{sc.appendChild(el('div','emo','🐞 → spots'));sc.appendChild(el('div','emo','spots → 🐞? 🦋? 🐸?'))}},
   {say:`The trap: hearing "all" when the word was "some". "Some children have hats, Max is a child, so Max has a hat." No! Some leaves room for Max to be one without. Listen for the first word.`,draw:async(sc)=>{sc.appendChild(el('div','emo','🎩🎩🧒🧒'));sc.appendChild(el('div','bigword','some have hats: Max <em>maybe</em>'))}},
   {say:`Where you meet it: "all the lights are off", "some of the cookies are gone", "none of my socks match". Grown-ups say these every day, and each one is a tiny logic puzzle.`,draw:async(sc)=>{sc.appendChild(el('div','emo','💡💡💡 🍪🍪 🧦🧦'))}},
   {say:`Your turn! Look at the balls and tap the true word. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const pic=el('div');const big=el('div','bigword','');const r=el('div','row');r.style.gap='8px';sc.append(pic,r,big);const next=()=>{const main=pick(BALLS)[0];const n=5;const k=pick([0,1,3,5]);const cols=shuffle(Array.from({length:n},(_,i)=>i<k?main:pick(BALLS.filter(b=>b[0]!==main))[0]));pic.innerHTML=ballRow(cols);const ans=k===5?'all':k===0?'none':'some';big.innerHTML=`How many are ${main}?`;r.innerHTML='';['all','some','none'].forEach(w=>{const b=el('button','choice',`${w} are ${main}`);b.onclick=()=>{if(w===ans){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':`<em>${ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{b.classList.add('miss');b.disabled=true;big.textContent=w==='all'?'All means every one. Look again.':w==='none'?'None means not even one. Look again.':'Some means at least one. Is there one?';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>True or not?</em> in the Think door, and the same as <em>Even and odd</em>: "can they all find a partner?" is an all-question.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','all · some · none'))}}
  ],
  tries:()=>{const main=pick(BALLS)[0];const k=pick([0,1,2,5]);const cols=shuffle(Array.from({length:5},(_,i)=>i<k?main:pick(BALLS.filter(b=>b[0]!==main))[0]));const ans=k===5?'all':k===0?'none':'some';return{q:`Which word is true about ${main}?`,kind:'choice',opts:['all','some','none'],ans,draw:st=>{st.innerHTML=ballRow(cols)},explain:ans==='all'?`Every ball is ${main}: all.`:ans==='none'?`Not one ball is ${main}: none.`:`${k} of 5 are ${main}: some.`}}},
 {id:'everyway',strand:'Ways of thinking',title:'Every way, in order',line:'How to be sure you found them all',door:'think',thing:'marbles',book:'learned how to find every way without missing one',
  pages:[
   {say:`Here is the whole idea in one sentence. When you must find <em>every</em> way, do not hunt around: go in <em>order</em>, and you will miss none and repeat none. Two shirts and two hats. How many outfits?`,draw:async(sc)=>{sc.appendChild(el('div','emo','👕 🎽'));sc.appendChild(el('div','emo','🎩 🧢'))}},
   {say:`The hunting way: "this one and that one… and this… did I do that one?" You lose track. The <em>order</em> way: take the first shirt and try it with <em>every</em> hat.`,draw:async(sc)=>{sc.appendChild(el('div','emo','👕🎩'));await wait(600);sc.appendChild(el('div','emo','👕🧢'));sc.appendChild(el('div','bigword','first shirt: done'))}},
   {say:`Then the second shirt with every hat. Now you can <em>see</em> you are finished: every shirt has had every hat. 2 and 2 make 4 outfits.`,draw:async(sc)=>{sc.appendChild(el('div','emo','👕🎩 👕🧢'));await wait(500);sc.appendChild(el('div','emo','🎽🎩 🎽🧢'));sc.appendChild(el('div','bigword','2 + 2 = <em>4</em>'))}},
   {say:`A table shows the order. Shirts down the side, hats across the top. Every box is one outfit. Count the boxes: no counting one by one needed, just rows times across.`,draw:async(sc)=>{const g=el('div','cgrid');g.style.gridTemplateColumns='auto 1fr 1fr';g.innerHTML='<div></div><div class="chead emo">🎩</div><div class="chead emo">🧢</div><div class="chead emo">👕</div><div class="ccell got"><span class="emo">👕🎩</span></div><div class="ccell got"><span class="emo">👕🧢</span></div><div class="chead emo">🎽</div><div class="ccell got"><span class="emo">🎽🎩</span></div><div class="ccell got"><span class="emo">🎽🧢</span></div>';sc.appendChild(g)}},
   {say:`Sometimes two ways are secretly the <em>same</em>. A strawberry scoop with a chocolate scoop is the same cone as chocolate with strawberry. In order, you say "strawberry with everything after it, then chocolate with everything after it", and you never count a cone twice.`,draw:async(sc)=>{sc.appendChild(el('div','emo','🍓🍫 🍓🍋'));sc.appendChild(el('div','emo','🍫🍋'));sc.appendChild(el('div','bigword','3 cones, not 6'))}},
   {say:`Sometimes order <em>matters</em>. Three cars parking in a row: red first, then the other two can swap. Red first gives 2 ways, yellow first 2, blue first 2. Six orders.`,draw:async(sc)=>{sc.appendChild(el('div','emo','🚗🚕🚙 🚗🚙🚕'));sc.appendChild(el('div','emo','🚕🚗🚙 🚕🚙🚗'));sc.appendChild(el('div','emo','🚙🚗🚕 🚙🚕🚗'));sc.appendChild(el('div','bigword','2 + 2 + 2 = <em>6</em>'))}},
   {say:`The rule: fix the first thing, run through all the rest, then change the first thing. Say it like a song: "first with everything, second with everything…"`,draw:async(sc)=>{sc.appendChild(el('div','bigword','first with everything'));sc.appendChild(el('div','bigword','then the next with everything'))}},
   {say:`The trap: stopping when it <em>feels</em> like a lot. "I found five, that must be all." Feelings cannot count. The table can: an empty box means a missing way.`,draw:async(sc)=>{const g=el('div','cgrid');g.style.gridTemplateColumns='auto 1fr 1fr 1fr';g.innerHTML='<div></div><div class="chead emo">🎩</div><div class="chead emo">🧢</div><div class="chead emo">👒</div><div class="chead emo">👕</div><div class="ccell got"><span class="emo">👕🎩</span></div><div class="ccell got"><span class="emo">👕🧢</span></div><div class="ccell got"><span class="emo">👕👒</span></div><div class="chead emo">🎽</div><div class="ccell got"><span class="emo">🎽🎩</span></div><div class="ccell got"><span class="emo">🎽🧢</span></div><div class="ccell"></div>';sc.appendChild(g);sc.appendChild(el('div','bigword','one box empty: <em>one more</em>'))}},
   {say:`Your turn! Tap how many ways. Think in rows: how many of the first thing, times how many of the second. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const big=el('div','bigword','');const pic=el('div');const r=el('div','row');r.style.gap='8px';sc.append(pic,big,r);const next=()=>{const a=rnd(2,3),b=rnd(2,4);pic.innerHTML=`<div class="emo">${'👕'.repeat(a)}</div><div class="emo">${'🎩'.repeat(b)}</div>`;big.innerHTML=`${a} shirts, ${b} hats: how many outfits?`;const ans=a*b;const opts=shuffle([ans,a+b,ans+1,Math.max(1,ans-2)].filter((v,i,x)=>x.indexOf(v)===i)).slice(0,4);if(!opts.includes(ans))opts[0]=ans;r.innerHTML='';opts.forEach(v=>{const btn=el('button','choice',v);btn.onclick=()=>{if(v===ans){btn.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?`${Array.from({length:a},()=>b).join(' + ')} = <em>${ans}</em>. You have it!`:`${Array.from({length:a},()=>b).join(' + ')} = <em>${ans}</em>`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{btn.classList.add('miss');btn.disabled=true;big.innerHTML=v===a+b?'Not added. Each shirt goes with every hat.':`Each of the ${a} shirts gets ${b} hats.`;bugs('think')}};r.appendChild(btn)})};next()}},
   {say:`It's the same as <em>Find every way</em> in the Think door, <em>How many ways?</em> in Stories, and the same as <em>Equal groups</em>: a table is rows of equal groups.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','rows × across'))}}
  ],
  tries:()=>{const kind=pick(['count','same','order']);if(kind==='count'){const a=rnd(2,3),b=rnd(2,3);return{q:`${a} shirts and ${b} hats. How many outfits?`,kind:'num',ans:a*b,draw:st=>{st.innerHTML=`<div class="emo">${'👕'.repeat(a)}</div><div class="emo">${'🎩'.repeat(b)}</div>`},explain:`Each of the ${a} shirts with each of the ${b} hats: ${a*b}.`}}
   if(kind==='same')return{q:'A strawberry scoop with a chocolate scoop, and a chocolate scoop with a strawberry scoop. How many different cones?',kind:'choice',opts:['1, they are the same cone','2'],ans:'1, they are the same cone',draw:st=>{st.innerHTML='<div class="emo">🍓🍫 🍫🍓</div>'},explain:'Swapping the scoops does not make a new cone.'};
   return{q:'To find every way without missing one, you…',kind:'choice',opts:['go in order: first with everything, then the next','try ones at random until it feels like enough'],ans:'go in order: first with everything, then the next',draw:()=>{},explain:'Order is how you know you are finished.'}}},
 {id:'catch',strand:'Ways of thinking',title:'How to catch a mistake',line:'Checking is a skill, not a punishment',door:'think',thing:'marbles',book:'learned how to check an answer and catch a slip',
  pages:[
   {say:`Here is the whole idea in one sentence. An answer is not finished when you say it. It is finished when you have <em>checked</em> it. Checking is a skill, like counting, and the best thinkers do it every time.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','answer, then <em>check</em>'))}},
   {say:`Check one: <em>does it make sense?</em> Max had 8 and gave some away. If your answer is 11, stop. Giving away makes fewer. 11 is more. The story itself says no.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','8, gave away → 11? ✗'));await wait(600);sc.appendChild(el('div','bigword','fewer than 8 ✓'))}},
   {say:`Check two: <em>go the other way</em>. If 7 + 5 = 12, then 12 take away 5 should land back on 7. If it lands on 8, one of them is wrong. Going backwards catches the slip.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','7 + 5 = 12'));await wait(600);sc.appendChild(el('div','bigword','12 − 5 = <em>7</em> ✓'))}},
   {say:`Check three: <em>count it a different way</em>. You counted 9 dots by ones. Now count them by twos, or in rows. Same answer twice is a strong answer. Different answers mean count again.`,draw:async(sc)=>{sc.innerHTML=dotRows([{n:3},{n:3},{n:3}]);sc.appendChild(el('div','bigword','3 rows of 3: <em>9</em>'))}},
   {say:`Where slips hide: the <em>first hop</em> (counting the start as a hop), the <em>sign</em> (adding when the story took away), <em>one dot twice</em>, and the <em>wrong boxes</em> (full ones instead of empty ones).`,draw:async(sc)=>{sc.appendChild(el('div','bigword','6… 6, 7, 8? ✗'));sc.appendChild(el('div','bigword','6… 7, 8, <em>9</em> ✓'))}},
   {say:`The rule: before "I'm done", ask one question. Does it make sense? Does it work backwards? Do I get the same another way? One check is enough. No check is not.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','sense?'));sc.appendChild(el('div','bigword','backwards?'));sc.appendChild(el('div','bigword','another way?'))}},
   {say:`<em>Why</em> it is not a punishment: everyone slips. Pip slips. Grown-ups slip. The difference between a good thinker and a careless one is not fewer slips. It is more <em>catches</em>.`,draw:async(sc)=>{sc.appendChild(el('div','emo','🐞 ✗ → 🐞 ✓'))}},
   {say:`The trap: checking by doing the <em>exact same thing again</em>. If you counted the start as a hop, you will count it as a hop again. A check must be a different road.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','same road twice: same slip'));sc.appendChild(el('div','bigword','<em>different road</em>: catch'))}},
   {say:`Your turn! Pip did a sum. Tap the check that catches her slip. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const st=el('div','story','');const big=el('div','bigword','');const r=el('div','row cards');sc.append(st,r,big);const next=()=>{const kind=pick(['sense','back','count']);let text,right,wrong;if(kind==='sense'){const a=rnd(6,10),b=rnd(2,4);text=`Max had ${a} and gave ${b} away. Pip says ${a+b}.`;right='Gave away means fewer. Is the answer smaller than '+a+'?';wrong='Check it by adding again: '+a+' + '+b}else if(kind==='back'){const a=rnd(4,9),b=rnd(2,5);text=`${a} + ${b}. Pip says ${a+b-1}.`;right=`Go backwards: does ${a+b-1} take away ${b} land on ${a}?`;wrong='Say the answer again, louder'}else{const n=rnd(6,9);text=`Pip counted ${n} dots by ones and got ${n+1}.`;right='Count them another way, in twos or rows';wrong='Count by ones again, faster'}st.textContent=text;big.textContent='';r.innerHTML='';shuffle([right,wrong]).forEach(t=>{const b=el('button','choice',t);b.onclick=()=>{if(t===right){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':'<em>That</em> check catches it.';if(got>=3){bugs('happy');confetti()}else setTimeout(next,900)}else{b.classList.add('miss');b.disabled=true;big.textContent='Same road twice finds the same slip. Pick a different road.';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>Catch Pip's mistake</em> in the Think door, the <em>Does that make sense?</em> card in the story games, and the <em>Why?</em> after every right answer: a reason is a check.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','a reason is a <em>check</em>'))}}
  ],
  tries:()=>{const kind=pick(['sense','back','road']);if(kind==='sense'){const a=rnd(6,10),b=rnd(2,4);return{q:`Max had ${a} and gave ${b} away. Pip says ${a+b}. Does that make sense?`,kind:'choice',opts:['no, giving away makes fewer','yes'],ans:'no, giving away makes fewer',draw:st=>st.appendChild(el('div','bigword',`${a} → gave ${b} → ${a+b}?`)),explain:`Gave away means fewer than ${a}. ${a+b} is more.`}}
   if(kind==='back'){const a=rnd(4,9),b=rnd(2,5);return{q:`${a} + ${b} = ${a+b}. Check it backwards: ${a+b} − ${b} = ?`,kind:'num',ans:a,draw:st=>st.appendChild(el('div','bigword',`${a} + ${b} = ${a+b}`)),explain:`${a+b} − ${b} lands back on ${a}, so the sum was right.`}}
   return{q:'A good check is…',kind:'choice',opts:['a different road to the same answer','the same road again, faster'],ans:'a different road to the same answer',draw:()=>{},explain:'The same road finds the same slip. A different road catches it.'}}},
 {id:'rule',strand:'Ways of thinking',title:'Spot the rule',line:'Across, down, then both at once',door:'reason',thing:'buttons',book:'learned how to spot the rule in a picture grid',
  pages:[
   {say:`Here is the idea. A <em>rule</em> is something that changes the same way every time. In a picture grid, one rule goes <em>across</em> each row and one goes <em>down</em> each column. Find both, and you know what goes in the empty square.`,draw:async(sc)=>{const b={shape:'circle',col:'red',size:'big',count:1,fill:'solid',turn:0};sc.appendChild(mxGrid([[b,{...b,col:'blue'}],[{...b,shape:'square'},{...b,col:'blue',shape:'square'}]],[1,1],70));sc.appendChild(el('div','bigword','across <em>and</em> down'))}},
   {say:`The same idea in a picture. Put your finger on the top row and slide <em>across</em>: red circle, blue circle. Same shape, same size. Only the colour changed. That is the across rule: <em>red turns blue</em>.`,draw:async(sc)=>{const b={shape:'circle',col:'red',size:'big',count:1,fill:'solid',turn:0};const g=mxGrid([[b,{...b,col:'blue'}],[{...b,shape:'square'},{...b,col:'blue',shape:'square'}]],[1,1],70);sc.appendChild(g);const w=el('div','bigword','');sc.appendChild(w);await wait(500);g.hl('row',0,true);w.innerHTML='red turns <em>blue</em>'}},
   {say:`A second way: slide your finger <em>down</em> the first column. Red circle, red square. Same colour. Only the shape changed. That is the down rule: <em>a circle becomes a square</em>.`,draw:async(sc)=>{const b={shape:'circle',col:'red',size:'big',count:1,fill:'solid',turn:0};const g=mxGrid([[b,{...b,col:'blue'}],[{...b,shape:'square'},{...b,col:'blue',shape:'square'}]],[1,1],70);sc.appendChild(g);const w=el('div','bigword','');sc.appendChild(w);await wait(500);g.hl('col',0,true);w.innerHTML='a circle becomes a <em>square</em>'}},
   {say:`A third way: the empty square has a row <em>and</em> a column. Its row says blue. Its column says square. So it must be <em>blue and a square</em>, both at once, not just one of them.`,draw:async(sc)=>{const b={shape:'circle',col:'red',size:'big',count:1,fill:'solid',turn:0};const ans={...b,col:'blue',shape:'square'};const g=mxGrid([[b,{...b,col:'blue'}],[{...b,shape:'square'},ans]],[1,1],70);sc.appendChild(g);const w=el('div','bigword','blue <em>and</em> a square');sc.appendChild(w);await wait(900);g.fill(ans)}},
   {say:`The rule for finding the rule: <em>across first</em>, what changed? <em>Then down</em>, what changed? Then say both together: it must be this AND that. Three steps, every time.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','1. across: what changed?'));sc.appendChild(el('div','bigword','2. down: what changed?'));sc.appendChild(el('div','bigword','3. <em>both</em> at once'))}},
   {say:`<em>Why</em> it works: every row follows the same across rule, and every column follows the same down rule. So the bottom row changes just like the top row did, and the last column changes just like the first. The empty square has no choice.`,draw:async(sc)=>{const b={shape:'star',col:'green',size:'small',count:1,fill:'solid',turn:0};const g=mxGrid([[b,{...b,count:2},{...b,count:3}],[{...b,size:'mid'},{...b,size:'mid',count:2},{...b,size:'mid',count:3}],[{...b,size:'big'},{...b,size:'big',count:2},{...b,size:'big',count:3}]],[2,2],52);sc.appendChild(g);const w=el('div','bigword','');sc.appendChild(w);await wait(600);g.hl('row',0,true);w.textContent='one more each step';await wait(1100);g.hl('row',0,false);g.hl('row',1,true);w.textContent='one more each step, again';await wait(1100);g.hl('row',1,false);g.hl('col',2,true);w.innerHTML='down: it <em>grows</em>';await wait(1100);g.hl('col',2,false);g.fill({...b,size:'big',count:3});w.innerHTML='three <em>and</em> big'}},
   {say:`Two traps. The first: checking <em>one thing only</em>. "It is blue, so it must be this one": but that one is a circle, and the column says square. The second: picking the one you <em>like</em>. Pretty is not a rule.`,draw:async(sc)=>{const r=el('div','row');r.style.gap='20px';const ok={shape:'square',col:'blue',size:'big',count:1,fill:'solid',turn:0};[[{...ok,shape:'circle'},'blue, but a circle ✗'],[ok,'blue AND a square ✓']].forEach(([f,t])=>{const d=el('div');d.style.textAlign='center';d.innerHTML=mxSvg(f,80)+`<div class="instr">${t}</div>`;r.appendChild(d)});sc.appendChild(r)}},
   {say:`Where you meet it: a <em>sock drawer</em> (colours across, sizes down), a <em>calendar</em> (days across, weeks down), the <em>hundred chart</em> (one more across, ten more down). Rows and columns are everywhere, and each one has its rule.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','across: 1 more'));sc.appendChild(el('div','bigword','down: <em>10</em> more'));sc.appendChild(hundredChart([4,5,6,14,24]))}},
   {say:`Your turn! Tap the one that goes in the empty square. Across first, then down. Three in a row and you have it.`,draw:async(sc)=>{let got=0;const top=el('div'),r=el('div','row'),big=el('div','bigword','');sc.append(top,r,big);const next=()=>{const p=mxProblem(2);top.innerHTML='';top.appendChild(mxGrid(p.cells,p.miss,62));r.innerHTML='';p.choices.forEach(c=>{const b=el('button','choice');b.style.padding='6px';b.innerHTML=mxSvg(c.f,56);b.onclick=()=>{if(!c.X){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':`across, ${mxRule(p.A,p.vA)}; down, ${mxRule(p.B,p.vB)}`;if(got>=3){bugs('happy');confetti()}else setTimeout(next,1200)}else{b.classList.add('miss');b.disabled=true;big.textContent=`That one is ${mxWord(c.X,c.f[c.X])}. Check the ${c.X===p.A?'row':c.X===p.B?'column':'others: that never changes'}.`;bugs('think')}};r.appendChild(b)})};next()}},
   {say:`Now without a picture. Pip says the rules in words: "Across, red turns blue. Down, it gets big. The top left is a small red star." Tap what the bottom right must be.`,draw:async(sc)=>{let got=0;const st=el('div','story',''),r=el('div','row cards'),big=el('div','bigword','');sc.append(st,r,big);const next=()=>{const p=mxProblem(2);const f=p.cells[0][0];st.innerHTML=`Across, <b>${mxRule(p.A,p.vA)}</b>. Down, <b>${mxRule(p.B,p.vB)}</b>. The top left is ${mxDesc(f)}.`;big.textContent='';r.innerHTML='';shuffle(p.choices).forEach(c=>{const b=el('button','choice',mxDesc(c.f));b.onclick=()=>{if(!c.X){b.classList.add('hit');got++;playNote(got*4);big.innerHTML=got>=3?'You have it!':'<em>both</em> rules at once';if(got>=3){bugs('happy');confetti()}else setTimeout(next,1200)}else{b.classList.add('miss');b.disabled=true;big.textContent=c.X===p.A?'Read the across rule again.':c.X===p.B?'Read the down rule again.':'That part never changed.';bugs('think')}};r.appendChild(b)})};next()}},
   {say:`It's the same as <em>Spot the rule</em> in the Reasoning door, the <em>Rule machine</em> (one rule, every time) and <em>What comes next?</em> (the rule runs along a row). A rule is a promise: the same change, every step.`,draw:async(sc)=>{sc.appendChild(el('div','bigword','a rule is the <em>same change</em>, every step'))}}
  ],
  tries:()=>{const p=mxProblem(pick([1,2]));if(Math.random()<.5)return{q:'Which one goes in the empty square?',kind:'choice',opts:shuffle(p.choices.map(c=>mxDesc(c.f))),ans:mxDesc(p.ans),draw:st=>st.appendChild(mxGrid(p.cells,p.miss,56)),explain:`Across, ${mxRule(p.A,p.vA)}. Down, ${mxRule(p.B,p.vB)}. So it is ${mxDesc(p.ans)}.`,show:st=>{const g=st.querySelector('.mx');if(g&&g.fill)g.fill(p.ans)}};
   const other=['col','shape','size','count','fill','turn'].filter(x=>x!==p.A&&x!==p.B&&(x!=='turn'||MX_TURN.includes(p.ans.shape)));return{q:'What changes across the top row?',kind:'choice',opts:shuffle([MX_NAME[p.A],MX_NAME[p.B||pick(other)],MX_NAME[pick(other.filter(x=>x!==(p.B||'')).slice(0,3))]].filter((v,i,a)=>a.indexOf(v)===i)),ans:MX_NAME[p.A],draw:st=>st.appendChild(mxGrid(p.cells,p.miss,56)),explain:`Across the top row, ${mxRule(p.A,p.vA)}. ${MX_NAME[p.A]} is what changes.`}}},
];
function globeSvg(ang,withBug,showLabels,color){color=color||'#5aa9e6';const a=((ang%360)+360)%360;const rad=a*Math.PI/180;const bx=110+70*Math.sin(rad),by=110-70*Math.cos(rad)*0.35;const front=Math.sin(rad)>=-0.2;let h=`<svg viewBox="0 0 320 220" style="width:220px;max-width:100%"><circle cx="290" cy="110" r="26" fill="#ffc83d"/><circle cx="110" cy="110" r="72" fill="${color}"/>`;
  if(color==='#5aa9e6')h+=`<path d="M70 80q20-20 40 0t30 20q-10 20-40 10t-30-30z" fill="#4cae7c" opacity=".9"/><ellipse cx="130" cy="150" rx="22" ry="10" fill="#4cae7c" opacity=".9"/>`;
  h+=`<path d="M110 38a72 72 0 0 0 0 144z" fill="rgba(10,20,50,.55)"/>`;
  if(showLabels)h+=`<text x="190" y="110" font-size="13" fill="var(--fg)" font-family="var(--display)">midday</text><text x="10" y="110" font-size="13" fill="var(--fg)" font-family="var(--display)">midnight</text><text x="95" y="24" font-size="13" fill="var(--fg)" font-family="var(--display)">evening</text><text x="90" y="212" font-size="13" fill="var(--fg)" font-family="var(--display)">morning</text>`;
  if(withBug)h+=`<g transform="translate(${bx-12},${by-12}) scale(.4)" opacity="${front?1:.35}">${BUG}</g>`;
  return h+'</svg>'}
function handSvg(n){let h=`<svg viewBox="0 0 160 160" style="width:150px"><path d="M30 150V80M55 150V55M80 150V45M105 150V58M20 150v-30l-14-22" stroke="#f4a261" stroke-width="18" stroke-linecap="round" fill="none"/><rect x="18" y="105" width="100" height="55" rx="14" fill="#f4a261"/>`;const pts=[[30,110],[30,95],[30,80],[55,105],[55,80],[55,55],[80,100],[80,72],[80,45],[105,105],[105,82],[105,58]];pts.forEach(([x,y],i)=>{h+=`<circle cx="${x}" cy="${y}" r="7" fill="${i<n?'var(--accent)':'rgba(0,0,0,.15)'}"/>`;if(i<n)h+=`<text x="${x}" y="${y+4}" text-anchor="middle" font-size="9" fill="#fff" font-family="var(--display)">${i+1}</text>`});return h+'</svg>'}
function clockSvg(h,m,marks){const ha=(h%12)*30+m*0.5,ma=m*6;let nums='';for(let i=1;i<=12;i++){const a=i*30*Math.PI/180;nums+=`<text x="${100+78*Math.sin(a)}" y="${100-78*Math.cos(a)+6}" text-anchor="middle" font-size="16" font-family="var(--display)" font-weight="700" fill="var(--fg)">${i}</text>`;if(marks)nums+=`<text x="${100+96*Math.sin(a)}" y="${100-96*Math.cos(a)+4}" text-anchor="middle" font-size="9" fill="var(--accent)" font-family="var(--display)">${i*5}</text>`}
  let ticks='';for(let i=0;i<60;i++){const a=i*6*Math.PI/180;ticks+=`<line x1="${100+88*Math.sin(a)}" y1="${100-88*Math.cos(a)}" x2="${100+(i%5?84:80)*Math.sin(a)}" y2="${100-(i%5?84:80)*Math.cos(a)}" stroke="var(--fg)" stroke-width="${i%5?1:2}"/>`}
  return `<svg viewBox="0 0 200 200" style="width:200px;max-width:100%"><circle cx="100" cy="100" r="92" fill="var(--card)" stroke="var(--fg)" stroke-width="4"/>${ticks}${nums}<line x1="100" y1="100" x2="${100+48*Math.sin(ha*Math.PI/180)}" y2="${100-48*Math.cos(ha*Math.PI/180)}" stroke="var(--fg)" stroke-width="7" stroke-linecap="round"/><line x1="100" y1="100" x2="${100+70*Math.sin(ma*Math.PI/180)}" y2="${100-70*Math.cos(ma*Math.PI/180)}" stroke="var(--accent)" stroke-width="5" stroke-linecap="round"/><circle cx="100" cy="100" r="5" fill="var(--fg)"/></svg>`}
function scaleSvg(L,R,t){const dy=t?19.5:0;return `<svg viewBox="0 0 400 160"><path d="M200 140V30M120 140h160" stroke="var(--fg)" stroke-width="4"/><g style="transform:rotate(${t}deg);transform-origin:200px 40px"><path d="M60 40h280" stroke="var(--fg)" stroke-width="4"/></g><g style="transform:translateY(${t<0?dy:-dy}px)"><path d="M60 40v10" stroke="var(--fg)" stroke-width="3"/><rect x="15" y="50" width="90" height="60" rx="8" fill="var(--card)" stroke="var(--line)" stroke-width="2"/><text x="60" y="88" text-anchor="middle" font-size="22" font-family="var(--display)" fill="var(--fg)">${L}</text></g><g style="transform:translateY(${t<0?-dy:dy}px)"><path d="M340 40v10" stroke="var(--fg)" stroke-width="3"/><rect x="295" y="50" width="90" height="60" rx="8" fill="var(--card)" stroke="var(--line)" stroke-width="2"/><text x="340" y="88" text-anchor="middle" font-size="22" font-family="var(--display)" fill="var(--fg)">${R}</text></g></svg>`}
function hundredChart(hl){const g=el('div');g.style.cssText='display:grid;grid-template-columns:repeat(10,1fr);gap:2px;font-family:var(--display);font-size:.8rem;width:100%;max-width:340px';for(let i=1;i<=100;i++){const c=el('div','',i);const on=hl.includes(i);c.style.cssText=`text-align:center;padding:3px 0;border-radius:5px;background:${on?'var(--accent)':'rgba(255,255,255,.55)'};color:${on?'#fff':'var(--fg)'};${on?'font-weight:700':''}`;g.appendChild(c)}return g}
/* drag-and-drop: items in a tray, drop zones that accept one item each */
function makeDraggable(item,opts){item.classList.add('grab');let home=null,ox=0,oy=0,w=0,h=0;
  item.addEventListener('pointerdown',e=>{if(item.dataset.locked)return;e.preventDefault();home=item.parentElement;const r=item.getBoundingClientRect();ox=e.clientX-r.left;oy=e.clientY-r.top;w=r.width;h=r.height;
    const ph=el('div','it2');ph.style.visibility='hidden';ph.id='ph';home.insertBefore(ph,item);document.body.appendChild(item);item.classList.add('drag');item.style.width=w+'px';item.style.height=h+'px';move(e);item.setPointerCapture(e.pointerId)});
  function move(e){item.style.left=(e.clientX-ox)+'px';item.style.top=(e.clientY-oy)+'px';document.querySelectorAll('.hot').forEach(z=>z.classList.remove('hot'));const z=zoneAt(e);if(z)z.classList.add('hot')}
  function zoneAt(e){const t=document.elementFromPoint(e.clientX+w/2-ox,e.clientY+h/2-oy);const z=t&&t.closest&&t.closest('.dz, .tray');if(!z)return null;if(z.classList.contains('dz')&&z.classList.contains('full'))return null;return z}
  item.addEventListener('pointermove',e=>{if(item.classList.contains('drag'))move(e)});
  const drop=e=>{if(!item.classList.contains('drag'))return;const z=zoneAt(e);item.classList.remove('drag');item.style.cssText='';document.querySelectorAll('.hot').forEach(x=>x.classList.remove('hot'));const ph=document.getElementById('ph');
    if(z&&z!==home){if(ph)ph.remove();if(home&&home.classList.contains('dz'))home.classList.remove('full');z.appendChild(item);if(z.classList.contains('dz'))z.classList.add('full');playNote(rnd(5,15));if(opts&&opts.onDrop)opts.onDrop(z,item)}
    else{if(ph){ph.replaceWith(item)}else home.appendChild(item)}};
  item.addEventListener('pointerup',drop);item.addEventListener('pointercancel',drop)}
function trayOf(n,cls){const t=el('div','srow tray wide '+(cls||''));const items=[];for(let i=0;i<n;i++){const d=dot('');items.push(d);t.appendChild(d)}return{t,items}}
function zones(n,cls){const arr=[];for(let i=0;i<n;i++)arr.push(el('div','dz'+(cls?' '+cls:'')));return arr}
function fullCount(zs){return zs.filter(z=>z.classList.contains('full')).length}

function dotsRow2(n){const r=row('');r.classList.add('wide');r.items=[];for(let i=0;i<n;i++){const d=dot('');r.items.push(d);r.appendChild(d)}return r}
function pairUp2(n){const g=el('div','pairgrid');for(let i=0;i<n;i++){const d=dot(i===n-1&&n%2?'alone glow':'');g.appendChild(d)}return g}
function renderIdeas(){const l=$('#idealist');l.innerHTML='';const strands=['Numbers','Adding and taking','Groups','Patterns','Shapes','Measure','Time','Ways of thinking'];strands.forEach(st=>{const hs=IDEAS.filter(i=>i.strand===st);if(!hs.length)return;l.appendChild(el('h3','strand',st));hs.forEach(i=>{const b=el('button','idea'+(S.counts['idea_'+i.id]?' done':''),`<b>${i.title}</b><small>${i.line}</small>`);b.onclick=()=>openIdea(i);l.appendChild(b)})})}
let learnFromGame=false;
function openIdea(idea,fromGame){learnFromGame=!!fromGame;show('learn');$('#learnTitle').textContent=idea.title;currentThing=idea.thing||'marbles';document.querySelectorAll('#learn .readbtn').forEach(b=>b.remove());
  const box=$('#sceneInner'),bub=$('#bubble'),dots=$('#pageDots'),prev=$('#prevBtn'),next=$('#nextBtn'),tryCard=$('#tryCard');let pg=0,token=0;tryCard.hidden=true;
  $('#narrBug').innerHTML=BUG;
  async function render(){const my=++token;const page=idea.pages[pg];box.innerHTML='';const sc=el('div','sceneInner');sc.style.padding='0';sc.style.minHeight='0';box.appendChild(sc);bub.innerHTML=page.say;const rb=readBtn(()=>bub.textContent);rb.style.marginTop='6px';bub.appendChild(el('div')).appendChild(rb);
    dots.innerHTML='';idea.pages.forEach((_,i)=>dots.appendChild(el('i',i===pg?'on':'')));prev.disabled=pg===0;next.textContent=pg===idea.pages.length-1?'Try it ›':'Next ›';
    try{await page.draw(sc)}catch(e){if(my===token)console.warn('page draw failed',e)}if(my!==token)return}
  prev.onclick=()=>{if(pg>0){pg--;render()}};next.onclick=()=>{if(pg<idea.pages.length-1){pg++;render()}else{tryCard.hidden=false;tryCard.scrollIntoView({behavior:'smooth',block:'start'});startTries()}};
  render();
  function startTries(){let got=0,asked=0;const P=$('#tryPrompt'),ST=$('#tryStage'),M=$('#tryMsg'),C=$('#tryControls');
  function nextTry(){if(asked>=3){P.textContent=got===3?`Three out of three. ${KID()} gets it!`:`${got} out of 3. ${KID()} is getting it.`;ST.innerHTML='';M.textContent='';C.innerHTML='';
      S.counts['idea_'+idea.id]=(S.counts['idea_'+idea.id]||0)+1;S.log=((S.log||[]).concat({d:Date.now(),idea:idea.id})).slice(-400);addPage(`${KID()} ${idea.book}${got===3?' and got every try-it right':''}.`,got===3);save();
      const r=el('div','row');const g=el('button','btn',learnFromGame?'Back to my puzzle':`Play ${DOORS[idea.door][0]}`);g.onclick=()=>{if(learnFromGame&&S.trail){show('play');play(S.trail.steps[S.trail.i])}else startTrail(idea.door)};const a=el('button','btn quiet','Try again');a.onclick=()=>{got=0;asked=0;nextTry()};const o=el('button','btn quiet','Other ideas');o.onclick=()=>{renderIdeas();show('ideas')};r.append(g,a,o);C.appendChild(r);if(got===3){confetti();bugs('happy')}return}
    let t=null;for(let i=0;i<10&&!t;i++)t=idea.tries();asked++;P.textContent=`Try it (${asked} of 3): ${t.q}`;ST.innerHTML='';M.textContent='';M.className='msg';C.innerHTML='';t.draw(ST);let first=true;
    const finish=(ok)=>{if(ok&&first)got++;M.textContent=(ok?'Yes! ':'')+t.explain;M.className='msg'+(ok?' good':'');bugs(ok?'happy':'think');if(t.show)try{t.show(ST)}catch(e){}C.querySelectorAll('button').forEach(b=>b.disabled=true);const r=el('div','row');const n=el('button','btn','Next');n.onclick=nextTry;r.appendChild(n);C.appendChild(r)};
    if(t.kind==='choice'){const c=choices(t.opts,(o,b)=>{if(o===t.ans){b.classList.add('hit');finish(true)}else{b.classList.add('miss');b.disabled=true;if(first){first=false;M.textContent='Not that one. Look again and try the other.'}else finish(false)}});c.classList.add('bigpick');C.appendChild(c)}
    else C.appendChild(numpad((v,nm)=>{if(v===t.ans)finish(true);else if(first){first=false;M.textContent=`Not ${v}. Try once more.`}else finish(false)},3))}
  nextTry()}}




